/// Transaction-log (`.LOG1`/`.LOG2`) replay provenance for a registry hive,
/// surfaced to the frontend so the examiner can see whether the state shown is
/// the on-disk (pre-replay) or recovered (post-replay) hive. Built from the
/// additive metadata keys the registry parser stamps onto the hive record.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RegistryReplayProvenance {
    pub logs_replayed: bool,
    pub hive_dirty: bool,
    pub replay_reason: String,
    pub log_format: String,
    pub log_files: Vec<String>,
    pub primary_sequence: u32,
    pub secondary_sequence: u32,
    pub log_entries_applied: u32,
    pub dirty_pages_applied: u32,
    pub replay_sequence_start: Option<u32>,
    pub replay_sequence_end: Option<u32>,
    pub hive_last_written_before: Option<String>,
    pub hive_last_written_after: Option<String>,
    pub changed_keys: Vec<String>,
}

/// Build a [`RegistryReplayProvenance`] from a hive record's metadata. Returns
/// `None` when the record predates the replay feature (no `logs_replayed` key),
/// so old hives cleanly surface no provenance rather than a fabricated one.
fn build_registry_provenance(metadata: &serde_json::Value) -> Option<RegistryReplayProvenance> {
    // The `logs_replayed` key is the presence sentinel for the whole stamp.
    metadata.get("logs_replayed")?;
    let b = |k: &str| metadata.get(k).and_then(|v| v.as_bool()).unwrap_or(false);
    let s = |k: &str| {
        metadata
            .get(k)
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string()
    };
    let u = |k: &str| metadata.get(k).and_then(|v| v.as_u64()).unwrap_or(0) as u32;
    let opt_u = |k: &str| metadata.get(k).and_then(|v| v.as_u64()).map(|n| n as u32);
    let opt_s = |k: &str| {
        metadata
            .get(k)
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
    };
    let strings = |k: &str| {
        metadata
            .get(k)
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .filter_map(|x| x.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_default()
    };
    Some(RegistryReplayProvenance {
        logs_replayed: b("logs_replayed"),
        hive_dirty: b("hive_dirty"),
        replay_reason: s("replay_reason"),
        log_format: s("log_format"),
        log_files: strings("log_files"),
        primary_sequence: u("primary_sequence"),
        secondary_sequence: u("secondary_sequence"),
        log_entries_applied: u("log_entries_applied"),
        dirty_pages_applied: u("dirty_pages_applied"),
        replay_sequence_start: opt_u("replay_sequence_start"),
        replay_sequence_end: opt_u("replay_sequence_end"),
        hive_last_written_before: opt_s("hive_last_written_before"),
        hive_last_written_after: opt_s("hive_last_written_after"),
        changed_keys: strings("replay_changed_keys"),
    })
}

