#[derive(Debug, Serialize, Deserialize)]
pub struct FileSystemGridQuery {
    /// Present: list direct children of this folder artifact.
    /// Absent: list all FileEntry artifacts under the source (subtree).
    pub parent_id: Option<Uuid>,
    #[serde(default = "default_page")]
    pub page: u32,
    #[serde(default = "default_page_size")]
    pub page_size: u32,
    /// Case-insensitive substring match on file name.
    pub name: Option<String>,
    /// Extension suffix match (leading dot optional).
    pub extension: Option<String>,
    /// Comma-separated list of extensions; matches any of them. Lets one
    /// request cover a media class (every picture type) instead of one request
    /// per extension.
    pub extensions: Option<String>,
    /// Only entries marked deleted.
    #[serde(default)]
    pub deleted_only: bool,
    /// Only entries that can be **shown** to be one of a kind: no other
    /// artifact in the case carries their SHA-256 (§2.8).
    ///
    /// A file with no hash is set aside rather than listed: it cannot be shown
    /// to be unique, and listing it here would present an unknown as a
    /// finding. The response reports how many were set aside.
    #[serde(default)]
    pub unique_only: bool,
    /// "only" = directories only, "exclude" = files only, absent = both.
    pub dirs: Option<String>,
    /// Sort column: name | size | modified | created (default name).
    pub sort: Option<String>,
    /// Sort direction: asc | desc (default asc).
    pub order: Option<String>,
    /// Filter by hash-set match status: "notable" | "known" | "unknown".
    pub known: Option<String>,
    /// Include each entry's full metadata document.
    #[serde(default)]
    pub include_metadata: bool,
    /// List immediate children of this directory path, deriving the tree from
    /// the `path` column rather than parent_id (parsers store files flat under
    /// the FileSystem artifact). An empty string lists the filesystem root.
    /// When present, overrides parent_id.
    pub path: Option<String>,
    /// List a SAVED COMPOUND FILTER's population in this grid.
    ///
    /// The filter is resolved to a set of artifact ids by the same evaluator
    /// `/filters/:id/apply` uses, and the grid then lists exactly that set —
    /// with the grid's own paging, sort, selection and export, which the apply
    /// endpoint's listing never had. Every other parameter still applies and
    /// NARROWS the population further; nothing here widens it.
    ///
    /// The population is bounded (`FILTER_POPULATION_MAX_IDS`) and the scan
    /// behind it is bounded, so the response carries a `filter` block reporting
    /// both, plus the `scan_complete` and `undecodable` flags the apply path
    /// reports. A grid that lists part of a filter's matches must say so.
    pub filter_id: Option<Uuid>,
}

fn default_page() -> u32 {
    1
}
fn default_page_size() -> u32 {
    100
}

/// Maximum page size for the files listing.
const FILES_MAX_PAGE_SIZE: u32 = 500;

/// Maximum page size for the timeline listing. Bounds a single response so a
/// client cannot request an unbounded page of events.
const TIMELINE_MAX_PAGE_SIZE: i64 = 1000;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FileSystemGridItem {
    pub id: Uuid,
    pub parent_id: Option<Uuid>,
    pub name: String,
    pub path: Option<String>,
    pub extension: Option<String>,
    pub size: Option<i64>,
    pub created: Option<String>,
    pub modified: Option<String>,
    pub accessed: Option<String>,
    pub is_directory: bool,
    pub is_deleted: bool,
    /// Hash-set match status: "notable" | "known" | null (no match).
    pub known_status: Option<String>,
    /// Full metadata document; present only when include_metadata=true.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub metadata: Option<serde_json::Value>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct FileSystemGridResponse {
    pub items: Vec<FileSystemGridItem>,
    /// Rows matching the scope, the grid's filters AND — when one was named —
    /// the saved filter's population.
    pub total_count: u64,
    pub page: u32,
    pub page_size: u32,
    pub total_pages: u32,
    pub has_next: bool,
    pub has_previous: bool,
    /// Present only when the grid was opened on a saved filter. Absent means no
    /// filter was applied, never "a filter was applied and everything was fine".
    #[serde(skip_serializing_if = "Option::is_none")]
    pub filter: Option<FilterPopulationDisclosure>,
    /// Present only under `unique_only` (§2.8): what that filter could not
    /// assess. Absent means the filter was not applied — never "it was applied
    /// and nothing was set aside".
    #[serde(skip_serializing_if = "Option::is_none")]
    pub unique: Option<UniqueOnlyDisclosure>,
}

/// What "show unique only" set aside, and why.
///
/// Uniqueness is decided by SHA-256, so a file that carries no hash cannot be
/// shown to be one of a kind. Listing it anyway would present an unknown as a
/// finding; excluding it silently would make the grid's count read as "the
/// case holds this many unique files" when it is "this many could be shown to
/// be unique". So the count of what was set aside travels with the grid.
#[derive(Debug, Serialize, Deserialize)]
pub struct UniqueOnlyDisclosure {
    /// Files in this scope carrying no SHA-256, and so excluded from the
    /// listing: their uniqueness is unknown, not disproved.
    pub unassessable: u64,
    /// The sentence a screen should show when `unassessable` is non-zero.
    pub note: String,
}

/// What a grid opened on a saved filter has to say about the population it is
/// showing.
///
/// A filtered grid is a population-defining instrument pointed at a screen full
/// of rows an examiner will bulk-tag, export and testify about. Three separate
/// things can make it short of the filter's real matches, they are repaired by
/// three different actions, and so they are carried as three separate fields
/// rather than one "incomplete" flag:
///
///   * the SCAN stopped at its ceiling (`scan_complete` false) — matches past it
///     were never examined, and `matched` is a lower bound;
///   * the POPULATION was larger than the grid will list (`population_capped`) —
///     the matches exist and were counted, but this grid holds only the first
///     `population_cap` of them;
///   * rows inside the scan could not be evaluated (`undecodable`) — the filter
///     was never tested against them, so they are neither matches nor
///     established non-matches, and no amount of paging recovers them.
#[derive(Debug, Serialize, Deserialize)]
pub struct FilterPopulationDisclosure {
    pub filter_id: Uuid,
    pub filter_name: String,
    /// Artifacts the filter matched, of EVERY type. A lower bound when
    /// `scan_complete` is false.
    pub matched: u64,
    /// How many of `matched` this grid can list: the file grid shows FileEntry
    /// rows only, so a filter that also matched registry records or messages
    /// legitimately lists fewer rows than it matched. The difference is stated
    /// rather than left to look like rows going missing.
    pub listed: u64,
    pub scan_complete: bool,
    pub undecodable: u64,
    pub population_capped: bool,
    pub population_cap: usize,
    pub inventory_incomplete: bool,
    /// A closed vocabulary; see [`filter_population_reason`].
    pub inventory_incomplete_reason: Option<String>,
}

#[derive(Debug)]
pub enum ApiError {
    InvalidRequest(String),
    ValidationError(String),
    ResourceNotFound(String),
    /// The caller is authenticated but not authorized for this resource
    /// (403). Used by per-case access control.
    Forbidden(String),
    InternalServerError(String),
    PayloadTooLarge(String),
    /// The request was valid and the data exists, but the complete answer is
    /// larger than this endpoint will return, and the endpoint refuses to
    /// return a silent subset instead.
    ///
    /// Distinct from [`ApiError::InternalServerError`] because that variant
    /// deliberately replaces its message with a correlation id before it
    /// reaches the client (it often embeds sqlx/IO detail and server paths).
    /// A ceiling disclosure has the opposite requirement: the message names
    /// the ceiling and the exports that do disclose their own, and it is the
    /// only thing an examiner can act on. Routing one through
    /// `InternalServerError` turns "this case holds more GPS fixes than the
    /// map will draw" into "An internal error occurred (reference 3f2a91b0)",
    /// which reads as a broken server rather than a bounded answer.
    ResultTooLarge(String),
    /// The request was valid and the caller entitled to make it, but the
    /// process is already doing as much of this work as it will do at once
    /// (503). Nothing was started and nothing was changed, so the caller can
    /// simply retry. See [`SEARCH_REPAIR_SLOTS`].
    SystemOverload(String),
}

impl std::fmt::Display for ApiError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ApiError::InvalidRequest(msg) => write!(f, "Invalid request: {}", msg),
            ApiError::ValidationError(msg) => write!(f, "Validation error: {}", msg),
            ApiError::ResourceNotFound(msg) => write!(f, "Resource not found: {}", msg),
            ApiError::Forbidden(msg) => write!(f, "Forbidden: {}", msg),
            ApiError::InternalServerError(msg) => write!(f, "Internal server error: {}", msg),
            ApiError::PayloadTooLarge(msg) => write!(f, "Payload too large: {}", msg),
            ApiError::ResultTooLarge(msg) => write!(f, "Result too large: {}", msg),
            ApiError::SystemOverload(msg) => write!(f, "System overload: {}", msg),
        }
    }
}

impl std::error::Error for ApiError {}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let (status, code, message) = match self {
            ApiError::InvalidRequest(msg) => (StatusCode::BAD_REQUEST, "INVALID_REQUEST", msg),
            ApiError::ValidationError(msg) => {
                (StatusCode::UNPROCESSABLE_ENTITY, "VALIDATION_ERROR", msg)
            }
            ApiError::ResourceNotFound(msg) => (StatusCode::NOT_FOUND, "RESOURCE_NOT_FOUND", msg),
            ApiError::Forbidden(msg) => (StatusCode::FORBIDDEN, "FORBIDDEN", msg),
            // Internal errors often embed raw sqlx/IO detail and server paths.
            // Log the full detail server-side under a correlation id and return
            // only that id to the client, so operators can trace it without
            // leaking internals over the wire.
            ApiError::InternalServerError(msg) => {
                let error_id = uuid::Uuid::new_v4().simple().to_string();
                error!("Internal server error [{}]: {}", error_id, msg);
                (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "JOB_FAILED",
                    format!("An internal error occurred (reference {}).", &error_id[..8]),
                )
            }
            ApiError::PayloadTooLarge(msg) => {
                (StatusCode::PAYLOAD_TOO_LARGE, "PAYLOAD_TOO_LARGE", msg)
            }
            // The message is a ceiling disclosure written for the examiner, so
            // it is passed through verbatim rather than swapped for a
            // correlation id. 507 keeps it distinguishable from both a client
            // mistake (4xx) and a server fault (500): the request was fine and
            // the server is fine, the answer is simply larger than this
            // endpoint will serve.
            ApiError::ResultTooLarge(msg) => {
                (StatusCode::INSUFFICIENT_STORAGE, "RESULT_TOO_LARGE", msg)
            }
            ApiError::SystemOverload(msg) => {
                (StatusCode::SERVICE_UNAVAILABLE, "SYSTEM_OVERLOAD", msg)
            }
        };

        let body = Json(ErrorResponse {
            error: ApiErrorData {
                code: code.to_string(),
                message,
                details: None,
            },
        });

        (status, body).into_response()
    }
}

// --- Evidence root confinement (H6) ---

/// Confines server-side file access (ingest, filesystem browsing, artifact
/// content/hex/verify) to an allowlist of evidence root directories,
/// configured via `SEANCE_EVIDENCE_ROOTS` (absolute paths separated by `:` or `;`).
///
/// Default: when the variable is unset the policy FAILS CLOSED to the process
/// working directory, with a prominent warning at startup. Seance is primarily
/// a local workstation tool, so the launch directory keeps the common "evidence
/// under the launch dir" case working, but nothing outside it is readable.
/// Unrestricted access to the host filesystem happens only when an operator
/// sets `SEANCE_ALLOW_UNRESTRICTED_FS=true`. Any multi-user or network-exposed
/// deployment should set SEANCE_EVIDENCE_ROOTS to the evidence directories.
#[derive(Clone, Debug, Default)]
pub struct EvidenceRootPolicy {
    /// True when SEANCE_EVIDENCE_ROOTS (or an explicit root list) was
    /// provided. Kept separate from `roots` so a configured-but-empty list
    /// fails closed (denies everything) instead of silently allowing all.
    restricted: bool,
    /// Canonicalized allowed roots.
    roots: Vec<std::path::PathBuf>,
}

impl EvidenceRootPolicy {
    /// Unrestricted policy: every path is allowed (legacy behavior).
    pub fn unrestricted() -> Self {
        Self::default()
    }

    /// Restrict access to the given roots. Roots that cannot be
    /// canonicalized (e.g. do not exist) are skipped with an error log;
    /// paths under a skipped root are therefore DENIED (fail closed).
    pub fn restricted_to(roots: Vec<std::path::PathBuf>) -> Self {
        let mut canonical = Vec::new();
        for root in roots {
            match root.canonicalize() {
                Ok(c) => canonical.push(c),
                Err(e) => error!(
                    "Ignoring invalid evidence root {:?}: {}. Paths under it will be denied.",
                    root, e
                ),
            }
        }
        Self {
            restricted: true,
            roots: canonical,
        }
    }

    /// Build from the SEANCE_EVIDENCE_ROOTS environment variable (absolute
    /// paths separated by `:` or `;`). Unset or empty confines access to the
    /// process working directory, with a prominent startup warning; only
    /// `SEANCE_ALLOW_UNRESTRICTED_FS=true` opens the whole filesystem.
    ///
    /// Parsed by `seance_memory::analysis::split_env_list`, the same rule every
    /// other Séance environment list uses, rather than by a bare `split(':')`.
    /// That was MEM-006's defect and this was the last copy of it: a raw colon
    /// split cuts `D:\evidence` into `D` and `\evidence`, neither of which
    /// canonicalises, and since this policy fails closed the operator ends up
    /// with a server that can open nothing under the drive it was pointed at.
    /// The parse is structural rather than platform-dependent on purpose — an
    /// evidence-root list travels with the case notes, and one an examiner
    /// wrote on Windows has to mean the same thing on the Linux machine that
    /// re-runs the analysis.
    pub fn from_env() -> Self {
        match std::env::var("SEANCE_EVIDENCE_ROOTS") {
            Ok(spec) if !spec.trim().is_empty() => {
                let policy = Self::restricted_to(
                    seance_memory::analysis::split_env_list(&spec)
                        .into_iter()
                        .map(std::path::PathBuf::from)
                        .collect(),
                );
                info!(
                    "Evidence access restricted to {} root(s): {:?}",
                    policy.roots.len(),
                    policy.roots
                );
                policy
            }
            _ => {
                // Fail closed: unset roots no longer mean "read any file on the
                // host". An operator who genuinely wants unrestricted access
                // must opt in explicitly; otherwise access is confined to the
                // current working directory so the server is still usable for
                // the common "evidence under the launch dir" case without
                // exposing the whole filesystem.
                let opt_out = std::env::var("SEANCE_ALLOW_UNRESTRICTED_FS")
                    .map(|v| v.eq_ignore_ascii_case("true") || v == "1")
                    .unwrap_or(false);
                if opt_out {
                    warn!(
                        "SEANCE_ALLOW_UNRESTRICTED_FS is set: the API can read ANY file the \
                         server process can access. Only use this on a trusted local workstation."
                    );
                    Self::unrestricted()
                } else {
                    let cwd =
                        std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("."));
                    warn!(
                        "SEANCE_EVIDENCE_ROOTS not set: confining evidence access to the current \
                         directory ({:?}). Set SEANCE_EVIDENCE_ROOTS to your evidence directories, \
                         or SEANCE_ALLOW_UNRESTRICTED_FS=true to allow full filesystem access.",
                        cwd
                    );
                    Self::restricted_to(vec![cwd])
                }
            }
        }
    }

    /// True when an allowlist is in force.
    pub fn is_restricted(&self) -> bool {
        self.restricted
    }

    /// First configured root, used as the default starting directory for
    /// filesystem browsing.
    pub fn first_root(&self) -> Option<&std::path::Path> {
        self.roots.first().map(|p| p.as_path())
    }

    /// All configured evidence roots, for the ingest browser's root switcher.
    pub fn roots(&self) -> &[std::path::PathBuf] {
        &self.roots
    }

    /// Canonicalize `path` (resolving `..` and symlinks) and verify it falls
    /// under one of the allowed roots. Returns the canonical path on success.
    /// Unrestricted policies only require that the path canonicalizes.
    pub fn check(&self, path: &std::path::Path) -> Result<std::path::PathBuf, String> {
        let canonical = path
            .canonicalize()
            .map_err(|e| format!("Invalid path {:?}: {}", path, e))?;
        if !self.restricted || self.roots.iter().any(|root| canonical.starts_with(root)) {
            Ok(canonical)
        } else {
            Err(format!(
                "Path {:?} is outside the configured evidence roots",
                path
            ))
        }
    }
}

/// Deployment opt-in that lets non-admin examiners use the server's own
/// filesystem as an evidence source.
///
/// Same shape as `SEANCE_ALLOW_UNRESTRICTED_FS` above: the safe posture is the
/// default, and widening it is an explicit operator decision recorded in the
/// deployment rather than inferred from whoever happens to be logged in.
const EXAMINER_HOST_FS_ENV: &str = "SEANCE_EXAMINER_HOST_FS";

/// Authorise a request to use the SERVER's own filesystem as an evidence
/// source: enumerating it (`/filesystem/browse`, `/evidence-roots`) or
/// attaching a path from it (`POST /cases/{id}/ingest`).
///
/// [`EvidenceRootPolicy`] answers "may the SERVER open this path". It has never
/// answered "may THIS USER open it", and conflating the two was the whole of
/// HUNT-008. Case scoping does not answer it either: `create_case` is open to
/// examiners and self-grants `owner`, so every case-scoped check upstream of a
/// server-path read is satisfied by a case the requester opened for themselves
/// moments earlier. "You hold a case" therefore authorised reading ANY file
/// under the evidence roots — in a shared lab, another team's exhibits sitting
/// in the same directory, which is to say the whole evidence store.
///
/// Custody of the evidence store is a privilege in its own right, not a
/// consequence of case work. Admins hold it, which covers the single-workstation
/// default: with authentication disabled `auth_middleware` attributes requests
/// to the `admin`-roled `local` identity, so that deployment is unaffected. A
/// multi-user deployment that genuinely intends every examiner to reach the
/// whole evidence tree must say so with `SEANCE_EXAMINER_HOST_FS=true`.
///
/// Anything else is refused with 403 and a message that says why. It is
/// deliberately not an empty listing: "there is nothing here" and "you may not
/// look here" are different answers, and only one of them is true.
fn require_host_filesystem_access(role: &str) -> Result<(), ApiError> {
    if role == "admin" {
        return Ok(());
    }
    let opted_in = std::env::var(EXAMINER_HOST_FS_ENV)
        .map(|v| v.eq_ignore_ascii_case("true") || v == "1")
        .unwrap_or(false);
    if opted_in {
        return Ok(());
    }
    Err(ApiError::Forbidden(
        "Reading the server's own filesystem is reserved for administrators. The evidence-root \
         allowlist says which paths this SERVER may open, not which paths you may open, and a \
         case does not narrow it — an examiner able to browse it can attach any exhibit in the \
         evidence store to a case of their own. Ask an administrator to ingest the source, or \
         set SEANCE_EXAMINER_HOST_FS=true if this deployment intends every examiner to reach \
         the whole evidence tree."
            .to_string(),
    ))
}

/// Read the mandatory `case_id` query parameter shared by the host-filesystem
/// endpoints.
///
/// Mandatory because `case_access_middleware` only recognises a case named in
/// the PATH (`/cases/{uuid}/...`); these two routes have no such segment, so
/// before HUNT-008 they sat outside per-case enforcement entirely and
/// authentication was their only gate. Naming the case in the query is what
/// gives [`require_case_access`] something to check.
fn required_case_id(params: &std::collections::HashMap<String, String>) -> Result<Uuid, ApiError> {
    let raw = params
        .get("case_id")
        .map(|s| s.trim())
        .filter(|s| !s.is_empty())
        .ok_or_else(|| {
            ApiError::InvalidRequest(
                "case_id is required: the server's filesystem is browsable only in the context \
                 of a case you hold, so the request must name one."
                    .to_string(),
            )
        })?;
    Uuid::parse_str(raw)
        .map_err(|_| ApiError::InvalidRequest(format!("case_id is not a valid UUID: {}", raw)))
}

// --- Application State ---

#[derive(Clone)]
pub struct AppState {
    pub db: Arc<SqliteConnection>,
    pub orchestrator_sender: seance_core::orchestrator::TaskSubmitter,
    pub ad_hoc_sender: mpsc::Sender<seance_core::profile::AdHocRequest>,
    pub event_sender: tokio::sync::broadcast::Sender<Artifact>,
    pub status_sender: tokio::sync::broadcast::Sender<seance_core::orchestrator::OrchestratorEvent>,
    pub active_tasks: Arc<std::sync::atomic::AtomicUsize>,
    pub search_service: Option<Arc<seance_search::SearchService>>,
    pub ingestion_service: seance_core::ingestion::IngestionService,
    pub module_registry: Vec<seance_core::module::ModuleInfo>,
    pub signing_config: Option<SigningConfig>,
    /// Evidence-root allowlist for server-side file access (H6).
    pub evidence_roots: EvidenceRootPolicy,
    /// Cooperative cancellation handle for orchestrator processing.
    pub cancellation: seance_core::orchestrator::CancellationHandle,
}

/// The orchestrator's per-case task census, handed to the router as an axum
/// `Extension` so `GET /api/v1/status` can break `active_tasks` down by case.
///
/// An extension rather than an [`AppState`] field because `AppState` is
/// assembled by struct literal in every embedding (the server, the CLI's
/// embedded server, the test crates), and a field none of them set would not
/// compile; a layer the embedding forgets simply leaves the route saying the
/// census is unavailable, which is the truth for that embedding.
#[derive(Clone)]
pub struct ProcessingCensus(pub seance_core::task_queue::CaseTaskCensus);

// --- Audit helpers ---

/// Record a best-effort audit event. Failure is logged but never fails the
/// request (low-stakes actions like tagging or metadata edits).
async fn audit_best_effort(
    state: &AppState,
    case_id: Option<Uuid>,
    user: &str,
    action: &str,
    resource_type: Option<&str>,
    resource_id: Option<Uuid>,
    details: Option<&str>,
) {
    if let Err(e) = state
        .db
        .record_audit_event(case_id, user, action, resource_type, resource_id, details)
        .await
    {
        warn!("Failed to record audit event '{}': {}", action, e);
    }
}

/// Record a mandatory audit event for evidentially significant actions
/// (deletions, ingest, exports). Failure aborts the request so the action
/// never goes unaccounted for.
async fn audit_required(
    state: &AppState,
    case_id: Option<Uuid>,
    user: &str,
    action: &str,
    resource_type: Option<&str>,
    resource_id: Option<Uuid>,
    details: Option<&str>,
) -> Result<(), ApiError> {
    state
        .db
        .record_audit_event(case_id, user, action, resource_type, resource_id, details)
        .await
        .map_err(|e| {
            error!("Failed to record mandatory audit event '{}': {}", action, e);
            ApiError::InternalServerError(format!("Failed to record audit event: {}", e))
        })
}

/// Turn the outcome of a search-index purge into the outcome of the request
/// that asked for the delete.
///
/// Fail closed (HUNT-010): the purge runs BEFORE the destructive database
/// delete, so a purge that did not succeed aborts the request with the evidence
/// still in place and the index still describing it. Warning and carrying on
/// left deleted evidence answering searches until someone rebuilt the index by
/// hand, and a stale hit is indistinguishable from a live artifact in a result
/// list: the examiner reads it as evidence still in the case.
///
/// The residual risk of this order is the opposite one: a database delete that
/// fails after a successful purge leaves live artifacts missing from the index
/// until a rebuild. That is a search that under-reports, announced by the 500
/// the caller receives, rather than a deletion the index quietly denies.
fn require_index_purge(result: anyhow::Result<()>, scope: &str) -> Result<(), ApiError> {
    result.map_err(|e| {
        error!(
            "Refusing to delete {}: the search index purge failed: {}",
            scope, e
        );
        ApiError::InternalServerError(format!(
            "The search index could not be purged for {}, so nothing was deleted: {}",
            scope, e
        ))
    })
}

/// Seed the initial admin account on first startup.
///
/// When the `users` table is empty, seed one admin so every audited action is
/// attributable to a real user. The credential is chosen deterministically and
/// is always the one communicated to the operator (no phantom regenerated on
/// restart):
///
/// - `SEANCE_ADMIN_PASSWORD` set to a password the product would itself accept
///   → use that hash, no forced change. `AuthConfig::from_env` leaves the hash
///   empty for an empty or too-short value, so a weak env credential falls
///   through to the forced-change branches below rather than becoming a
///   permanent admin password (HUNT-003).
/// - else `bind_is_loopback` → default password `seance`, **forced change on
///   first login**. A known default is acceptable only because the server is
///   confined to loopback and the credential must be rotated before any other
///   action.
/// - else (exposed bind, no env password) → a generated password, logged once,
///   also forced-change — never a known default on a reachable server.
///
/// Idempotent: does nothing once any user exists.
pub async fn bootstrap_admin(
    db: &SqliteConnection,
    auth_config: &AuthConfig,
    bind_is_loopback: bool,
) -> anyhow::Result<()> {
    if db.count_users().await? != 0 {
        return Ok(());
    }

    let (password_hash, must_change) = if !auth_config.admin_password_hash.is_empty() {
        (auth_config.admin_password_hash.clone(), false)
    } else if bind_is_loopback {
        warn!(
            "Seeding initial admin '{}' with the default password 'seance'. \
             You will be required to change it on first login.",
            auth_config.admin_username
        );
        (
            hash_password("seance").map_err(|e| anyhow::anyhow!(e))?,
            true,
        )
    } else {
        let generated = format!(
            "{}{}",
            uuid::Uuid::new_v4().simple(),
            uuid::Uuid::new_v4().simple()
        );
        warn!(
            "Seeding initial admin '{}' with a generated password (bind is non-loopback):\n\n    {}\n\n\
             You will be required to change it on first login.",
            auth_config.admin_username, generated
        );
        (
            hash_password(&generated).map_err(|e| anyhow::anyhow!(e))?,
            true,
        )
    };

    let id = db
        .create_user(&auth_config.admin_username, &password_hash, "admin")
        .await?;
    if must_change {
        db.set_must_change_password(id, true).await?;
    }
    info!(
        "Bootstrapped initial admin user '{}' (id {}).",
        auth_config.admin_username, id
    );
    Ok(())
}

// --- Handlers ---

pub async fn create_case(
    State(state): State<AppState>,
    Extension(user): Extension<AuthenticatedUser>,
    Extension(role): Extension<AuthenticatedRole>,
    Json(payload): Json<CreateCaseRequest>,
) -> Result<Json<CaseResponse>, ApiError> {
    info!(
        "Received request to create case with name: {:?}",
        payload.name
    );
    match state
        .db
        .create_case_with_metadata(
            payload.name,
            payload.reference_number,
            payload.examiner_name,
        )
        .await
    {
        Ok(id) => {
            // A live case with no `case_created` row hangs every later action
            // off a chain that never records the case being opened, so the
            // write is mandatory rather than best-effort (HUNT-023). On failure
            // the case is rolled back exactly as a failed owner grant rolls it
            // back below: nothing survives that the audit trail cannot account
            // for.
            if let Err(e) = audit_required(
                &state,
                Some(id),
                &user.0,
                "case_created",
                Some("case"),
                Some(id),
                None,
            )
            .await
            {
                error!(
                    "Audit write failed for new case {} by '{}'; rolling the case back",
                    id, user.0
                );
                if let Err(del) = state.db.delete_case(id).await {
                    error!(
                        "Failed to roll back case {} after the audit write failed: {}",
                        id, del
                    );
                }
                return Err(e);
            }
            // Grant the creating user 'owner' access so a non-admin examiner can
            // see and manage the case they just opened. Best-effort and resolved
            // by username: skipped for the "local" dev identity (auth disabled)
            // and for any token subject with no user row, since admins bypass the
            // access table entirely and can repair a missing grant.
            if let Ok(Some(creator)) = state.db.get_user_by_username(&user.0).await {
                if let Err(e) = state
                    .db
                    .grant_case_access(id, creator.id, "owner", Some(creator.id))
                    .await
                {
                    // A non-admin can only reach the case through this grant.
                    // If it fails, don't leave them a case they cannot open
                    // (BUG-028): roll the case back and surface the error so the
                    // client can retry. Admins bypass the access table, so for
                    // them a failed grant is non-fatal and only warned.
                    if role.0 != "admin" {
                        error!(
                            "Owner grant failed on case {} for non-admin '{}': {}; rolling back",
                            id, user.0, e
                        );
                        if let Err(del) = state.db.delete_case(id).await {
                            error!(
                                "Failed to roll back case {} after grant failure: {}",
                                id, del
                            );
                        }
                        return Err(ApiError::InternalServerError(
                            "Case could not be created with owner access; please retry".to_string(),
                        ));
                    }
                    warn!(
                        "Failed to grant owner access on case {} to admin '{}': {}",
                        id, user.0, e
                    );
                }
            }
            // Fetch the created case to return full details
            match state.db.get_case(id).await {
                Ok(case) => Ok(Json(case)),
                Err(e) => {
                    error!("Failed to fetch created case: {}", e);
                    Err(ApiError::InternalServerError(
                        "Case created but failed to retrieve details".to_string(),
                    ))
                }
            }
        }
        Err(e) => {
            error!("Failed to create case: {}", e);
            Err(ApiError::InternalServerError(
                "Failed to create case in database".to_string(),
            ))
        }
    }
}

pub async fn list_cases(
    State(state): State<AppState>,
    Extension(user): Extension<AuthenticatedUser>,
    Extension(role): Extension<AuthenticatedRole>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
) -> Result<Json<Vec<CaseResponse>>, ApiError> {
    info!("Received request to list cases with params: {:?}", params);

    // Check if we have search/filter parameters
    let has_search_params =
        params.contains_key("q") || params.contains_key("status") || params.contains_key("sort");

    let cases = if has_search_params {
        let query = params.get("q").map(|s| s.as_str());
        let status = params
            .get("status")
            .filter(|s| !s.is_empty())
            .map(|s| s.as_str());
        let sort = params
            .get("sort")
            .filter(|s| !s.is_empty())
            .map(|s| s.as_str());

        state
            .db
            .search_cases(query, status, sort)
            .await
            .map_err(|e| {
                error!("Failed to search cases from database: {}", e);
                ApiError::InternalServerError("Failed to search cases".to_string())
            })?
    } else {
        state.db.list_cases().await.map_err(|e| {
            error!("Failed to list cases from database: {}", e);
            ApiError::InternalServerError("Failed to retrieve cases".to_string())
        })?
    };

    // Access control: admins see every case; everyone else sees only cases they
    // have been granted access to. An unresolved token subject sees nothing
    // (fail closed) rather than the full list.
    let cases = if role.0 == "admin" {
        cases
    } else {
        let accessible: std::collections::HashSet<Uuid> =
            match state.db.get_user_by_username(&user.0).await.map_err(|e| {
                error!("Failed to resolve user for case list: {}", e);
                ApiError::InternalServerError("Failed to retrieve cases".to_string())
            })? {
                Some(u) => state
                    .db
                    .list_accessible_case_ids(u.id)
                    .await
                    .map_err(|e| {
                        error!("Failed to list accessible cases: {}", e);
                        ApiError::InternalServerError("Failed to retrieve cases".to_string())
                    })?
                    .into_iter()
                    .collect(),
                None => std::collections::HashSet::new(),
            };
        cases
            .into_iter()
            .filter(|c| accessible.contains(&c.id))
            .collect()
    };

    Ok(Json(cases))
}

pub async fn get_or_create_default_case(
    State(state): State<AppState>,
    Extension(user): Extension<AuthenticatedUser>,
    Extension(role): Extension<AuthenticatedRole>,
) -> Result<Json<CaseResponse>, ApiError> {
    let cases = state.db.list_cases().await.map_err(|e| {
        error!("Failed to list cases for default: {}", e);
        ApiError::InternalServerError("Failed to retrieve cases".to_string())
    })?;

    // Scope to the caller's accessible cases, mirroring `list_cases`: admins
    // see every case; anyone else only cases they hold a grant for, and an
    // unresolved token subject sees nothing (fail closed).
    let cases = if role.0 == "admin" {
        cases
    } else {
        let accessible: std::collections::HashSet<Uuid> =
            match state.db.get_user_by_username(&user.0).await.map_err(|e| {
                error!("Failed to resolve user for default case: {}", e);
                ApiError::InternalServerError("Failed to retrieve cases".to_string())
            })? {
                Some(u) => state
                    .db
                    .list_accessible_case_ids(u.id)
                    .await
                    .map_err(|e| {
                        error!("Failed to list accessible cases: {}", e);
                        ApiError::InternalServerError("Failed to retrieve cases".to_string())
                    })?
                    .into_iter()
                    .collect(),
                None => std::collections::HashSet::new(),
            };
        cases
            .into_iter()
            .filter(|c| accessible.contains(&c.id))
            .collect()
    };

    // list_cases is newest-first (ORDER BY created_at DESC); the default should
    // be the most recent accessible case, not the oldest (`pop()` took the tail).
    if let Some(case) = cases.into_iter().next() {
        Ok(Json(case))
    } else {
        info!("No accessible case found, creating a default case.");
        let new_case_id = state
            .db
            .create_case_with_metadata(
                Some("Default Case".to_string()),
                None,
                Some("System".to_string()),
            )
            .await
            .map_err(|e| {
                error!("Failed to create default case: {}", e);
                ApiError::InternalServerError("Failed to create default case".to_string())
            })?;

        // Mirror create_case: mandatory audit attribution (a case that exists
        // with no `case_created` row is a gap in the chain of custody however
        // it was created, HUNT-023), then a best-effort owner grant so the
        // creator retains access to the case they just caused.
        if let Err(e) = audit_required(
            &state,
            Some(new_case_id),
            &user.0,
            "case_created",
            Some("case"),
            Some(new_case_id),
            None,
        )
        .await
        {
            error!(
                "Audit write failed for default case {} by '{}'; rolling the case back",
                new_case_id, user.0
            );
            if let Err(del) = state.db.delete_case(new_case_id).await {
                error!(
                    "Failed to roll back default case {} after the audit write failed: {}",
                    new_case_id, del
                );
            }
            return Err(e);
        }
        if let Ok(Some(creator)) = state.db.get_user_by_username(&user.0).await {
            if let Err(e) = state
                .db
                .grant_case_access(new_case_id, creator.id, "owner", Some(creator.id))
                .await
            {
                // Mirror create_case (BUG-028): a non-admin can only reach the
                // case through this grant, so roll the case back rather than
                // hand them a case they cannot open (BUG-081).
                if role.0 != "admin" {
                    error!(
                        "Owner grant failed on default case {} for non-admin '{}': {}; rolling back",
                        new_case_id, user.0, e
                    );
                    if let Err(del) = state.db.delete_case(new_case_id).await {
                        error!(
                            "Failed to roll back default case {} after grant failure: {}",
                            new_case_id, del
                        );
                    }
                    return Err(ApiError::InternalServerError(
                        "Case could not be created with owner access; please retry".to_string(),
                    ));
                }
                warn!(
                    "Failed to grant owner access on default case {} to admin '{}': {}",
                    new_case_id, user.0, e
                );
            }
        }

        // Fetch the created case to return full details
        match state.db.get_case(new_case_id).await {
            Ok(case) => Ok(Json(case)),
            Err(e) => {
                error!("Failed to fetch created default case: {}", e);
                Err(ApiError::InternalServerError(
                    "Case created but failed to retrieve details".to_string(),
                ))
            }
        }
    }
}

pub async fn ingest_source(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
    Extension(user): Extension<AuthenticatedUser>,
    Extension(role): Extension<AuthenticatedRole>,
    Json(payload): Json<IngestRequest>,
) -> Result<Json<IngestResponse>, ApiError> {
    info!(
        "Received ingest request for case {}: {} (type: {}) with profile: {:?} \
         (memory_image: {:?}, memory_image_format: {:?})",
        case_id,
        payload.path,
        payload.artifact_type,
        payload.profile,
        payload.memory_image,
        payload.memory_image_format
    );

    // `payload.path` names a file on the SERVER, so this is a host-filesystem
    // read wearing a case-scoped route. `case_access_middleware` has already
    // established that the caller may write to this case, which is a weaker
    // statement than it looks: they may have created it seconds ago. Gating
    // only the browse endpoints would have closed the listing and left the read
    // itself open — a path guessed, remembered from an earlier role, or read
    // out of a colleague's report is all it takes (HUNT-008). Checked before
    // any profile is created or activated, so a refused ingest leaves no trace
    // of work it did not do.
    require_host_filesystem_access(&role.0)?;

    // Reject up-front if the case does not exist, rather than queueing an
    // ingest that fails deep in the pipeline with a foreign-key error. This is
    // the common "stale case open in the browser after the DB was reset" case.
    // get_case errors when the row is absent, which is the case we guard.
    if state.db.get_case(case_id).await.is_err() {
        return Err(ApiError::ResourceNotFound(format!(
            "Case {} does not exist (it may have been deleted). Reload the case list and try again.",
            case_id
        )));
    }

    // Validate the memory declaration before anything is activated, created or
    // queued, so a refused assertion leaves no trace of work it did not do.
    // The keys are carried to the artifact's metadata below.
    let memory_keys = memory_declaration_keys(&payload)?;

    // A new ingest is fresh work: lift any prior per-case cancel so its
    // artifacts are not skipped as poison. A cancel drains the queued batch,
    // it does not disable the case until the process restarts.
    state.cancellation.clear_case_cancel(case_id);

    // Handle profile selection if specified
    if let Some(profile_name) = &payload.profile {
        match profile_name.as_str() {
            "triage" => {
                // Create or activate triage profile
                let triage = seance_core::profile::IngestionProfile::triage(case_id);

                // Validate triage module IDs against registry
                let registry_ids: std::collections::HashSet<&str> = state
                    .module_registry
                    .iter()
                    .map(|m| m.id.as_str())
                    .collect();
                for module_id in &triage.enabled_modules {
                    if !registry_ids.contains(module_id.as_str()) {
                        warn!(
                            "Triage profile references unknown module '{}' — it will not run",
                            module_id
                        );
                    }
                }

                // Check if triage profile already exists
                let existing_profiles = state.db.list_profiles(case_id).await.map_err(|e| {
                    ApiError::InternalServerError(format!("Failed to list profiles: {}", e))
                })?;

                let existing_triage = existing_profiles.iter().find(|p| p.name == "triage");

                if let Some(existing) = existing_triage {
                    // Activate existing triage profile
                    state
                        .db
                        .set_active_profile(case_id, existing.id)
                        .await
                        .map_err(|e| {
                            ApiError::InternalServerError(format!(
                                "Failed to activate profile: {}",
                                e
                            ))
                        })?;
                    info!("Activated existing triage profile for case {}", case_id);
                } else {
                    // Create new triage profile
                    state.db.create_profile(&triage).await.map_err(|e| {
                        ApiError::InternalServerError(format!("Failed to create profile: {}", e))
                    })?;
                    state
                        .db
                        .set_active_profile(case_id, triage.id)
                        .await
                        .map_err(|e| {
                            ApiError::InternalServerError(format!(
                                "Failed to activate profile: {}",
                                e
                            ))
                        })?;
                    info!("Created and activated triage profile for case {}", case_id);
                }
            }
            "deep" => {
                // Create or activate deep profile
                let deep = seance_core::profile::IngestionProfile::deep(case_id);

                let existing_profiles = state.db.list_profiles(case_id).await.map_err(|e| {
                    ApiError::InternalServerError(format!("Failed to list profiles: {}", e))
                })?;

                let existing_deep = existing_profiles.iter().find(|p| p.name == "deep");

                if let Some(existing) = existing_deep {
                    state
                        .db
                        .set_active_profile(case_id, existing.id)
                        .await
                        .map_err(|e| {
                            ApiError::InternalServerError(format!(
                                "Failed to activate profile: {}",
                                e
                            ))
                        })?;
                    info!("Activated existing deep profile for case {}", case_id);
                } else {
                    state.db.create_profile(&deep).await.map_err(|e| {
                        ApiError::InternalServerError(format!("Failed to create profile: {}", e))
                    })?;
                    state
                        .db
                        .set_active_profile(case_id, deep.id)
                        .await
                        .map_err(|e| {
                            ApiError::InternalServerError(format!(
                                "Failed to activate profile: {}",
                                e
                            ))
                        })?;
                    info!("Created and activated deep profile for case {}", case_id);
                }
            }
            uuid_str => {
                // Treat as profile UUID
                if let Ok(profile_id) = Uuid::parse_str(uuid_str) {
                    state
                        .db
                        .set_active_profile(case_id, profile_id)
                        .await
                        .map_err(|e| {
                            ApiError::InternalServerError(format!(
                                "Failed to activate profile: {}",
                                e
                            ))
                        })?;
                    info!("Activated profile {} for case {}", profile_id, case_id);
                } else {
                    return Err(ApiError::InvalidRequest(format!(
                        "Invalid profile: {}",
                        uuid_str
                    )));
                }
            }
        }
    }

    let file_path = std::path::PathBuf::from(&payload.path);
    if !file_path.exists() {
        warn!("Ingest path does not exist: {:?}", file_path);
        return Err(ApiError::InvalidRequest(format!(
            "Path does not exist: {:?}",
            file_path
        )));
    }

    // H6: confine ingest to the configured evidence roots
    let file_path = state.evidence_roots.check(&file_path).map_err(|e| {
        warn!("Ingest path rejected by evidence-root policy: {}", e);
        ApiError::InvalidRequest(e)
    })?;

    // A directory is a source in its own right: an iOS backup folder, a mounted
    // image, an exported file tree. `IosBackupParser` reads `path` and does
    // nothing unless it is a directory, and `AsepEnumerator`, `FileAnalyzer`,
    // `FileHasher`, `EncryptionDetector`, `ICalParser` and the iOS artifact
    // readers all branch on `is_directory`. Nothing but `seance scan` ever wrote
    // that shape, so through the API — and therefore through the UI — an iOS
    // backup folder, which is the standard iOS acquisition, could not be
    // examined at all. `FileDataSource::new` on a directory does not even fail
    // on Unix: it opens the fd, every read then fails, and the ingest "succeeds"
    // with a source nothing can read.
    if file_path.is_dir() {
        return ingest_directory(&state, &user, case_id, &file_path, &payload).await;
    }

    // Parse the artifact type from the request, or auto-detect
    let (artifact_type, detected_subtype) = if payload.artifact_type == "auto" {
        auto_detect_artifact_type(&file_path)
    } else {
        let art_type = payload
            .artifact_type
            .parse::<ArtifactType>()
            .map_err(|e| ApiError::InvalidRequest(format!("Invalid artifact type: {}", e)))?;
        // `RawEvidence` is what a caller writes for "disk image", and the
        // documented example does exactly that. Honoured over the file's own
        // signature it turns an E01 into a source no module parses (HUNT-273),
        // so a signature that names a container wins.
        match signature_overrides_raw_evidence(&file_path, &art_type) {
            Some(detected) => {
                info!(
                    "'{}' asked for RawEvidence but {:?} carries a {:?} signature; ingesting it as that",
                    payload.path, file_path, detected.0
                );
                detected
            }
            None => (art_type, None),
        }
    };

    // A memory declaration only reaches the analysis on an artifact type the
    // memory module subscribes to (RawEvidence, FileEntry). Attached to any
    // other type it is persisted, never read, and the ingest succeeds with the
    // whole memory tier reporting `did_not_run`. Refuse, and say which type
    // would honour it, rather than accept an assertion we will drop.
    //
    // Under `auto` this no longer fires for the ordinary capture names: a
    // `.mem`/`.vmem`/`hiberfil.sys` matches no magic and no extension entry, and
    // the undetermined default is RawEvidence (see `UNDETERMINED_TYPE`). It
    // still fires when the source really is something else — a declaration on a
    // detected ZIP or E01 is a mistake, and saying so is the point.
    if declares_memory(&payload)
        && !matches!(
            artifact_type,
            ArtifactType::RawEvidence | ArtifactType::FileEntry
        )
    {
        return Err(ApiError::InvalidRequest(format!(
            "A memory-image declaration cannot be honoured for artifact type {:?} (resolved \
             from \"{}\"): the memory analysis only receives RawEvidence and FileEntry, so the \
             declaration would be recorded and never read. Ingest a declared memory capture \
             with \"artifact_type\": \"RawEvidence\".",
            artifact_type, payload.artifact_type
        )));
    }

    // An encrypted Apple disk image is ciphertext end to end: no partition
    // table, no filesystem, nothing any module can open, and (unlike LUKS and
    // BitLocker) no passphrase entry point exists for it yet. It is still
    // ingested, because the exhibit belongs in the case and its acquisition
    // hash belongs on the record, but the source is marked encrypted and unread
    // so the examiner is told why it produced no files (LIVE-003).
    let apple_encrypted_dmg = is_apple_encrypted_dmg(&file_path);
    if apple_encrypted_dmg {
        warn!(
            "{:?} is an encrypted Apple disk image ('encrcdsa'): it is recorded as encrypted \
             and unopened. No volume, filesystem or file will be extracted from it.",
            file_path
        );
    }

    // Honest gate: refuse formats we can recognize but cannot actually extract,
    // so the examiner gets a clear message rather than an ingest that succeeds
    // and then silently yields no files.
    let lower_name = file_path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or_default()
        .to_lowercase();
    let gate_subtype = detected_subtype.or_else(|| map_extension(&lower_name).1);
    if let Some(msg) = unsupported_format_message(gate_subtype) {
        return Err(ApiError::InvalidRequest(msg));
    }

    match FileDataSource::new(file_path.clone()) {
        Ok(file_source) => {
            // Record the CANONICAL path -- the one actually opened above -- not
            // the caller's string. A relative / symlinked / `..`-containing
            // request would otherwise persist a CWD-dependent path that no
            // longer resolves after a restart, breaking re-open and leaving a
            // chain-of-custody path that does not match the file hashed
            // (BUG-236). `requested_path` keeps the operator's original input
            // when it differs, so the record stays complete.
            let canonical_path = file_path.to_string_lossy().to_string();
            // Build metadata based on artifact type
            let mut metadata = serde_json::json!({
                "source_path": canonical_path,
                "path": canonical_path,
                "description": "Ingested via API",
                "user_specified_type": payload.artifact_type,
            });
            if payload.path != canonical_path {
                if let Some(obj) = metadata.as_object_mut() {
                    obj.insert(
                        "requested_path".to_string(),
                        serde_json::json!(payload.path),
                    );
                }
            }

            // Add type-specific metadata
            // Always set name from filename
            let file_name = file_path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("unknown");

            // Record the source byte size so the disk map, overview, and
            // report can display it without re-statting the evidence file.
            let source_size = std::fs::metadata(&file_path).map(|m| m.len()).ok();

            if let Some(obj) = metadata.as_object_mut() {
                obj.insert("name".to_string(), serde_json::json!(file_name));

                if let Some(size) = source_size {
                    obj.insert("size".to_string(), serde_json::json!(size));
                }

                // Add subtype if detected
                if let Some(subtype) = detected_subtype {
                    obj.insert("subtype".to_string(), serde_json::json!(subtype));
                }

                // The examiner's memory declaration, verbatim. Without it the
                // memory module treats a headerless dump as "no detection" and
                // returns nothing, which is why this is what makes a raw
                // capture analysable at all.
                attach_memory_declaration(obj, &memory_keys);

                // A source whose bytes we cannot decrypt is declared as such on
                // the artifact itself, so "0 artifacts" is never all the
                // examiner is told (LIVE-003).
                if apple_encrypted_dmg {
                    attach_encrypted_source_markers(obj, APPLE_ENCRYPTED_DMG_FORMAT);
                }

                // Note: FileSystem artifacts intentionally do NOT get a
                // hard-coded filesystem_type/cluster_size here. Stamping "NTFS"
                // made the ext4/APFS/XFS/etc parsers skip the volume (wrong
                // filesystem_type) while only the NTFS parser tried and failed
                // (BUG-005). With the field absent, each FS parser content-
                // detects from the superblock/boot sector and the correct one
                // runs; the NTFS parser reads the real cluster size from the
                // boot sector regardless. The content-detected `subtype` set
                // above still scopes dispatch when available.
            }

            // Non-blocking ingest: the artifact ID is returned immediately;
            // acquisition hashing, persistence (including the integrity
            // baseline + "evidence_acquisition_hashed" audit event written by
            // seance_core), and queueing run in a background task. Progress
            // and outcome are broadcast as acquisition_hash_progress /
            // ingest_completed / ingest_failed SSE events.
            let artifact = state
                .ingestion_service
                .clone()
                .with_status_sender(state.status_sender.clone())
                .ingest_artifact_background(
                    case_id,
                    artifact_type,
                    Some(Arc::new(file_source)),
                    metadata,
                );

            info!("Queued background ingest for artifact ID: {}", artifact.id);

            // Evidence ingestion must always be attributable to the requester
            // (the background task audits only the acquisition hashing). Record
            // the canonical path so the audit names the file that was actually
            // opened and hashed (BUG-236).
            audit_required(
                &state,
                Some(case_id),
                &user.0,
                INGEST_REQUESTED,
                Some("artifact"),
                Some(artifact.id),
                Some(&canonical_path),
            )
            .await?;

            // A headerless capture is only analysed when declared. If the
            // name is memory-shaped and nothing declared it, say so here —
            // at the moment of ingest, which is where it is read (HUNT-081).
            let notes = if declares_memory(&payload) {
                Vec::new()
            } else {
                seance_memory::undeclared_memory_hint(file_name)
                    .into_iter()
                    .collect()
            };
            Ok(Json(IngestResponse {
                artifact_id: artifact.id,
                status: "hashing".to_string(),
                notes,
            }))
        }
        Err(e) => {
            error!(
                "Failed to create file data source for {:?}: {}",
                file_path, e
            );
            Err(ApiError::InternalServerError(format!(
                "Failed to access file: {}",
                e
            )))
        }
    }
}

/// Ingest a directory as a single directory-shaped `RawEvidence` root.
///
/// This is the shape `seance scan` has always produced for a folder, and the
/// shape the directory-aware modules require: `path` pointing at the directory
/// and `is_directory: true`. It is deliberately identical, because a case must
/// not depend on which entry point loaded the evidence.
///
/// No data source and no acquisition hash. A directory has no bytes of its own,
/// so there is nothing to hash; the files discovered inside it are hashed
/// individually as they are produced. `source_path` is therefore omitted rather
/// than set to the directory — `IngestionService` hashes exactly when that key
/// is present, and pointing it at a directory would fail the whole ingest.
async fn ingest_directory(
    state: &AppState,
    user: &AuthenticatedUser,
    case_id: Uuid,
    dir_path: &std::path::Path,
    payload: &IngestRequest,
) -> Result<Json<IngestResponse>, ApiError> {
    // A directory is not a capture: the declaration would ride an artifact with
    // no data source, so the memory module would read the keys and have nothing
    // to read them against.
    if declares_memory(payload) {
        return Err(ApiError::InvalidRequest(format!(
            "A memory-image declaration names a single captured file, but {} is a directory. \
             Ingest the capture itself.",
            dir_path.display()
        )));
    }

    // Only the type the directory-aware modules subscribe to. Accepting any
    // other would persist a directory artifact that no module opens.
    if payload.artifact_type != "auto" && payload.artifact_type != "RawEvidence" {
        return Err(ApiError::InvalidRequest(format!(
            "{} is a directory, which is ingested as RawEvidence so the directory-aware \
             modules (iOS backup, autostart enumeration) receive it. \"{}\" was requested; \
             send \"auto\" or \"RawEvidence\".",
            dir_path.display(),
            payload.artifact_type
        )));
    }

    let canonical_path = dir_path.to_string_lossy().to_string();
    let dir_name = dir_path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("directory");

    let mut metadata = serde_json::json!({
        "name": dir_name,
        "path": canonical_path,
        "is_directory": true,
        "description": "Ingested via API",
        "user_specified_type": payload.artifact_type,
    });
    if payload.path != canonical_path {
        if let Some(obj) = metadata.as_object_mut() {
            obj.insert(
                "requested_path".to_string(),
                serde_json::json!(payload.path),
            );
        }
    }
    // No memory declaration is attached: one is refused above, because a
    // directory has no bytes for the analysis to read the keys against.

    let artifact = state
        .ingestion_service
        .clone()
        .with_status_sender(state.status_sender.clone())
        .ingest_artifact_background(case_id, ArtifactType::RawEvidence, None, metadata);

    info!(
        "Queued background ingest for directory artifact ID: {}",
        artifact.id
    );

    audit_required(
        state,
        Some(case_id),
        &user.0,
        INGEST_REQUESTED,
        Some("artifact"),
        Some(artifact.id),
        Some(&canonical_path),
    )
    .await?;

    Ok(Json(IngestResponse {
        artifact_id: artifact.id,
        notes: Vec::new(),
        // Not "hashing": a directory has no bytes to hash, and reporting a
        // hashing phase that will never run is exactly the kind of claim this
        // codebase must not make.
        status: "queued".to_string(),
    }))
}

// --- Acquisition visibility ---

/// Audit actions that bracket an evidence ingest.
///
/// The request-time event is written by the API, names the requester, and is
/// mandatory; the two outcome events are written by the background task in
/// `seance_core::ingestion` when the ingest ends. They pair by resource_id (the
/// artifact ID), which is what lets an attempt with no outcome be told apart
/// from one that finished — the question a returning examiner is really asking.
const INGEST_REQUESTED: &str = "evidence_ingest_requested";
const INGEST_COMPLETED: &str = "evidence_ingest_completed";
const INGEST_FAILED: &str = "evidence_ingest_failed";

/// The name the request-time event carried before it was corrected.
///
/// It was written BEFORE hashing, so on a case ingested by an older build it
/// asserts that evidence was ingested when the hash may then have failed. It is
/// still read here — those attempts are part of the case and must not vanish
/// from this answer — but it is only ever read as "an ingest was requested",
/// which is all it ever actually witnessed.
const INGEST_REQUESTED_LEGACY: &str = "evidence_ingested";

/// The audit event written for every acquisition baseline that is recorded.
///
/// It predates the request/outcome split and is unchanged by it, which makes it
/// the one durable success signal an attempt from an older build can carry: a
/// build that never wrote an outcome event still wrote one of these for every
/// exhibit it hashed. Read here so an ingest whose baseline is demonstrably on
/// the record is not reported as an attempt of unknown disposition.
const ACQUISITION_BASELINE: &str = "evidence_acquisition_hashed";

/// How many of each ingest event to read. Ingest attempts are per exhibit, not
/// per artifact, so this is generous for a real case (S5 does not apply: four
/// million artifacts still come from a handful of exhibits) while keeping the
/// answer bounded on a case that somehow holds thousands.
const ACQUISITION_SCAN: i64 = 200;

/// How many attempts of each kind this endpoint will describe in full. Beyond
/// it the response says how many were left out rather than silently truncating.
const ACQUISITION_LIST_LIMIT: usize = 50;

/// The artifact ID an audit row refers to.
fn audit_resource_uuid(row: &serde_json::Value) -> Option<Uuid> {
    row["resource_id"]
        .as_str()
        .and_then(|s| Uuid::parse_str(s).ok())
}

/// The trailing path component, for a UI that has one line to name an exhibit.
fn path_basename(path: &str) -> String {
    std::path::Path::new(path)
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or(path)
        .to_string()
}

/// What an ingest attempt looked like at request time, from the audit log.
struct IngestRequestRow {
    id: i64,
    at: String,
    by: String,
    /// The canonical source path, which is what the request-time event records
    /// as its details.
    source_path: Option<String>,
    /// True when this row came from [`INGEST_REQUESTED_LEGACY`], i.e. was
    /// written by a build that had no outcome events to write. It changes what
    /// the silence after the request means, so it travels with the row.
    legacy: bool,
}

/// How a lookup of an exhibit's row in the artifact table came back, in the
/// form the response publishes it: `Some(true)` the row is in the case,
/// `Some(false)` it is not, `None` the artifact table could not be read.
///
/// The three are kept apart because collapsing the error into `false` states
/// that the exhibit is not in the case — an affirmative claim about what the
/// case holds, made from a database error. At triage that reads as "re-ingest
/// it"; in a statement it is simply a wrong sentence. `seance_core`'s
/// `evidence_row_disposition` has always kept the three apart, and this
/// endpoint now does too: the `None` serialises as JSON null, which a client
/// must read as "not determined", never as "absent".
fn evidence_row_exists<T, E>(lookup: &Result<Option<T>, E>) -> Option<bool> {
    match lookup {
        Ok(row) => Some(row.is_some()),
        Err(_) => None,
    }
}

#[cfg(test)]
mod evidence_row_lookup_tests {
    use super::evidence_row_exists;

    /// A read that succeeded answers the question; a read that failed did not
    /// ask it. Pinned here rather than through the endpoint because the failure
    /// mode is a database error, and the sentence it used to produce — "the
    /// exhibit is not in the case" — is one an examiner acts on.
    #[test]
    fn a_failed_read_is_not_reported_as_an_absent_row() {
        let present: Result<Option<u8>, &str> = Ok(Some(1));
        let absent: Result<Option<u8>, &str> = Ok(None);
        let unreadable: Result<Option<u8>, &str> = Err("database is locked");

        assert_eq!(evidence_row_exists(&present), Some(true));
        assert_eq!(evidence_row_exists(&absent), Some(false));
        assert_eq!(
            evidence_row_exists(&unreadable),
            None,
            "a failed artifact-table read must report 'not determined', never that the exhibit \
             is absent from the case"
        );
    }
}

/// Ingest attempts for this case: what is being acquired right now, what the
/// record leaves unresolved, and what has failed.
///
/// This exists because none of those questions could be answered by a client
/// that was not connected at the moment it happened. Acquisition hashing of a
/// large exhibit produces no completed evidence for as long as it runs, and its
/// progress went out only on the live event stream; an ingest that failed
/// produced one event and then nothing. A second tab, a colleague, or the same
/// examiner after a reload saw a case that looked idle — and, worse, an audit
/// log whose only ingest event had been written before the hash ran.
///
/// Three populations, stated separately because they are known in different
/// ways:
///
/// - `in_flight` — ingests THIS server process is currently running, with live
///   progress. Nothing else goes in this list. An attempt this process is not
///   carrying is not something this endpoint can say is in flight, however
///   recently it was requested.
/// - `unresolved` — attempts in this case's audit log with nothing on the
///   record after the request: no outcome event, no acquisition baseline, and
///   not running here. Their disposition is UNKNOWN, and the entry says which
///   kind of unknown it is, because the two are not the same claim:
///   `no_outcome_recorded` is a request from a build that would have written an
///   outcome and did not, which is what a server stopped mid-acquisition
///   leaves behind; `predates_outcome_events` is a request recorded under the
///   old `evidence_ingested` name by a build that wrote no outcome events at
///   all, where the absence of one says nothing whatsoever.
/// - `failed` — attempts whose failure IS on the record, most recent first,
///   carrying the audit detail verbatim and whether an evidence row for the
///   exhibit exists in the case.
///
/// An attempt with an outcome event, or with an `evidence_acquisition_hashed`
/// baseline recorded after it, is resolved and appears in none of the three;
/// the count of each is stated so the populations still add up.
///
/// All of them are scoped to the case, and the response states what its scans
/// actually read: the audit log remains the complete record.
pub async fn get_case_acquisitions(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let rows = |action: &'static str| {
        let db = state.db.clone();
        async move {
            db.get_audit_log_filtered(
                case_id,
                None,
                Some(action),
                None,
                None,
                None,
                ACQUISITION_SCAN,
                0,
            )
            .await
            .map_err(|e| {
                error!("Failed to read ingest audit events: {}", e);
                ApiError::InternalServerError("Failed to read the ingest audit trail".to_string())
            })
        }
    };

    let (requested_rows, legacy_rows, completed_rows, failed_rows, baseline_rows) = tokio::try_join!(
        rows(INGEST_REQUESTED),
        rows(INGEST_REQUESTED_LEGACY),
        rows(INGEST_COMPLETED),
        rows(INGEST_FAILED),
        rows(ACQUISITION_BASELINE),
    )?;

    // A scan that came back exactly full proves the case holds events older
    // than the ones it read; a short one proves the opposite, that it read
    // every event of that action this case holds. The two are different
    // answers and the response reports which it has, because "0 older
    // attempts" from a full window would be a count of rows nobody looked at.
    let filled = |scanned: &[serde_json::Value]| scanned.len() as i64 >= ACQUISITION_SCAN;
    let attempts_scan_filled_window = filled(&requested_rows) || filled(&legacy_rows);
    let failures_scan_filled_window = filled(&failed_rows);

    // An attempt is only judged "no outcome recorded" if an outcome for it
    // WOULD have been seen by these scans. When a scan filled its window, any
    // request older than the oldest outcome it read is outside it, and this
    // endpoint has no basis for a claim about it: it is counted as unexamined
    // rather than reported as unresolved.
    let scan_floor = |terminal: &[serde_json::Value]| -> i64 {
        if !filled(terminal) {
            i64::MIN
        } else {
            terminal
                .iter()
                .filter_map(|r| r["id"].as_i64())
                .min()
                .unwrap_or(i64::MIN)
        }
    };
    let outcome_floor = scan_floor(&completed_rows).max(scan_floor(&failed_rows));

    // The newest event of a kind per artifact. Keyed by row ID rather than
    // merely present/absent because an event only speaks for a request that
    // PRECEDES it: an exhibit ingested twice — the first attempt baselined, the
    // second interrupted — must not have its second attempt excused by the
    // first attempt's record.
    let newest_per_artifact = |scanned: &[serde_json::Value]| {
        let mut newest: std::collections::HashMap<Uuid, i64> = std::collections::HashMap::new();
        for row in scanned {
            let (Some(artifact_id), Some(row_id)) = (audit_resource_uuid(row), row["id"].as_i64())
            else {
                continue;
            };
            newest
                .entry(artifact_id)
                .and_modify(|existing| *existing = (*existing).max(row_id))
                .or_insert(row_id);
        }
        newest
    };
    let mut terminal = newest_per_artifact(&completed_rows);
    for (artifact_id, row_id) in newest_per_artifact(&failed_rows) {
        terminal
            .entry(artifact_id)
            .and_modify(|existing| *existing = (*existing).max(row_id))
            .or_insert(row_id);
    }
    let baselines = newest_per_artifact(&baseline_rows);

    // Request rows by artifact, newest first, so a live acquisition can be
    // labelled with who asked for it and when.
    let mut requests: std::collections::HashMap<Uuid, IngestRequestRow> =
        std::collections::HashMap::new();
    let mut unexamined = 0usize;
    let mut attempts_scanned = 0usize;
    for (row, legacy) in requested_rows
        .iter()
        .map(|r| (r, false))
        .chain(legacy_rows.iter().map(|r| (r, true)))
    {
        let Some(artifact_id) = audit_resource_uuid(row) else {
            continue;
        };
        attempts_scanned += 1;
        let id = row["id"].as_i64().unwrap_or(i64::MIN);
        if id < outcome_floor {
            unexamined += 1;
            continue;
        }
        let entry = IngestRequestRow {
            id,
            at: row["timestamp"].as_str().unwrap_or_default().to_string(),
            by: row["user_id"].as_str().unwrap_or_default().to_string(),
            source_path: row["details"]
                .as_str()
                .filter(|s| !s.is_empty())
                .map(String::from),
            legacy,
        };
        requests
            .entry(artifact_id)
            .and_modify(|existing| {
                if entry.id > existing.id {
                    existing.id = entry.id;
                    existing.at = entry.at.clone();
                    existing.by = entry.by.clone();
                    existing.source_path = entry.source_path.clone();
                    existing.legacy = entry.legacy;
                }
            })
            .or_insert(entry);
    }

    // The exhibit's name as the case knows it, when a row for it exists. Also
    // the answer to "is this exhibit in the case at all?", which is what an
    // examiner reading a failure needs to know next.
    let artifact_row = |artifact_id: Uuid| {
        let db = state.db.clone();
        async move { db.get_artifact(artifact_id).await }
    };

    // 1. What this process is actually running, with live progress.
    let live = state.ingestion_service.acquisitions_in_flight(case_id);
    let live_ids: std::collections::HashSet<Uuid> = live.iter().map(|a| a.artifact_id).collect();
    let mut in_flight: Vec<serde_json::Value> = Vec::new();
    for entry in &live {
        let request = requests.get(&entry.artifact_id);
        // Reported for the live entries too, because there is a real window —
        // between the request being accepted and the row being written — where
        // the exhibit is being acquired and has no card on any screen yet.
        let lookup = artifact_row(entry.artifact_id).await;
        let percent = match (entry.bytes_total, entry.bytes_done) {
            (Some(total), done) if total > 0 => {
                serde_json::json!(((done as f64 / total as f64) * 1000.0).round() / 10.0)
            }
            _ => serde_json::Value::Null,
        };
        let name = entry.name.clone().or_else(|| {
            entry
                .source_path
                .as_deref()
                .map(path_basename)
                .or_else(|| request.and_then(|r| r.source_path.as_deref().map(path_basename)))
        });
        in_flight.push(serde_json::json!({
            "artifact_id": entry.artifact_id,
            "source_path": entry.source_path.clone()
                .or_else(|| request.and_then(|r| r.source_path.clone())),
            "name": name,
            "phase": entry.phase,
            "bytes_done": entry.bytes_done,
            "bytes_total": entry.bytes_total,
            "percent": percent,
            "started_at": entry.started_at,
            "updated_at": entry.updated_at,
            "requested_at": request.map(|r| r.at.clone()),
            "requested_by": request.map(|r| r.by.clone()),
            "live": true,
            "evidence_row_exists": evidence_row_exists(&lookup),
            "state_note": match entry.phase {
                seance_core::ingestion::AcquisitionPhase::Queued =>
                    "Accepted and not yet reading bytes. No artifacts from it exist yet.",
                seance_core::ingestion::AcquisitionPhase::Hashing =>
                    "Computing the acquisition baseline. The exhibit is in the case with its \
                     integrity state still 'verifying'; artifacts appear as processing runs.",
            },
        }));
    }

    // 2. Attempts the record leaves unresolved, and the two different reasons a
    //    record can be silent after the request. Neither is "in flight": this
    //    process is not carrying them, and saying otherwise would turn the
    //    whole ingest history of an inherited case into a list of exhibits
    //    apparently mid-hash.
    let mut unresolved_requests: Vec<(&Uuid, &IngestRequestRow)> = Vec::new();
    let mut resolved_by_outcome = 0usize;
    let mut resolved_by_baseline = 0usize;
    for (artifact_id, request) in requests.iter() {
        if live_ids.contains(artifact_id) {
            continue;
        }
        if terminal
            .get(artifact_id)
            .is_some_and(|outcome_id| *outcome_id > request.id)
        {
            resolved_by_outcome += 1;
            continue;
        }
        // The durable success signal that survives the audit-event rename:
        // `record_acquisition_baseline` has always written one of these per
        // exhibit, so a case ingested by a build that knew nothing of outcome
        // events still says, on its own record, that the acquisition ran to its
        // end and the digests are held.
        if baselines
            .get(artifact_id)
            .is_some_and(|baseline_id| *baseline_id > request.id)
        {
            resolved_by_baseline += 1;
            continue;
        }
        unresolved_requests.push((artifact_id, request));
    }
    unresolved_requests.sort_by_key(|(_, request)| std::cmp::Reverse(request.id));
    let unresolved_omitted = unresolved_requests
        .len()
        .saturating_sub(ACQUISITION_LIST_LIMIT);
    let mut unresolved: Vec<serde_json::Value> = Vec::new();
    for (artifact_id, request) in unresolved_requests.into_iter().take(ACQUISITION_LIST_LIMIT) {
        let lookup = artifact_row(*artifact_id).await;
        let row = lookup.as_ref().ok().and_then(|r| r.as_ref());
        let name = row
            .and_then(|a| a.metadata.get("name").and_then(|v| v.as_str()))
            .map(String::from)
            .or_else(|| request.source_path.as_deref().map(path_basename));
        let (disposition, state_note) = if request.legacy {
            (
                "predates_outcome_events",
                "This ingest was recorded under the older 'evidence_ingested' action, by a \
                 build that wrote no ingest outcome events at all. No outcome event could have \
                 been recorded for it, so the absence of one is not evidence that the \
                 acquisition was interrupted — it is a fact about the build, not about this \
                 exhibit. No acquisition baseline for it appears in the scanned record either, \
                 so its disposition is simply NOT KNOWN here; the exhibit's own integrity \
                 record is where to look next.",
            )
        } else {
            (
                "no_outcome_recorded",
                "This ingest was requested and no outcome was ever recorded, no acquisition \
                 baseline for it appears in the scanned record, and this server is not running \
                 it — which is what a server stopped mid-acquisition leaves behind. Whether it \
                 completed is NOT known from this record; check the exhibit before relying on \
                 it.",
            )
        };
        unresolved.push(serde_json::json!({
            "artifact_id": artifact_id,
            "source_path": request.source_path.clone(),
            "name": name,
            "phase": "unknown",
            "bytes_done": serde_json::Value::Null,
            "bytes_total": serde_json::Value::Null,
            "percent": serde_json::Value::Null,
            "started_at": serde_json::Value::Null,
            "updated_at": serde_json::Value::Null,
            "requested_at": request.at.clone(),
            "requested_by": request.by.clone(),
            "live": false,
            "evidence_row_exists": evidence_row_exists(&lookup),
            "disposition": disposition,
            "state_note": state_note,
        }));
    }

    // 3. Failures, from the record rather than from a toast nobody saw.
    let failures_omitted = failed_rows.len().saturating_sub(ACQUISITION_LIST_LIMIT);
    let mut failed: Vec<serde_json::Value> = Vec::new();
    for row in failed_rows.iter().take(ACQUISITION_LIST_LIMIT) {
        let Some(artifact_id) = audit_resource_uuid(row) else {
            continue;
        };
        let request = requests.get(&artifact_id);
        let lookup = artifact_row(artifact_id).await;
        let artifact = lookup.as_ref().ok().and_then(|r| r.as_ref());
        let source_path = request.and_then(|r| r.source_path.clone()).or_else(|| {
            artifact
                .and_then(|a| a.metadata.get("source_path").and_then(|v| v.as_str()))
                .map(String::from)
        });
        let name = artifact
            .and_then(|a| a.metadata.get("name").and_then(|v| v.as_str()))
            .map(String::from)
            .or_else(|| source_path.as_deref().map(path_basename));
        failed.push(serde_json::json!({
            "artifact_id": artifact_id,
            "source_path": source_path,
            "name": name,
            "failed_at": row["timestamp"],
            "requested_at": request.map(|r| r.at.clone()),
            "requested_by": request.map(|r| r.by.clone()),
            // Verbatim from the audit record — the sentence that will be read
            // back in a statement is the sentence that was written, not a
            // paraphrase of it.
            "detail": row["details"],
            "evidence_row_exists": evidence_row_exists(&lookup),
        }));
    }

    // What the scans read, said as what they read rather than as what exists.
    let attempts_disclosure = if attempts_scan_filled_window {
        format!(
            "Attempts are read from the {ACQUISITION_SCAN} most recent events of each ingest \
             action, and that window came back full: this case holds ingest attempts older than \
             the {attempts_scanned} read here, and their number is not known here. Of the ones \
             read, {unexamined} fell outside the outcome scans and are not classified."
        )
    } else {
        format!(
            "Every ingest request event this case holds was read ({attempts_scanned} in all), \
             of which {unexamined} fell outside the outcome scans and are not classified."
        )
    };
    let failures_disclosure = if failures_scan_filled_window {
        format!(
            "Failures are read from the {ACQUISITION_SCAN} most recent failure events and that \
             window came back full too, so this case has recorded failures older than the ones \
             counted here."
        )
    } else {
        format!(
            "Every recorded failure for this case was read ({} in all).",
            failed_rows.len()
        )
    };

    // The processing side (HUNT-113): one row per ingest run, from queueing
    // to the case going idle, or to a later start finding it never did. This
    // is what tells an interrupted walk from a finished one after a restart,
    // which nothing above can — acquisition is the hash, not the walk.
    let processing_runs: Vec<serde_json::Value> = match state.db.list_ingest_runs(case_id).await {
        Ok(runs) => runs
            .into_iter()
            .map(|run| {
                serde_json::json!({
                    "id": run.id,
                    "source_artifact_id": run.source_artifact_id,
                    "source_label": run.source_label,
                    "started_at": run.started_at,
                    "finished_at": run.finished_at,
                    "status": run.status,
                    "artifacts_recorded": run.artifacts_recorded,
                    "detail": run.detail,
                })
            })
            .collect(),
        Err(e) => {
            error!("Failed to list ingest runs: {}", e);
            return Err(ApiError::InternalServerError(
                "Failed to list ingest runs".to_string(),
            ));
        }
    };
    let interrupted_runs = processing_runs
        .iter()
        .filter(|r| r["status"] == "interrupted" || r["status"] == "cancelled")
        .count();

    Ok(Json(serde_json::json!({
        "case_id": case_id,
        // Only what this process is carrying. An attempt nobody is running is
        // not in flight, whatever the record does or does not say about it.
        "in_flight": in_flight,
        // Processing runs, newest first. `running` means a process is walking
        // the source now; `interrupted` means one was and stopped before the
        // walk ended, and the source is stamped incomplete in the case.
        "processing_runs": processing_runs,
        "processing_runs_unfinished": interrupted_runs,
        "in_flight_count": in_flight.len(),
        "live_count": live.len(),
        // Attempts with nothing on the record after the request. Listed
        // separately from `in_flight` because "unknown" and "running" are
        // different claims, and only one of them is true here.
        "unresolved": unresolved,
        "unresolved_count": unresolved.len(),
        "unresolved_omitted": unresolved_omitted,
        "failed": failed,
        "failed_count": failed.len(),
        "failed_omitted": failures_omitted,
        // Attempts excluded from all three lists because the record resolves
        // them, counted so the stated population still adds up.
        "attempts_resolved_by_outcome": resolved_by_outcome,
        "attempts_resolved_by_baseline": resolved_by_baseline,
        "attempts_scanned": attempts_scanned,
        "attempts_outside_outcome_scan": unexamined,
        // True means older attempts exist that this response did not read, so
        // no count here may be read as a case total.
        "attempts_scan_filled_window": attempts_scan_filled_window,
        "failures_scan_filled_window": failures_scan_filled_window,
        "population": format!(
            "Ingest attempts for this case: those this server process is running now (live \
             progress), those the record leaves unresolved, and the most recent recorded \
             failures. {resolved_by_outcome} attempt(s) are excluded as resolved by a recorded \
             outcome and {resolved_by_baseline} as resolved by a recorded acquisition baseline. \
             {attempts_disclosure} {failures_disclosure} This is not a list of the case's \
             evidence — the audit log is the complete record of ingest attempts."
        ),
    })))
}

/// Parse relative date strings like "7d", "24h", "30d", "1y" into a timestamp
/// Returns the timestamp for the start of the range
fn parse_relative_date(relative: &str) -> Result<i64, String> {
    use chrono::{Datelike, Timelike, Utc};

    let now = Utc::now();

    // Handle special keywords
    match relative {
        "today" => {
            // Start of today (midnight UTC)
            let start_of_day = now
                .with_hour(0)
                .ok_or("Failed to set hour")?
                .with_minute(0)
                .ok_or("Failed to set minute")?
                .with_second(0)
                .ok_or("Failed to set second")?
                .with_nanosecond(0)
                .ok_or("Failed to set nanosecond")?;
            return Ok(start_of_day.timestamp());
        }
        "yesterday" => {
            let yesterday = now - chrono::Duration::days(1);
            let start_of_yesterday = yesterday
                .with_hour(0)
                .ok_or("Failed to set hour")?
                .with_minute(0)
                .ok_or("Failed to set minute")?
                .with_second(0)
                .ok_or("Failed to set second")?
                .with_nanosecond(0)
                .ok_or("Failed to set nanosecond")?;
            return Ok(start_of_yesterday.timestamp());
        }
        "this_week" => {
            // Start of this week (Monday at midnight)
            let today_weekday = now.weekday();
            let days_from_monday = today_weekday.num_days_from_monday();
            let monday = now - chrono::Duration::days(days_from_monday as i64);
            let start_of_week = monday
                .with_hour(0)
                .ok_or("Failed to set hour")?
                .with_minute(0)
                .ok_or("Failed to set minute")?
                .with_second(0)
                .ok_or("Failed to set second")?
                .with_nanosecond(0)
                .ok_or("Failed to set nanosecond")?;
            return Ok(start_of_week.timestamp());
        }
        "this_month" => {
            // Start of this month (1st day at midnight)
            let start_of_month = now
                .with_day(1)
                .ok_or("Failed to set day")?
                .with_hour(0)
                .ok_or("Failed to set hour")?
                .with_minute(0)
                .ok_or("Failed to set minute")?
                .with_second(0)
                .ok_or("Failed to set second")?
                .with_nanosecond(0)
                .ok_or("Failed to set nanosecond")?;
            return Ok(start_of_month.timestamp());
        }
        "this_year" => {
            // Start of this year (Jan 1 at midnight)
            let start_of_year = now
                .with_month(1)
                .ok_or("Failed to set month")?
                .with_day(1)
                .ok_or("Failed to set day")?
                .with_hour(0)
                .ok_or("Failed to set hour")?
                .with_minute(0)
                .ok_or("Failed to set minute")?
                .with_second(0)
                .ok_or("Failed to set second")?
                .with_nanosecond(0)
                .ok_or("Failed to set nanosecond")?;
            return Ok(start_of_year.timestamp());
        }
        _ => {}
    }

    // Parse numeric relative dates like "7d", "24h", "30d"
    if relative.len() < 2 {
        return Err(format!("Invalid relative date format: {}", relative));
    }

    let (number_part, unit) = relative.split_at(relative.len() - 1);
    let num: i64 = number_part
        .parse()
        .map_err(|_| format!("Invalid number in relative date: {}", number_part))?;

    let past_time = match unit {
        "h" => now - chrono::Duration::hours(num),
        "d" => now - chrono::Duration::days(num),
        "w" => now - chrono::Duration::weeks(num),
        "m" => now - chrono::Duration::days(num * 30), // Approximate
        "y" => now - chrono::Duration::days(num * 365), // Approximate
        _ => return Err(format!("Unknown time unit: {} (use h/d/w/m/y)", unit)),
    };

    Ok(past_time.timestamp())
}

pub async fn get_timeline(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
) -> Result<Json<PaginatedTimelineResponse>, ApiError> {
    info!(
        "Received request to get timeline for case {} with params: {:?}",
        case_id, params
    );

    // Parse pagination parameters. Floor page at 1 (a 0/negative page would
    // make offset negative and wrap to a huge usize) and bound page_size so a
    // client cannot request an unbounded result set (also avoids a div-by-zero
    // in the total_pages calculation below).
    let page = params
        .get("page")
        .and_then(|s| s.parse::<i64>().ok())
        .unwrap_or(1)
        .max(1);
    let page_size = params
        .get("page_size")
        .and_then(|s| s.parse::<i64>().ok())
        .unwrap_or(100)
        .clamp(1, TIMELINE_MAX_PAGE_SIZE);

    // Calculate limit and offset from page and page_size. One row past the page
    // is fetched deliberately (B8-041): `has_next` used to be inferred from the
    // page coming back full, which is wrong in both directions -- a page that
    // exactly ends the data claimed another page, and a page shortened by a row
    // the query could not decode claimed to be the last. The probe row is
    // dropped before the response is built.
    let limit = Some((page_size as usize).saturating_add(1));
    // Saturating: `?page=9223372036854775807` must not overflow the multiply.
    let offset = Some((page - 1).saturating_mul(page_size) as usize);

    // Handle date range parameters
    let mut from_ts = params.get("from").and_then(|s| s.parse::<i64>().ok());
    let mut to_ts = params.get("to").and_then(|s| s.parse::<i64>().ok());

    // Handle relative date parameter (e.g., "range=7d" or "range=this_month")
    if let Some(relative) = params.get("range") {
        match parse_relative_date(relative) {
            Ok(start_ts) => {
                let end_ts = chrono::Utc::now().timestamp();
                from_ts = Some(start_ts);
                to_ts = Some(end_ts);
                info!(
                    "Parsed relative date '{}' to range: {} - {}",
                    relative, start_ts, end_ts
                );
            }
            Err(e) => {
                warn!("Failed to parse relative date '{}': {}", relative, e);
                return Err(ApiError::InvalidRequest(format!(
                    "Invalid relative date format: {}",
                    e
                )));
            }
        }
    }

    // Handle source module filtering (supports comma-separated list). Empty
    // names are dropped and a list of nothing but empty names is no filter,
    // for the reason `parse_name_list` gives (HUNT-034).
    let source_modules: Option<Vec<String>> = parse_name_list(params.get("modules"));

    // Handle text search parameter - parse advanced search syntax
    let _search_query = params.get("search").and_then(|s| {
        if s.is_empty() {
            None
        } else {
            match search::SearchQuery::parse(s) {
                Ok(query) => Some(query),
                Err(e) => {
                    warn!("Failed to parse search query '{}': {}", s, e);
                    // Fall back to simple search
                    None
                }
            }
        }
    });
    let search_text = params.get("search").map(|s| s.as_str());

    // Handle column-specific filters
    let filename_filter = params.get("filter_filename").map(|s| s.as_str());
    let event_type_filter = params.get("filter_event_type").map(|s| s.as_str());

    // Handle sorting parameters
    let sort_by = params
        .get("sort_by")
        .map(|s| s.as_str())
        .unwrap_or("timestamp");
    let sort_order = params
        .get("sort_order")
        .map(|s| s.as_str())
        .unwrap_or("desc");

    // Handle dynamic columns parameter (comma-separated JSON paths like "$.filename,$.file_size")
    let dynamic_columns: Option<Vec<String>> = parse_name_list(params.get("columns"));

    // Handle tagged-only filter
    let tagged_only = params
        .get("tagged_only")
        .and_then(|s| s.parse::<bool>().ok())
        .unwrap_or(false);

    // If tagged_only is true, get the list of tagged event IDs
    let tagged_event_ids: Option<Vec<Vec<u8>>> = if tagged_only {
        let tags = state.db.list_timeline_tags(case_id).await.map_err(|e| {
            error!("Failed to list timeline tags for filtering: {}", e);
            ApiError::InternalServerError(format!("Failed to list tags: {}", e))
        })?;
        Some(
            tags.into_iter()
                .map(|tag| tag.event_id.as_bytes().to_vec())
                .collect(),
        )
    } else {
        None
    };

    // Fetch the page first so the count can be skipped without losing the rows.
    let mut events = state
        .db
        .get_timeline_events_filtered(
            case_id,
            from_ts,
            to_ts,
            source_modules.as_deref(),
            search_text,
            filename_filter,
            event_type_filter,
            limit,
            offset,
            Some(sort_by),
            Some(sort_order),
            dynamic_columns.as_deref(),
            tagged_event_ids.as_deref(),
        )
        .await
        .map_err(|e| {
            error!("Failed to fetch filtered timeline events: {}", e);
            ApiError::InternalServerError(format!("Failed to fetch timeline events: {}", e))
        })?;

    // The probe row decides `has_next`, and it is dropped here so it never
    // reaches the client as an extra event. This is a fact about the same query
    // that produced the rows, unlike the count comparison below, which is a
    // second query that can disagree with this one.
    let has_next = events.len() as i64 > page_size;
    events.truncate(page_size as usize);

    // The filtered COUNT(*) rescans the (often huge) event set, yet the total
    // only changes when the filters change -- not when paging. The client sends
    // count=false while paging within one filter set and reuses the total it
    // fetched on page 1 / filter change. When skipped we return -1 for
    // total_count/total_pages (the "reuse your cached total" sentinel);
    // `has_next` above is unaffected either way.
    let want_count = params.get("count").map(|s| s != "false").unwrap_or(true);
    let (total_count, total_pages) = if want_count {
        let total_count = state
            .db
            .get_timeline_events_count(
                case_id,
                from_ts,
                to_ts,
                source_modules.as_deref(),
                search_text,
                filename_filter,
                event_type_filter,
                tagged_event_ids.as_deref(),
            )
            .await
            .map_err(|e| {
                error!("Failed to count timeline events: {}", e);
                ApiError::InternalServerError(format!("Failed to count timeline events: {}", e))
            })?;
        let total_pages = (total_count as f64 / page_size as f64).ceil() as i64;
        (total_count, total_pages)
    } else {
        (-1, -1)
    };
    let has_previous = page > 1;

    let response = PaginatedTimelineResponse {
        events,
        pagination: PaginationMetadata {
            total_count,
            page,
            page_size,
            total_pages,
            has_next,
            has_previous,
        },
    };

    Ok(Json(response))
}

/// Timeline filter parameters shared by the list and histogram endpoints.
struct TimelineFilterParams {
    from_ts: Option<i64>,
    to_ts: Option<i64>,
    source_modules: Option<Vec<String>>,
    search_text: Option<String>,
    filename_filter: Option<String>,
    event_type_filter: Option<String>,
    /// Tagged-event IDs when tagged_only=true was requested.
    tagged_event_ids: Option<Vec<Vec<u8>>>,
}

/// Parse the timeline filter query params (from/to/range/modules/search/
/// filter_filename/filter_event_type/tagged_only) with the same semantics as
/// the timeline list endpoint.
async fn parse_timeline_filters(
    state: &AppState,
    case_id: Uuid,
    params: &std::collections::HashMap<String, String>,
) -> Result<TimelineFilterParams, ApiError> {
    let mut from_ts = params.get("from").and_then(|s| s.parse::<i64>().ok());
    let mut to_ts = params.get("to").and_then(|s| s.parse::<i64>().ok());

    if let Some(relative) = params.get("range") {
        match parse_relative_date(relative) {
            Ok(start_ts) => {
                from_ts = Some(start_ts);
                to_ts = Some(chrono::Utc::now().timestamp());
            }
            Err(e) => {
                warn!("Failed to parse relative date '{}': {}", relative, e);
                return Err(ApiError::InvalidRequest(format!(
                    "Invalid relative date format: {}",
                    e
                )));
            }
        }
    }

    let source_modules: Option<Vec<String>> = parse_name_list(params.get("modules"));

    let search_text = params.get("search").filter(|s| !s.is_empty()).cloned();
    let filename_filter = params.get("filter_filename").cloned();
    let event_type_filter = params.get("filter_event_type").cloned();

    let tagged_only = params
        .get("tagged_only")
        .and_then(|s| s.parse::<bool>().ok())
        .unwrap_or(false);
    let tagged_event_ids: Option<Vec<Vec<u8>>> = if tagged_only {
        let tags = state.db.list_timeline_tags(case_id).await.map_err(|e| {
            error!("Failed to list timeline tags for filtering: {}", e);
            ApiError::InternalServerError(format!("Failed to list tags: {}", e))
        })?;
        Some(
            tags.into_iter()
                .map(|tag| tag.event_id.as_bytes().to_vec())
                .collect(),
        )
    } else {
        None
    };

    Ok(TimelineFilterParams {
        from_ts,
        to_ts,
        source_modules,
        search_text,
        filename_filter,
        event_type_filter,
        tagged_event_ids,
    })
}

/// "Friendly" histogram bucket widths in seconds: 1min, 5min, 15min, 1h, 6h,
/// 1d, 1w, ~1 month, ~1 year.
const FRIENDLY_BUCKET_SECONDS: [i64; 9] =
    [60, 300, 900, 3600, 21600, 86400, 604800, 2629800, 31557600];

/// Round a raw bucket width UP to the nearest friendly unit; spans wider than
/// a year per bucket use whole-year multiples.
fn friendly_bucket_seconds(raw: i64) -> i64 {
    for unit in FRIENDLY_BUCKET_SECONDS {
        if raw <= unit {
            return unit;
        }
    }
    let year = FRIENDLY_BUCKET_SECONDS[8];
    // Saturating on both sides: `raw` is derived from the extent of the
    // evidence's own timestamps, and a corrupt one near `i64::MAX` must widen
    // the buckets, not overflow (release builds keep overflow checks on).
    (raw.saturating_add(year - 1) / year).saturating_mul(year)
}

/// The bucket width for a histogram over `[min_ts, max_ts]` drawn in about
/// `buckets` bars, rounded up to a friendly unit.
///
/// Every step saturates. The extent comes from the timestamps parsers
/// recovered from evidence, and a corrupt FILETIME or a mis-decoded epoch can
/// put one at either end of `i64`; `max_ts - min_ts` then overflowed, and with
/// `overflow-checks = true` in the release profile that was a panic — the
/// histogram and swimlane endpoints answered 500 for the whole case because of
/// one absurd timestamp. `buckets` is clamped to at least 10 by the callers, so
/// the division is safe.
fn histogram_bucket_seconds(min_ts: i64, max_ts: i64, buckets: i64) -> i64 {
    let buckets = buckets.max(1);
    let span = max_ts.saturating_sub(min_ts);
    let raw = std::cmp::max(1, span / buckets + i64::from(span % buckets != 0));
    friendly_bucket_seconds(raw)
}

/// Where the bulk of a time chart's events sit, in bucket indices, and how many
/// events fall outside that window at each end.
///
/// This is the Rust half of a rule the product states in two places, and the
/// two must not drift: `frontend/src/lib/focusWindow.ts` runs the same
/// algorithm for the charts that have no server-side focus (the dashboard's
/// mini timeline and the rich viewers' charts). The unit tests below are the
/// same fixtures as that module's, for exactly that reason. **Change one and
/// you must change the other**, or two screens will tell the same case two
/// ways, which is the failure `UI-007` exists to prevent.
///
/// The rule: an end is trimmed only when it is BOTH a small share of all events
/// (`trim_fraction` per end) AND separated from the mass by a long empty gap.
/// The second condition is what tells an artefactual timestamp — a FAT epoch in
/// 1980, a corrupt far-future stamp — from genuine sparse early activity, which
/// is often the most interesting thing in a case and is never trimmed for being
/// sparse alone. Everything trimmed is counted and returned so the caller can
/// disclose it; nothing is hidden.
fn focus_window(dense: &[i64]) -> (usize, usize, i64, i64) {
    const TRIM_FRACTION: f64 = 0.01;
    const MIN_GAP_FRACTION: f64 = 0.1;

    if dense.is_empty() {
        return (0, 0, 0, 0);
    }
    let mut lo = 0usize;
    let mut hi = dense.len() - 1;
    let total: i64 = dense.iter().sum();
    if total == 0 {
        return (lo, hi, 0, 0);
    }

    let budget = total as f64 * TRIM_FRACTION;
    // At least two empty buckets: one empty slot is ordinary quiet, not the
    // decades-wide void that separates an artefactual timestamp from real work.
    let min_gap = std::cmp::max(2, (dense.len() as f64 * MIN_GAP_FRACTION) as usize);

    let gap_after = |i: usize| -> usize {
        let mut g = 0;
        let mut j = i + 1;
        while j < dense.len() && dense[j] == 0 {
            g += 1;
            j += 1;
        }
        g
    };
    let gap_before = |i: usize| -> usize {
        let mut g = 0;
        let mut j = i;
        while j > 0 && dense[j - 1] == 0 {
            g += 1;
            j -= 1;
        }
        g
    };

    let mut before = 0i64;
    while lo < hi && (before + dense[lo]) as f64 <= budget {
        if dense[lo] == 0 {
            lo += 1;
            continue;
        }
        if gap_after(lo) < min_gap {
            break;
        }
        before += dense[lo];
        lo += 1;
    }
    let mut after = 0i64;
    while hi > lo && (after + dense[hi]) as f64 <= budget {
        if dense[hi] == 0 {
            hi -= 1;
            continue;
        }
        if gap_before(hi) < min_gap {
            break;
        }
        after += dense[hi];
        hi -= 1;
    }
    (lo, hi, before, after)
}

/// A histogram's bars as a dense array of counts, one slot per `bucket_seconds`
/// from the first bucket to the last, so [`focus_window`] sees the empty spans
/// as well as the occupied ones. A sparse response has no gaps to measure.
fn densify(buckets: &[(i64, i64)], bucket_seconds: i64) -> Vec<i64> {
    /// Cap on the dense array, mirroring the client's own render cap. A
    /// pathological extent divided by a friendly bucket width cannot make this
    /// allocate without bound.
    const MAX_SLOTS: usize = 4000;
    if bucket_seconds <= 0 || buckets.is_empty() {
        return Vec::new();
    }
    let first = buckets[0].0;
    let last = buckets[buckets.len() - 1].0;
    let by_start: std::collections::HashMap<i64, i64> = buckets.iter().copied().collect();
    let mut out = Vec::new();
    let mut t = first;
    while t <= last && out.len() < MAX_SLOTS {
        out.push(by_start.get(&t).copied().unwrap_or(0));
        match t.checked_add(bucket_seconds) {
            Some(next) => t = next,
            None => break,
        }
    }
    out
}

/// The window a focused time chart should draw, given one pass of buckets over
/// the whole extent: the times to re-query between, and what is outside them.
///
/// `None` when nothing is trimmed — the chart already shows where the events
/// are, and a second query would ask the same question twice.
struct ChartFocus {
    from_ts: i64,
    to_ts: i64,
    before: i64,
    after: i64,
}

fn chart_focus(buckets: &[(i64, i64)], bucket_seconds: i64) -> Option<ChartFocus> {
    let dense = densify(buckets, bucket_seconds);
    if dense.is_empty() {
        return None;
    }
    let (lo, hi, before, after) = focus_window(&dense);
    if before == 0 && after == 0 {
        return None;
    }
    let first = buckets[0].0;
    let from_ts = first.saturating_add((lo as i64).saturating_mul(bucket_seconds));
    // The window ends at the END of the last kept bucket, so the last bar is
    // inside it; `to` is exclusive at the API's own timeline filter.
    let to_ts = first
        .saturating_add((hi as i64).saturating_mul(bucket_seconds))
        .saturating_add(bucket_seconds);
    Some(ChartFocus {
        from_ts,
        to_ts,
        before,
        after,
    })
}

/// Whether the caller asked for the chart to be focused on where the events
/// are. Absent — every existing caller, the REPL and the report layer among
/// them — the endpoint answers over the whole extent exactly as before.
fn wants_focus(params: &std::collections::HashMap<String, String>) -> bool {
    matches!(params.get("focus").map(String::as_str), Some("auto"))
}

/// Pattern-of-life activity heatmap: event counts by (day-of-week, hour) in UTC.
pub async fn get_timeline_activity(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let cells = state.db.get_timeline_activity(case_id).await.map_err(|e| {
        error!("Failed to compute timeline activity: {}", e);
        ApiError::InternalServerError("Failed to compute timeline activity".to_string())
    })?;

    let total: i64 = cells.iter().map(|(_, _, n)| *n).sum();
    let max: i64 = cells.iter().map(|(_, _, n)| *n).max().unwrap_or(0);
    let cell_objs: Vec<serde_json::Value> = cells
        .into_iter()
        .map(|(dow, hour, count)| serde_json::json!({ "dow": dow, "hour": hour, "count": count }))
        .collect();

    Ok(Json(serde_json::json!({
        "cells": cell_objs,
        "total": total,
        "max": max,
    })))
}

pub async fn get_timeline_histogram(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let filters = parse_timeline_filters(&state, case_id, &params).await?;

    let buckets: i64 = params
        .get("buckets")
        .and_then(|s| s.parse().ok())
        .unwrap_or(120)
        .clamp(10, 500);

    let extent = state
        .db
        .get_timeline_extent(
            case_id,
            filters.from_ts,
            filters.to_ts,
            filters.source_modules.as_deref(),
            filters.search_text.as_deref(),
            filters.filename_filter.as_deref(),
            filters.event_type_filter.as_deref(),
            filters.tagged_event_ids.as_deref(),
        )
        .await
        .map_err(|e| {
            error!("Failed to compute timeline extent: {}", e);
            ApiError::InternalServerError("Failed to compute timeline extent".to_string())
        })?;

    let Some((min_ts, max_ts)) = extent else {
        return Ok(Json(serde_json::json!({
            "min_ts": null,
            "max_ts": null,
            "bucket_seconds": null,
            "buckets": [],
        })));
    };

    let mut bucket_seconds = histogram_bucket_seconds(min_ts, max_ts, buckets);

    let histogram_at = |bucket_seconds: i64, from_ts: Option<i64>, to_ts: Option<i64>| {
        let filters = &filters;
        let state = &state;
        async move {
            state
                .db
                .get_timeline_histogram(
                    case_id,
                    from_ts,
                    to_ts,
                    filters.source_modules.as_deref(),
                    filters.search_text.as_deref(),
                    filters.filename_filter.as_deref(),
                    filters.event_type_filter.as_deref(),
                    filters.tagged_event_ids.as_deref(),
                    bucket_seconds,
                )
                .await
                .map_err(|e| {
                    error!("Failed to compute timeline histogram: {}", e);
                    ApiError::InternalServerError(
                        "Failed to compute timeline histogram".to_string(),
                    )
                })
        }
    };

    let mut histogram = histogram_at(bucket_seconds, filters.from_ts, filters.to_ts).await?;

    // `focus=auto`: draw where the events are, at a resolution chosen for THAT
    // window rather than for the whole extent (`UI-010`). One FAT-epoch 1980
    // stamp otherwise sets the bucket width to a year and collapses four
    // decades of real work into one or two bars — readable, but far coarser
    // than the case deserves.
    //
    // The width follows the window because that is how the question is asked:
    // the resolution of an aggregation is a property of the range it covers,
    // which is what every mature analytics tool does when a range is zoomed.
    // Doing it here rather than in the client keeps ONE answer for a given
    // request, so the screen, an export and a report cannot each pick their own.
    //
    // Nothing is hidden by it: the events outside the window are counted and
    // returned in `focus`, the endpoint still reports the FULL extent in
    // `min_ts`/`max_ts`, and without the parameter the answer is what it always
    // was.
    let mut focus_json = serde_json::Value::Null;
    if wants_focus(&params) {
        if let Some(focus) = chart_focus(&histogram, bucket_seconds) {
            let focused_seconds = histogram_bucket_seconds(focus.from_ts, focus.to_ts, buckets);
            let focused = histogram_at(
                focused_seconds,
                Some(focus.from_ts),
                // The window's end is the end of the last kept bucket; the
                // timeline filter's `to` is inclusive, so step back one second
                // rather than pulling in the first event of the next bucket.
                Some(focus.to_ts.saturating_sub(1)),
            )
            .await?;
            if !focused.is_empty() {
                histogram = focused;
                bucket_seconds = focused_seconds;
                focus_json = serde_json::json!({
                    "from": focus.from_ts,
                    "to": focus.to_ts,
                    "events_before": focus.before,
                    "events_after": focus.after,
                });
            }
        }
    }

    let bucket_objs: Vec<serde_json::Value> = histogram
        .into_iter()
        .map(|(start, count)| serde_json::json!({ "start": start, "count": count }))
        .collect();

    Ok(Json(serde_json::json!({
        "min_ts": min_ts,
        "max_ts": max_ts,
        "bucket_seconds": bucket_seconds,
        "buckets": bucket_objs,
        "focus": focus_json,
    })))
}

/// Timeline histogram split into per-source-module lanes (swimlanes): shows
/// which sources were active over time, on the same axis and filters as the
/// aggregate histogram. Lanes are ordered by volume; overflow beyond the cap
/// is folded into an "Other" lane so nothing is silently dropped.
pub async fn get_timeline_swimlanes(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
) -> Result<Json<serde_json::Value>, ApiError> {
    const MAX_LANES: usize = 12;
    let filters = parse_timeline_filters(&state, case_id, &params).await?;

    let buckets: i64 = params
        .get("buckets")
        .and_then(|s| s.parse().ok())
        .unwrap_or(120)
        .clamp(10, 500);

    let extent = state
        .db
        .get_timeline_extent(
            case_id,
            filters.from_ts,
            filters.to_ts,
            filters.source_modules.as_deref(),
            filters.search_text.as_deref(),
            filters.filename_filter.as_deref(),
            filters.event_type_filter.as_deref(),
            filters.tagged_event_ids.as_deref(),
        )
        .await
        .map_err(|e| {
            error!("Failed to compute timeline extent: {}", e);
            ApiError::InternalServerError("Failed to compute timeline extent".to_string())
        })?;

    let Some((min_ts, max_ts)) = extent else {
        return Ok(Json(serde_json::json!({
            "min_ts": null, "max_ts": null, "bucket_seconds": null,
            "lanes": [], "truncated_lanes": false,
        })));
    };

    let mut bucket_seconds = histogram_bucket_seconds(min_ts, max_ts, buckets);

    let rows_at = |bucket_seconds: i64, from_ts: Option<i64>, to_ts: Option<i64>| {
        let filters = &filters;
        let state = &state;
        async move {
            state
                .db
                .get_timeline_histogram_by_source(
                    case_id,
                    from_ts,
                    to_ts,
                    filters.source_modules.as_deref(),
                    filters.search_text.as_deref(),
                    filters.filename_filter.as_deref(),
                    filters.event_type_filter.as_deref(),
                    filters.tagged_event_ids.as_deref(),
                    bucket_seconds,
                )
                .await
                .map_err(|e| {
                    error!("Failed to compute timeline swimlanes: {}", e);
                    ApiError::InternalServerError(
                        "Failed to compute timeline swimlanes".to_string(),
                    )
                })
        }
    };

    let mut rows = rows_at(bucket_seconds, filters.from_ts, filters.to_ts).await?;

    // `focus=auto`, exactly as the aggregate histogram does it (`UI-010`), and
    // for a reason beyond resolution: these lanes are drawn directly beneath
    // that histogram on the same page, so a window chosen for one and not the
    // other would put two charts of one case on one screen with two different
    // axes. The window is derived from the summed lanes, which is the same
    // series the histogram focuses on.
    let mut focus_json = serde_json::Value::Null;
    if wants_focus(&params) {
        let mut summed: std::collections::BTreeMap<i64, i64> = std::collections::BTreeMap::new();
        for (_, start, count) in &rows {
            *summed.entry(*start).or_insert(0) += count;
        }
        let summed: Vec<(i64, i64)> = summed.into_iter().collect();
        if let Some(focus) = chart_focus(&summed, bucket_seconds) {
            let focused_seconds = histogram_bucket_seconds(focus.from_ts, focus.to_ts, buckets);
            let focused = rows_at(
                focused_seconds,
                Some(focus.from_ts),
                Some(focus.to_ts.saturating_sub(1)),
            )
            .await?;
            if !focused.is_empty() {
                rows = focused;
                bucket_seconds = focused_seconds;
                focus_json = serde_json::json!({
                    "from": focus.from_ts,
                    "to": focus.to_ts,
                    "events_before": focus.before,
                    "events_after": focus.after,
                });
            }
        }
    }

    // Group (source, start, count) rows into per-source lanes with a running total.
    use std::collections::HashMap;
    let mut lanes: HashMap<String, (i64, Vec<(i64, i64)>)> = HashMap::new();
    for (src, start, count) in rows {
        let e = lanes.entry(src).or_insert_with(|| (0, Vec::new()));
        e.0 += count;
        e.1.push((start, count));
    }
    let mut lane_vec: Vec<(String, i64, Vec<(i64, i64)>)> =
        lanes.into_iter().map(|(s, (t, b))| (s, t, b)).collect();
    lane_vec.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    // Fold overflow lanes into a single "Other" lane (bucket sums merged).
    let truncated_lanes = lane_vec.len() > MAX_LANES;
    let overflow: Vec<(String, i64, Vec<(i64, i64)>)> = if truncated_lanes {
        lane_vec.split_off(MAX_LANES)
    } else {
        Vec::new()
    };
    if !overflow.is_empty() {
        let mut merged: std::collections::BTreeMap<i64, i64> = std::collections::BTreeMap::new();
        let mut total = 0i64;
        let n = overflow.len();
        for (_, t, b) in overflow {
            total += t;
            for (start, count) in b {
                *merged.entry(start).or_insert(0) += count;
            }
        }
        lane_vec.push((
            format!("Other ({} sources)", n),
            total,
            merged.into_iter().collect(),
        ));
    }

    let lanes_json: Vec<serde_json::Value> = lane_vec
        .into_iter()
        .map(|(source, total, b)| {
            let buckets: Vec<serde_json::Value> = b
                .into_iter()
                .map(|(start, count)| serde_json::json!({ "start": start, "count": count }))
                .collect();
            serde_json::json!({ "source": source, "total": total, "buckets": buckets })
        })
        .collect();

    Ok(Json(serde_json::json!({
        "min_ts": min_ts,
        "max_ts": max_ts,
        "bucket_seconds": bucket_seconds,
        "focus": focus_json,
        "lanes": lanes_json,
        "truncated_lanes": truncated_lanes,
    })))
}

/// Ceiling on one PDF timeline export. The PDF generator lays every row out in
/// memory, so this is a real memory bound, not a display preference.
const TIMELINE_PDF_EXPORT_LIMIT: usize = 50_000;

/// Compose the timeline PDF's filter line, truncation disclosure FIRST.
///
/// `TimelineReportGenerator::generate_timeline_report` draws this line with a
/// single `printpdf` `use_text` call, and `use_text` does not wrap: whatever
/// runs past the right edge of the sheet is drawn off the page and cannot be
/// read. A4 (210mm) less a 50mm margin leaves 160mm, and 12pt Helvetica
/// averages a little over 2mm per character, so roughly 76 characters survive —
/// including the generator's own "Filter: " prefix.
///
/// Order is therefore the fix, not decoration. Appended last, behind the date
/// range, module list and search text, the truncation sentence began well past
/// that width on any filtered export: it was drawn off the page and the exhibit
/// read as the complete filtered timeline — the same "looks complete, isn't"
/// defect one layer out from the one B8-016 was filed for. Leading, its first
/// clause lands on the sheet.
///
/// The long explanation follows at the end of the line, where clipping costs
/// only detail, never the fact of truncation. `PDF_FILTER_LINE_BUDGET` in the
/// tests below holds that arithmetic and is checked against the literal.
fn timeline_pdf_filter_description(
    mut filter_parts: Vec<String>,
    truncated_at: Option<usize>,
) -> Option<String> {
    if let Some(limit) = truncated_at {
        filter_parts.insert(
            0,
            format!("EXPORT TRUNCATED: {limit} newest events only, older ones missing"),
        );
        filter_parts.push(format!(
            "This PDF holds at most the {limit} most recent matching events; older matching \
             events are NOT in it. Narrow the date range, or use the CSV or JSON timeline \
             export, which stream the whole result set"
        ));
    }
    if filter_parts.is_empty() {
        None
    } else {
        Some(filter_parts.join("; "))
    }
}

/// Ceiling on one `/timeline/recent/:period` page.
const RECENT_TIMELINE_LIMIT: u32 = 5_000;

/// Windows `/timeline/recent/:period` accepts, in hours.
///
/// Returning `None` for anything else matters: the previous mapping fell back
/// to 24 hours for an unrecognized period, so a request for `90d` was answered
/// with one day of events and nothing in the response said so — a complete-
/// looking answer to a question that was never asked.
fn recent_period_hours(period: &str) -> Option<i64> {
    match period {
        "24h" => Some(24),
        "7d" => Some(24 * 7),
        "30d" => Some(24 * 30),
        _ => None,
    }
}

pub async fn get_recent_timeline(
    Path((case_id, period)): Path<(Uuid, String)>,
    State(state): State<AppState>,
) -> Result<Json<serde_json::Value>, ApiError> {
    info!(
        "Received request to get recent timeline for case {} (period: {})",
        case_id, period
    );

    let hours = recent_period_hours(&period).ok_or_else(|| {
        ApiError::InvalidRequest(format!(
            "Unsupported period '{}'. Use 24h, 7d or 30d, or the paginated \
             /timeline endpoint with an explicit date range.",
            period
        ))
    })?;

    let now = chrono::Utc::now().timestamp();
    let from_ts = now - hours * 3600;

    // Bounded page. The window query had no LIMIT and the response was a bare
    // array with no truncation field, so a case holding a month of MFT + USN +
    // EVTX activity answered this route with 10^5-10^6 rows (B8-025). Ask the
    // filtered query for the page instead, and disclose when the page is a
    // prefix of the window rather than the whole of it.
    let events = state
        .db
        .get_timeline_events_filtered(
            case_id,
            Some(from_ts),
            Some(now),
            None,
            None,
            None,
            None,
            Some(RECENT_TIMELINE_LIMIT as usize),
            None,
            None,
            None,
            None,
            None,
        )
        .await
        .map_err(|e| {
            error!("Failed to fetch recent timeline: {}", e);
            ApiError::InternalServerError(format!("Failed to fetch timeline events: {}", e))
        })?;

    let listing = CappedListing::judge(RECENT_TIMELINE_LIMIT, RECENT_TIMELINE_LIMIT, events.len());
    let mut fields = serde_json::Map::new();
    fields.insert("events".to_string(), serde_json::json!(events));
    fields.insert("period".to_string(), serde_json::json!(period));
    fields.insert("from_ts".to_string(), serde_json::json!(from_ts));
    fields.insert("to_ts".to_string(), serde_json::json!(now));
    Ok(listing.into_body(fields))
}

pub async fn get_timeline_source_modules(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
) -> Result<Json<std::collections::HashMap<String, i64>>, ApiError> {
    info!(
        "Received request to get timeline source module counts for case {}",
        case_id
    );

    let counts = state
        .db
        .get_timeline_source_module_counts(case_id)
        .await
        .map_err(|e| {
            error!("Failed to fetch source module counts: {}", e);
            ApiError::InternalServerError(format!("Failed to fetch source module counts: {}", e))
        })?;

    Ok(Json(counts))
}

pub async fn get_related_timeline_events(
    Path((case_id, artifact_id)): Path<(Uuid, Uuid)>,
    State(state): State<AppState>,
) -> Result<Json<serde_json::Value>, ApiError> {
    info!(
        "Received request to get related timeline events for artifact {} in case {}",
        artifact_id, case_id
    );

    let page = state
        .db
        .get_related_timeline_events(case_id, artifact_id)
        .await
        .map_err(|e| {
            error!("Failed to fetch related timeline events: {}", e);
            ApiError::InternalServerError(format!("Failed to fetch related timeline events: {}", e))
        })?;

    info!(
        "Found {} related timeline events (truncated: {})",
        page.events.len(),
        page.truncated
    );
    // The cap has to travel with the rows. A bare array here would let a
    // listing that stopped at `cap` read as this artifact's whole history,
    // which is the reading an examiner draws when nothing says otherwise.
    Ok(Json(serde_json::json!({
        "events": page.events,
        "truncated": page.truncated,
        "cap": page.cap,
    })))
}

/// Column header of the timeline CSV export.
///
/// The first column keeps its bare name — it is the raw epoch value the
/// evidence carries, and the preamble says exactly what it is. The columns
/// beside it render the same instant as ISO-8601 UTC, carry the sub-second
/// part, and carry the source's own UTC offset where one was recorded
/// (migration 0021), so nothing the store knows about the moment is left out
/// of the file (SHIP-036).
const TIMELINE_EXPORT_CSV_HEADER: &str =
    "Timestamp,Timestamp (ISO-8601 UTC),Subsecond Nanoseconds,\
Source UTC Offset Seconds,Event Type,Source Module,Description,Details,Artifact ID,Case ID\n";

/// The timezone and epoch convention every timeline export states in its own
/// preamble, in the CSV and the JSON alike.
fn timeline_export_timezone_note() -> &'static str {
    "Timestamp is Unix epoch seconds (UTC; no offset has been applied to it). \
     Timestamp (ISO-8601 UTC) is the same instant rendered as RFC 3339 in UTC. \
     Subsecond Nanoseconds is the sub-second part of that instant, 0 for sources that \
     record whole seconds. Source UTC Offset Seconds is the offset east of UTC of the \
     timezone the source itself recorded the time in, where the source recorded one; it \
     is empty (absent in JSON) where the source supplied a bare Unix timestamp with no \
     recoverable offset. No timestamp in this file has been shifted to the timezone of \
     the examined system or of the machine that produced the file."
}

/// How a reader tells a whole timeline export from a fragment of one — the
/// same rule the search export states, for the same reason: a streamed file can
/// stop at any byte, and a warning that lives only at the bottom cannot warn
/// about a download that never reached the bottom.
fn timeline_export_reading_note(format: TimelineExportFormat) -> String {
    let csv = format == TimelineExportFormat::Csv;
    format!(
        "{} If it does not, this file was cut short in transit: it is a fragment, rows are \
         missing from it, and it must not be tendered as the timeline of this case or filter.{}",
        export_terminal_test(csv, "every matching event"),
        if csv { CSV_PREAMBLE_NOTE } else { "" }
    )
}

/// What was asked for, stated before the first row of a timeline export.
struct TimelineExportHeading {
    case_id: Uuid,
    /// The filters in force, named. A filter not in force is omitted rather
    /// than printed empty.
    filters: Vec<(&'static str, String)>,
    /// Events matching the case and filter, counted just before the walk
    /// began. The verdict row states how many rows were actually written.
    matching_events: i64,
    exported_at: String,
}

/// The filters a timeline export ran under, named for its preamble.
fn timeline_export_filter_lines(filters: &TimelineFilterParams) -> Vec<(&'static str, String)> {
    let iso = |ts: i64| {
        chrono::DateTime::from_timestamp(ts, 0)
            .map(|dt| dt.to_rfc3339())
            .unwrap_or_else(|| ts.to_string())
    };
    let mut out = Vec::new();
    if let Some(from) = filters.from_ts {
        out.push(("from", format!("{} ({})", from, iso(from))));
    }
    if let Some(to) = filters.to_ts {
        out.push(("to", format!("{} ({})", to, iso(to))));
    }
    if let Some(modules) = &filters.source_modules {
        out.push(("modules", modules.join(", ")));
    }
    if let Some(search) = &filters.search_text {
        out.push(("search", search.clone()));
    }
    if let Some(filename) = &filters.filename_filter {
        out.push(("filename", filename.clone()));
    }
    if let Some(event_type) = &filters.event_type_filter {
        out.push(("event_type", event_type.clone()));
    }
    if filters.tagged_event_ids.is_some() {
        out.push(("tagged_only", "true".to_string()));
    }
    out
}

/// Why a timeline export stopped writing rows.
enum TimelineExportStop {
    /// The store's stream ended: every row the query matched has been written.
    Exhausted,
    /// The store failed mid-stream. Everything after the last row is absent.
    Failed(String),
}

impl TimelineExportStop {
    fn code(&self) -> &'static str {
        match self {
            Self::Exhausted => "exhausted",
            Self::Failed(_) => "failed",
        }
    }
}

/// The verdict row every timeline export ends with.
///
/// `rows` is what was written; `heading.matching_events` is what was counted
/// before the first row. On a complete walk the two normally agree, and when
/// they do not the file says so rather than leaving a reader to reconcile two
/// numbers: events written to the case between the count and the walk are the
/// ordinary cause, and it is named.
fn timeline_export_verdict(
    rows: usize,
    heading: &TimelineExportHeading,
    stop: &TimelineExportStop,
) -> String {
    match stop {
        TimelineExportStop::Exhausted => {
            let counted = heading.matching_events;
            if counted == rows as i64 {
                format!(
                    "{SEARCH_EXPORT_TERMINAL} VERDICT: COMPLETE. This file holds all {rows} of \
                     {counted} events matching the case and filters stated above — the whole \
                     matching set. The walk reached the end of the store's result set."
                )
            } else {
                format!(
                    "{SEARCH_EXPORT_TERMINAL} VERDICT: COMPLETE, COUNT MOVED. This file holds \
                     {rows} events; the count taken just before the first row was {counted}. The \
                     walk reached the end of the store's result set, so every event that matched \
                     when it was read is in this file; the difference is events added to or \
                     removed from the case between the count and the walk. Re-run the export for \
                     a file whose count and rows agree."
                )
            }
        }
        TimelineExportStop::Failed(detail) => format!(
            "{SEARCH_EXPORT_TERMINAL} VERDICT: INCOMPLETE. This file holds {rows} of {} matching \
             events. The export failed after row {rows}, and everything after that row is \
             absent: {detail}. Do not treat this file as the complete timeline.",
            heading.matching_events
        ),
    }
}

/// Which of the two streamed timeline formats a drain is writing. One drain
/// loop serves both, so the two exports of one timeline cannot describe the
/// same evidence differently.
#[derive(Clone, Copy, PartialEq, Eq)]
enum TimelineExportFormat {
    Csv,
    Json,
}

impl TimelineExportFormat {
    fn content_type(self) -> &'static str {
        match self {
            Self::Csv => "text/csv; charset=utf-8",
            Self::Json => "application/json",
        }
    }

    fn extension(self) -> &'static str {
        match self {
            Self::Csv => "csv",
            Self::Json => "json",
        }
    }

    /// Everything written before the first event row.
    fn preamble(self, heading: &TimelineExportHeading) -> String {
        match self {
            Self::Csv => {
                // `# name,value` lines ahead of the column header — the shape
                // the search export and the case-files MANIFEST.csv use, padded
                // to the table's width (see `csv_preamble_line`).
                let columns = TIMELINE_EXPORT_CSV_HEADER.trim_end().split(',').count();
                let line = |name: &str, value: &str| csv_preamble_line(name, value, columns);
                let mut out = String::new();
                out.push_str(&line("export", "timeline"));
                out.push_str(&line("case_id", &heading.case_id.to_string()));
                for (name, value) in &heading.filters {
                    out.push_str(&line(&format!("filter.{name}"), value));
                }
                out.push_str(&line(
                    "matching_events",
                    &heading.matching_events.to_string(),
                ));
                out.push_str(&line("order", "newest first (timestamp descending)"));
                out.push_str(&line(
                    "row_limit",
                    "none — this export streams the entire matching set, rather than \
                     taking one capped page of it",
                ));
                out.push_str(&line("timezone", timeline_export_timezone_note()));
                out.push_str(&line("exported_at", &heading.exported_at));
                out.push_str(&line("how_to_read", &timeline_export_reading_note(self)));
                out.push_str(TIMELINE_EXPORT_CSV_HEADER);
                out
            }
            Self::Json => {
                let filters: serde_json::Map<String, serde_json::Value> = heading
                    .filters
                    .iter()
                    .map(|(k, v)| ((*k).to_string(), serde_json::Value::String(v.clone())))
                    .collect();
                let head = serde_json::json!({
                    "export": "timeline",
                    "case_id": heading.case_id,
                    "filters": serde_json::Value::Object(filters),
                    "order": "newest first (timestamp descending)",
                    "timezone": timeline_export_timezone_note(),
                    "exported_at": heading.exported_at,
                    "population": {
                        "matching_events": heading.matching_events,
                        "row_limit": serde_json::Value::Null,
                    },
                    "how_to_read": timeline_export_reading_note(self),
                });
                // Opened up so that `events` and then `completeness` can be
                // its last members: a truncated JSON export must fail to
                // parse rather than parse as a smaller complete one.
                let mut out = serde_json::to_string(&head)
                    .unwrap_or_else(|_| String::from("{\"export\":\"timeline\""));
                out.pop();
                out.push_str(",\"events\":[");
                out
            }
        }
    }

    /// One event row. `first` decides the JSON separator; the CSV needs none.
    fn row(
        self,
        event: &seance_core::models::TimelineEventResponse,
        first: bool,
    ) -> Result<String, String> {
        match self {
            Self::Csv => {
                let timestamp_iso = chrono::DateTime::from_timestamp(event.timestamp, 0)
                    .map(|dt| dt.to_rfc3339())
                    .unwrap_or_else(|| event.timestamp.to_string());
                let offset = event
                    .source_utc_offset_seconds
                    .map(|o| o.to_string())
                    .unwrap_or_default();
                // csv_escape gives RFC-4180 quoting + formula-injection guarding.
                Ok(format!(
                    "{},{},{},{},{},{},{},{},{},{}\n",
                    event.timestamp,
                    csv_escape(&timestamp_iso),
                    event.timestamp_subsec_nanos,
                    offset,
                    csv_escape(&event.timestamp_desc),
                    csv_escape(&event.source_module),
                    csv_escape(&event.short_desc),
                    csv_escape(&event.full_details),
                    event.artifact_id,
                    event.case_id
                ))
            }
            Self::Json => {
                // The serialized event already carries `timestamp_subsec_nanos`
                // and, when the source recorded one, `source_utc_offset_seconds`.
                // The ISO-8601 rendering is added beside the raw value so the
                // JSON states the instant the same two ways the CSV does.
                let mut value = serde_json::to_value(event).map_err(|e| e.to_string())?;
                if let serde_json::Value::Object(map) = &mut value {
                    let iso = chrono::DateTime::from_timestamp(event.timestamp, 0)
                        .map(|dt| dt.to_rfc3339());
                    map.insert(
                        "timestamp_iso8601_utc".to_string(),
                        iso.map(serde_json::Value::String)
                            .unwrap_or(serde_json::Value::Null),
                    );
                }
                let mut out = String::new();
                if !first {
                    out.push(',');
                }
                out.push_str(&serde_json::to_string(&value).map_err(|e| e.to_string())?);
                Ok(out)
            }
        }
    }

    /// The verdict, and whatever closes the document around it.
    fn terminal(self, verdict: &str, rows: usize, stop: &TimelineExportStop) -> String {
        match self {
            Self::Csv => csv_verdict_row(
                verdict,
                TIMELINE_EXPORT_CSV_HEADER.trim_end().split(',').count(),
            ),
            Self::Json => {
                let tail = serde_json::json!({
                    "complete": matches!(stop, TimelineExportStop::Exhausted),
                    "rows": rows,
                    "walk_reached_end": matches!(stop, TimelineExportStop::Exhausted),
                    "stopped_because": stop.code(),
                    "statement": verdict,
                });
                format!(
                    "],\"completeness\":{}}}",
                    serde_json::to_string(&tail).unwrap_or_else(|_| "null".to_string())
                )
            }
        }
    }
}

/// The one drain both streamed timeline exports share.
///
/// Streams events straight to the response body, one at a time, so a case
/// with hundreds of MB of timeline never materializes in RAM. The population
/// is stated before the first row and the completeness after the last, because
/// that is when each is known; a mid-stream store error writes an INCOMPLETE
/// verdict row and then aborts the transfer, so the file names its own
/// shortfall whichever of the two signals reaches the client.
async fn stream_timeline_export(
    state: AppState,
    case_id: Uuid,
    user: &AuthenticatedUser,
    params: &std::collections::HashMap<String, String>,
    fmt: TimelineExportFormat,
) -> Result<axum::http::Response<Body>, ApiError> {
    // Parse the SAME filter set the list endpoint uses -- including
    // filter_filename / filter_event_type / tagged_only. Applying only a subset
    // made the export a different (larger) set than the examiner had on screen
    // (BUG-231).
    let filters = parse_timeline_filters(&state, case_id, params).await?;

    // The population, counted with the same filters, before the first row.
    let matching_events = state
        .db
        .get_timeline_events_count(
            case_id,
            filters.from_ts,
            filters.to_ts,
            filters.source_modules.as_deref(),
            filters.search_text.as_deref(),
            filters.filename_filter.as_deref(),
            filters.event_type_filter.as_deref(),
            filters.tagged_event_ids.as_deref(),
        )
        .await
        .map_err(|e| {
            error!("Failed to count timeline events for export: {}", e);
            ApiError::InternalServerError(format!("Failed to count timeline events: {}", e))
        })?;

    audit_required(
        &state,
        Some(case_id),
        &user.0,
        "timeline_exported",
        Some("case"),
        Some(case_id),
        Some(&format!(
            "format: {} (streamed), matching_events: {}",
            fmt.extension(),
            matching_events
        )),
    )
    .await?;

    let heading = TimelineExportHeading {
        case_id,
        filters: timeline_export_filter_lines(&filters),
        matching_events,
        exported_at: chrono::Utc::now().to_rfc3339(),
    };

    let mut rx = state.db.stream_export_timeline(
        case_id,
        filters.from_ts,
        filters.to_ts,
        filters.source_modules,
        filters.search_text,
        filters.filename_filter,
        filters.event_type_filter,
        filters.tagged_event_ids,
    );

    let body_stream = async_stream::stream! {
        yield Ok::<axum::body::Bytes, std::io::Error>(axum::body::Bytes::from(
            fmt.preamble(&heading),
        ));
        let mut written = 0usize;
        let stop = loop {
            match rx.recv().await {
                None => break TimelineExportStop::Exhausted,
                Some(Ok(event)) => match fmt.row(&event, written == 0) {
                    Ok(row) => {
                        written += 1;
                        yield Ok(axum::body::Bytes::from(row));
                    }
                    Err(e) => {
                        break TimelineExportStop::Failed(format!(
                            "a timeline event could not be serialized: {e}"
                        ))
                    }
                },
                Some(Err(e)) => {
                    error!("timeline {} export stream error: {}", fmt.extension(), e);
                    break TimelineExportStop::Failed(e.to_string());
                }
            }
        };
        let verdict = timeline_export_verdict(written, &heading, &stop);
        if let TimelineExportStop::Failed(_) = stop {
            warn!(
                "Timeline export for case {} ended incomplete after {} row(s): {}",
                case_id, written, verdict
            );
        }
        yield Ok(axum::body::Bytes::from(fmt.terminal(&verdict, written, &stop)));
        if let TimelineExportStop::Failed(detail) = stop {
            // The row above names the shortfall for whoever reads the file;
            // the error aborts the transfer for whoever is waiting on the
            // status. Both, rather than a truncated-but-valid-looking file.
            yield Err(std::io::Error::other(detail));
        }
    };

    Response::builder()
        .status(StatusCode::OK)
        .header("Content-Type", fmt.content_type())
        .header(
            "Content-Disposition",
            format!(
                "attachment; filename=\"timeline_export_{}.{}\"",
                case_id,
                fmt.extension()
            ),
        )
        .header("X-Export-Total", matching_events.to_string())
        .header("X-Export-Completeness", "stated-in-final-row")
        .body(Body::from_stream(body_stream))
        .map_err(|e| {
            error!("Failed to build response: {}", e);
            ApiError::InternalServerError(format!("Failed to build response: {}", e))
        })
}

pub async fn export_timeline_json(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
    Extension(user): Extension<AuthenticatedUser>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
) -> Result<axum::http::Response<Body>, ApiError> {
    info!(
        "Received request to export timeline as JSON for case {} with params: {:?}",
        case_id, params
    );
    stream_timeline_export(state, case_id, &user, &params, TimelineExportFormat::Json).await
}

pub async fn export_timeline_csv(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
    Extension(user): Extension<AuthenticatedUser>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
) -> Result<axum::http::Response<Body>, ApiError> {
    info!(
        "Received request to export timeline as CSV for case {} with params: {:?}",
        case_id, params
    );
    stream_timeline_export(state, case_id, &user, &params, TimelineExportFormat::Csv).await
}

/// `GET /cases/{id}/timeline/export/body_events` — the timeline's events (memory
/// events included) as a Sleuth Kit body file: `timeliner --create-bodyfile`
/// parity, which the file-list body file above cannot give because a memory
/// event is not a file.
///
/// One row per event, its single time in the column its kind names
/// (`seance_reporting::body_file`), and every timeline filter honoured — the
/// opposite of the file export, because here the population IS the events on
/// screen. Streamed, with the population stated before the first row and the
/// verdict after the last.
pub async fn export_timeline_body_events(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
    Extension(user): Extension<AuthenticatedUser>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
) -> Result<axum::http::Response<Body>, ApiError> {
    info!(
        "Received request to export case {} timeline events as a mactime body file: {:?}",
        case_id, params
    );
    let filters = parse_timeline_filters(&state, case_id, &params).await?;
    let matching = state
        .db
        .get_timeline_events_count(
            case_id,
            filters.from_ts,
            filters.to_ts,
            filters.source_modules.as_deref(),
            filters.search_text.as_deref(),
            filters.filename_filter.as_deref(),
            filters.event_type_filter.as_deref(),
            filters.tagged_event_ids.as_deref(),
        )
        .await
        .map_err(|e| {
            error!("Failed to count timeline events for body export: {}", e);
            ApiError::InternalServerError(format!("Failed to count timeline events: {}", e))
        })?;

    audit_required(
        &state,
        Some(case_id),
        &user.0,
        "timeline_exported",
        Some("case"),
        Some(case_id),
        Some(&format!(
            "format: body_events (streamed), events: {matching}"
        )),
    )
    .await?;

    let preamble = seance_reporting::render_event_body_file_preamble(
        &case_id.to_string(),
        matching as i64,
        &chrono::Utc::now().to_rfc3339(),
        "Every time is Unix epoch seconds in UTC, as the source recorded it; none has been \
         shifted to the timezone of the examined system or of the machine that produced \
         this file.",
    );
    let mut rx = state.db.stream_export_timeline(
        case_id,
        filters.from_ts,
        filters.to_ts,
        filters.source_modules,
        filters.search_text,
        filters.filename_filter,
        filters.event_type_filter,
        filters.tagged_event_ids,
    );

    let body_stream = async_stream::stream! {
        yield Ok::<axum::body::Bytes, std::io::Error>(axum::body::Bytes::from(preamble));
        let mut written = 0usize;
        let failure = loop {
            match rx.recv().await {
                None => break None,
                Some(Ok(event)) => {
                    let entry = seance_reporting::BodyFileEntry::from_timeline_event(
                        event.timestamp,
                        &event.source_module,
                        &event.short_desc,
                        &event.timestamp_desc,
                    );
                    written += 1;
                    yield Ok(axum::body::Bytes::from(
                        seance_reporting::render_body_file(std::slice::from_ref(&entry)),
                    ));
                }
                Some(Err(e)) => {
                    error!("body-events export stream error: {}", e);
                    break Some(e);
                }
            }
        };
        yield Ok(axum::body::Bytes::from(seance_reporting::render_event_body_file_verdict(
            written,
            matching as i64,
            failure.as_deref(),
        )));
        if let Some(detail) = failure {
            yield Err(std::io::Error::other(detail));
        }
    };

    Response::builder()
        .status(StatusCode::OK)
        .header("Content-Type", "text/plain; charset=utf-8")
        .header(
            "Content-Disposition",
            format!("attachment; filename=\"body_events_{}.txt\"", case_id),
        )
        .header("X-Export-Total", matching.to_string())
        .header("X-Export-Completeness", "stated-in-final-row")
        .body(Body::from_stream(body_stream))
        .map_err(|e| {
            error!("Failed to build response: {}", e);
            ApiError::InternalServerError(format!("Failed to build response: {}", e))
        })
}

/// `GET /cases/{id}/timeline/export/body` — the case's files as a Sleuth Kit
/// body file, the intermediate `mactime`, log2timeline and Timesketch consume.
///
/// This is a FILE export, not an event export: one row per `FileEntry`
/// artifact carrying that file's own MAC times (`seance_reporting::body_file`),
/// which is what a body file is. It therefore takes none of the timeline
/// filters — a body file filtered to the events on screen would be a file list
/// with files missing and nothing on its face to say so — and its preamble
/// states that. Streamed like the CSV and JSON exports, with the population
/// stated before the first row and the verdict after the last; both sit on
/// `#` lines, which `mactime` skips.
pub async fn export_timeline_body_file(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
    Extension(user): Extension<AuthenticatedUser>,
) -> Result<axum::http::Response<Body>, ApiError> {
    info!(
        "Received request to export case {} files as a mactime body file",
        case_id
    );

    let file_entries = state.db.count_file_entries(case_id).await.map_err(|e| {
        error!("Failed to count file entries for body-file export: {}", e);
        ApiError::InternalServerError(format!("Failed to count file entries: {}", e))
    })?;

    audit_required(
        &state,
        Some(case_id),
        &user.0,
        "timeline_exported",
        Some("case"),
        Some(case_id),
        Some(&format!(
            "format: body (streamed), file_entries: {}",
            file_entries
        )),
    )
    .await?;

    let preamble = seance_reporting::render_body_file_preamble(
        &case_id.to_string(),
        file_entries,
        &chrono::Utc::now().to_rfc3339(),
        "Every time is Unix epoch seconds in UTC, as the source recorded it; none has been \
         shifted to the timezone of the examined system or of the machine that produced \
         this file.",
    );
    let mut rx = state.db.stream_file_entries(case_id);

    let body_stream = async_stream::stream! {
        yield Ok::<axum::body::Bytes, std::io::Error>(axum::body::Bytes::from(preamble));
        let mut written = 0usize;
        let failure = loop {
            match rx.recv().await {
                None => break None,
                Some(Ok(artifact)) => {
                    let entry =
                        seance_reporting::BodyFileEntry::from_file_entry_metadata(&artifact.metadata);
                    written += 1;
                    yield Ok(axum::body::Bytes::from(
                        seance_reporting::render_body_file(std::slice::from_ref(&entry)),
                    ));
                }
                Some(Err(e)) => {
                    error!("body-file export stream error: {}", e);
                    break Some(e);
                }
            }
        };
        if let Some(detail) = failure.as_deref() {
            warn!(
                "Body-file export for case {} ended incomplete after {} row(s): {}",
                case_id, written, detail
            );
        }
        yield Ok(axum::body::Bytes::from(seance_reporting::render_body_file_verdict(
            written,
            file_entries,
            failure.as_deref(),
        )));
        if let Some(detail) = failure {
            // The line above names the shortfall for whoever reads the file;
            // the error aborts the transfer for whoever is waiting on the
            // status. Both, rather than a truncated-but-valid-looking file.
            yield Err(std::io::Error::other(detail));
        }
    };

    Response::builder()
        .status(StatusCode::OK)
        .header("Content-Type", "text/plain; charset=utf-8")
        .header(
            "Content-Disposition",
            format!("attachment; filename=\"body_{}.txt\"", case_id),
        )
        .header("X-Export-Total", file_entries.to_string())
        .header("X-Export-Completeness", "stated-in-final-row")
        .body(Body::from_stream(body_stream))
        .map_err(|e| {
            error!("Failed to build response: {}", e);
            ApiError::InternalServerError(format!("Failed to build response: {}", e))
        })
}

/// A `TimelineEventResponse`'s well-known device-position keys, checked in
/// this order. Only a handful of source modules carry a byte/sector/entry
/// offset into the medium the event came from, and different modules spell
/// it differently. `None` when none of these keys is present as a number —
/// never a fabricated 0, because 0 is itself a real offset.
const DEVICE_OFFSET_KEYS: &[&str] = &[
    "device_offset",
    "byte_offset",
    "offset",
    "sector_offset",
    "cluster_offset",
];

/// Read a device-position key out of an event's `full_details`.
///
/// NOT `dynamic_fields`: that map is populated only when a caller passes
/// `dynamic_columns` to `seance_db::get_timeline_events_filtered`, asking for
/// specific JSON paths by name in advance — `stream_export_timeline`, which
/// every timeline export (including this one) actually calls, takes no such
/// parameter, so `dynamic_fields` is `None` on every row that reaches here
/// and a device-offset lookup against it can never succeed. `full_details` is
/// on every `TimelineEventResponse` unconditionally: `seance_db`'s
/// `timeline_full_details` guarantees it is always valid JSON — the event's
/// own `full_details` field if the producing module set one and it parses,
/// else the artifact's whole metadata document, else a plain string wrapped
/// as a JSON string literal. Bytes that fail to parse, or parse to something
/// with no keys (a JSON string, number, array), yield `None` rather than a
/// fabricated offset.
fn device_offset_from_full_details(full_details: &str) -> Option<i64> {
    let doc: serde_json::Value = serde_json::from_str(full_details).ok()?;
    let obj = doc.as_object()?;
    for key in DEVICE_OFFSET_KEYS {
        if let Some(v) = obj.get(*key) {
            if let Some(n) = v.as_i64() {
                return Some(n);
            }
            if let Some(n) = v.as_u64() {
                return i64::try_from(n).ok();
            }
        }
    }
    None
}

/// One timeline event, shaped into the five MemProcFS-Analyzer column names
/// this export publishes, plus a sixth `DEVICE_OFFSET` column MemProcFS's own
/// schema has no room for (MemProcFS is memory-only; this timeline spans disk
/// evidence too).
///
/// The mapping from this project's own event shape to those five names is an
/// editorial choice, stated once here rather than left to be reverse-engineered
/// from the SQL: `TYPE` is the producing module (MemProcFS's "type" column
/// names the artifact category the same way), `ACTION` is this project's
/// `timestamp_desc` (what kind of time this is — "File Modified", "Registry
/// Key Last Write" — which is the verb MemProcFS's own "action" column
/// carries), `SUBJECT` is the short label of what the event is about, and
/// `DESC` is the long-form detail.
struct SqliteTimelineRow {
    date: String,
    r#type: String,
    action: String,
    subject: String,
    desc: String,
    device_offset: Option<i64>,
}

fn timeline_row_for_sqlite(
    event: &seance_core::models::TimelineEventResponse,
) -> SqliteTimelineRow {
    let date = chrono::DateTime::from_timestamp(event.timestamp, 0)
        .map(|dt| dt.to_rfc3339())
        .unwrap_or_else(|| event.timestamp.to_string());
    SqliteTimelineRow {
        date,
        r#type: event.source_module.clone(),
        action: event.timestamp_desc.clone(),
        subject: event.short_desc.clone(),
        desc: event.full_details.clone(),
        device_offset: device_offset_from_full_details(&event.full_details),
    }
}

const TIMELINE_SQLITE_SCHEMA: &str = concat!(
    "CREATE TABLE timeline (",
    "\"DATE\" TEXT NOT NULL, ",
    "\"TYPE\" TEXT NOT NULL, ",
    "\"ACTION\" TEXT NOT NULL, ",
    "\"SUBJECT\" TEXT NOT NULL, ",
    "\"DESC\" TEXT NOT NULL, ",
    "\"DEVICE_OFFSET\" INTEGER",
    ");",
);

const TIMELINE_SQLITE_META_SCHEMA: &str = concat!(
    "CREATE TABLE export_meta (",
    "case_id TEXT NOT NULL, ",
    "exported_at TEXT NOT NULL, ",
    "matching_events INTEGER NOT NULL, ",
    "rows_written INTEGER NOT NULL, ",
    "complete INTEGER NOT NULL, ",
    "stopped_because TEXT, ",
    "statement TEXT NOT NULL",
    ");",
);

/// Create the two tables this export publishes. Split out so a test can build
/// a real on-disk database and read it back without going through the HTTP
/// handler or a live case.
fn create_timeline_sqlite_schema(conn: &rusqlite::Connection) -> rusqlite::Result<()> {
    conn.execute(TIMELINE_SQLITE_SCHEMA, [])?;
    conn.execute(TIMELINE_SQLITE_META_SCHEMA, [])?;
    Ok(())
}

/// Insert one event's row inside the caller's transaction. Never called
/// outside one: `§3.7`'s "single-pass store" requirement is that the whole
/// walk commits once, not once per row.
fn insert_timeline_sqlite_row(
    tx: &rusqlite::Transaction<'_>,
    event: &seance_core::models::TimelineEventResponse,
) -> rusqlite::Result<()> {
    let row = timeline_row_for_sqlite(event);
    tx.execute(
        "INSERT INTO timeline (\"DATE\", \"TYPE\", \"ACTION\", \"SUBJECT\", \"DESC\", \"DEVICE_OFFSET\") \
         VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
        rusqlite::params![row.date, row.r#type, row.action, row.subject, row.desc, row.device_offset],
    )?;
    Ok(())
}

fn insert_timeline_sqlite_meta(
    tx: &rusqlite::Transaction<'_>,
    case_id: Uuid,
    exported_at: &str,
    matching_events: i64,
    rows_written: i64,
    complete: bool,
    stopped_because: &str,
    statement: &str,
) -> rusqlite::Result<()> {
    tx.execute(
        "INSERT INTO export_meta (case_id, exported_at, matching_events, rows_written, \
         complete, stopped_because, statement) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
        rusqlite::params![
            case_id.to_string(),
            exported_at,
            matching_events,
            rows_written,
            complete as i64,
            stopped_because,
            statement,
        ],
    )?;
    Ok(())
}

/// `GET /cases/{id}/timeline/export/sqlite` — the case's filtered timeline as
/// a single SQLite database, in the MemProcFS-Analyzer column set (`DATE`,
/// `TYPE`, `ACTION`, `SUBJECT`, `DESC`) plus `DEVICE_OFFSET`, for interop with
/// Timeline Explorer and MemProcFS-Analyzer.
///
/// Built in one pass over the same filtered event stream the CSV/JSON exports
/// use — one open transaction, one commit — rather than N separate
/// transactions, so a case with a very large timeline is not N times slower to
/// export than it needs to be and a reader never sees a half-committed table.
/// The database is written to a real temporary file (bounded memory while
/// building, however large the case is) and the finished file's bytes are the
/// response body; a stream error partway through still commits every row
/// recovered so far and records the shortfall in `export_meta` rather than
/// losing the rows already read or silently presenting a partial table as
/// complete.
pub async fn export_timeline_sqlite(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
    Extension(user): Extension<AuthenticatedUser>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
) -> Result<axum::http::Response<Body>, ApiError> {
    info!(
        "Received request to export timeline as SQLite for case {} with params: {:?}",
        case_id, params
    );

    let filters = parse_timeline_filters(&state, case_id, &params).await?;

    let matching_events = state
        .db
        .get_timeline_events_count(
            case_id,
            filters.from_ts,
            filters.to_ts,
            filters.source_modules.as_deref(),
            filters.search_text.as_deref(),
            filters.filename_filter.as_deref(),
            filters.event_type_filter.as_deref(),
            filters.tagged_event_ids.as_deref(),
        )
        .await
        .map_err(|e| {
            error!("Failed to count timeline events for SQLite export: {}", e);
            ApiError::InternalServerError(format!("Failed to count timeline events: {}", e))
        })?;

    let mut rx = state.db.stream_export_timeline(
        case_id,
        filters.from_ts,
        filters.to_ts,
        filters.source_modules,
        filters.search_text,
        filters.filename_filter,
        filters.event_type_filter,
        filters.tagged_event_ids,
    );

    let tmp = tempfile::NamedTempFile::new().map_err(|e| {
        error!(
            "Failed to create temp file for SQLite timeline export: {}",
            e
        );
        ApiError::InternalServerError(format!("Failed to create temp file: {}", e))
    })?;
    let tmp_path = tmp.path().to_path_buf();

    // rusqlite::Connection is not Send-friendly to hold across an .await, so
    // the whole build runs inside one blocking task and only its outcome
    // (row count, stop reason) crosses back into the async fn.
    let exported_at = chrono::Utc::now().to_rfc3339();
    let build = tokio::task::spawn_blocking({
        let tmp_path = tmp_path.clone();
        move || -> Result<(usize, bool, String, String), String> {
            let mut conn = rusqlite::Connection::open(&tmp_path).map_err(|e| e.to_string())?;
            create_timeline_sqlite_schema(&conn).map_err(|e| e.to_string())?;
            let tx = conn.transaction().map_err(|e| e.to_string())?;
            let mut written = 0usize;
            let (complete, stopped_because, statement) = loop {
                match rx.blocking_recv() {
                    None => {
                        break (
                            true,
                            "exhausted".to_string(),
                            format!("{written} of {matching_events} matching event(s) exported"),
                        )
                    }
                    Some(Ok(event)) => {
                        if let Err(e) = insert_timeline_sqlite_row(&tx, &event) {
                            break (
                                false,
                                "row_failed".to_string(),
                                format!(
                                    concat!(
                                        "stopped after {} row(s): a timeline event could not ",
                                        "be written: {}"
                                    ),
                                    written, e
                                ),
                            );
                        }
                        written += 1;
                    }
                    Some(Err(e)) => {
                        break (
                            false,
                            "store_error".to_string(),
                            format!("stopped after {written} row(s): {e}"),
                        )
                    }
                }
            };
            insert_timeline_sqlite_meta(
                &tx,
                case_id,
                &exported_at,
                matching_events as i64,
                written as i64,
                complete,
                &stopped_because,
                &statement,
            )
            .map_err(|e| e.to_string())?;
            tx.commit().map_err(|e| e.to_string())?;
            Ok((written, complete, stopped_because, statement))
        }
    })
    .await
    .map_err(|e| {
        error!("SQLite timeline export task panicked: {}", e);
        ApiError::InternalServerError("SQLite export task failed".to_string())
    })?
    .map_err(|e| {
        error!("Failed to build SQLite timeline export: {}", e);
        ApiError::InternalServerError(format!("Failed to build SQLite export: {}", e))
    })?;

    let (written, complete, stopped_because, statement) = build;

    audit_required(
        &state,
        Some(case_id),
        &user.0,
        "timeline_exported",
        Some("case"),
        Some(case_id),
        Some(&format!(
            concat!("format: sqlite, rows: {} of {} matching, complete: {}, stopped: {}"),
            written, matching_events, complete, stopped_because
        )),
    )
    .await?;

    if !complete {
        warn!(
            "Timeline SQLite export for case {} ended incomplete after {} row(s): {}",
            case_id, written, statement
        );
    }

    // Streamed from the finished file, not buffered whole into a `Vec<u8>`:
    // this handler's whole point (per its own doc comment) is that memory use
    // is bounded by the size of one page/chunk, not by the size of the case's
    // timeline, and reading the finished file into RAM before responding
    // undid that in the one phase that is easiest to overlook — a
    // code-review finding on 2026-09-18. `tmp` (the `NamedTempFile`, whose
    // `Drop` deletes the file) is moved INTO the stream generator rather than
    // dropped at the end of this function, so the file is not unlinked until
    // the stream itself is fully consumed or aborted — matching the same
    // temp-file-then-stream shape `export_case_files_zip` already uses
    // (`tokio_util::io::ReaderStream` over a `tokio::fs::File`), except that
    // export unlinks its temp file eagerly on Unix (`tempfile::tempfile()`)
    // because it never needs a real path; this one does, for rusqlite.
    let tokio_file = tokio::fs::File::open(&tmp_path).await.map_err(|e| {
        error!("Failed to open SQLite timeline export for streaming: {}", e);
        ApiError::InternalServerError(format!("Failed to open SQLite export: {}", e))
    })?;
    let body_stream = async_stream::stream! {
        // Kept alive for the lifetime of this generator, not the enclosing
        // function: dropped (deleting the temp file) only once the stream
        // itself is dropped, after the last chunk is yielded or the
        // connection is aborted.
        let _keep_temp_file_alive = tmp;
        let mut reader = tokio_util::io::ReaderStream::new(tokio_file);
        while let Some(chunk) = futures::StreamExt::next(&mut reader).await {
            yield chunk;
        }
    };

    Response::builder()
        .status(StatusCode::OK)
        .header("Content-Type", "application/vnd.sqlite3")
        .header(
            "Content-Disposition",
            format!("attachment; filename=\"timeline_export_{case_id}.sqlite\""),
        )
        .header("X-Export-Total", matching_events.to_string())
        .header("X-Export-Completeness", "stated-in-export-meta-table")
        .body(Body::from_stream(body_stream))
        .map_err(|e| {
            error!("Failed to build response: {}", e);
            ApiError::InternalServerError(format!("Failed to build response: {}", e))
        })
}

pub async fn export_timeline_pdf(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
    Extension(user): Extension<AuthenticatedUser>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
) -> Result<axum::http::Response<Body>, ApiError> {
    info!(
        "Received request to export timeline as PDF for case {} with params: {:?}",
        case_id, params
    );

    // Same full filter set as the list endpoint (BUG-231).
    let filters = parse_timeline_filters(&state, case_id, &params).await?;
    let from_ts = filters.from_ts;
    let to_ts = filters.to_ts;
    let source_modules = filters.source_modules.as_deref();
    let search_text = filters.search_text.as_deref();

    // Bounded fetch. The JSON and CSV timeline exports stream, so they never
    // hold the whole result set; the PDF has to lay every row out in memory, so
    // an unlimited fetch on a real case (MFT + USN + EVTX) stalled or OOM'd the
    // server (B8-016). One past the ceiling tells a full page apart from an
    // exactly-at-the-ceiling one, and when it binds the PDF says so on its face
    // rather than reading as the complete timeline.
    let mut events = state
        .db
        .get_timeline_events_filtered(
            case_id,
            from_ts,
            to_ts,
            source_modules,
            search_text,
            filters.filename_filter.as_deref(),
            filters.event_type_filter.as_deref(),
            Some(TIMELINE_PDF_EXPORT_LIMIT + 1),
            None, // No offset
            None, // sort_by
            None, // sort_order
            None, // dynamic_columns
            filters.tagged_event_ids.as_deref(),
        )
        .await
        .map_err(|e| {
            error!("Failed to fetch timeline events for export: {}", e);
            ApiError::InternalServerError(format!("Failed to fetch timeline events: {}", e))
        })?;

    let pdf_truncated = events.len() > TIMELINE_PDF_EXPORT_LIMIT;
    events.truncate(TIMELINE_PDF_EXPORT_LIMIT);

    // The population the slice above was cut from, counted with the same
    // filters. The PDF prints the two together; it used to print the size of
    // the slice under the label "Total Events" (SHIP-035).
    let matching_total = state
        .db
        .get_timeline_events_count(
            case_id,
            from_ts,
            to_ts,
            source_modules,
            search_text,
            filters.filename_filter.as_deref(),
            filters.event_type_filter.as_deref(),
            filters.tagged_event_ids.as_deref(),
        )
        .await
        .map_err(|e| {
            error!("Failed to count timeline events for PDF export: {}", e);
            ApiError::InternalServerError(format!("Failed to count timeline events: {}", e))
        })?;

    info!(
        "Exporting {} timeline events as PDF (truncated: {})",
        events.len(),
        pdf_truncated
    );

    audit_required(
        &state,
        Some(case_id),
        &user.0,
        "timeline_exported",
        Some("case"),
        Some(case_id),
        Some(&format!(
            "format: pdf, events: {} of {} matching, truncated: {}",
            events.len(),
            matching_total,
            pdf_truncated
        )),
    )
    .await?;

    // Get case info for report
    let case = state.db.get_case(case_id).await.map_err(|e| {
        error!("Failed to fetch case info: {}", e);
        ApiError::InternalServerError(format!("Failed to fetch case: {}", e))
    })?;

    // Build filter description
    let mut filter_parts = vec![];
    if let Some(from) = from_ts {
        filter_parts.push(format!(
            "From: {}",
            chrono::DateTime::from_timestamp(from, 0)
                .map(|dt| dt.to_rfc3339())
                .unwrap_or_default()
        ));
    }
    if let Some(to) = to_ts {
        filter_parts.push(format!(
            "To: {}",
            chrono::DateTime::from_timestamp(to, 0)
                .map(|dt| dt.to_rfc3339())
                .unwrap_or_default()
        ));
    }
    if let Some(modules) = source_modules {
        filter_parts.push(format!("Modules: {}", modules.join(", ")));
    }
    if let Some(search) = search_text {
        filter_parts.push(format!("Search: {}", search));
    }
    if let Some(ref filename) = filters.filename_filter {
        filter_parts.push(format!("Filename: {}", filename));
    }
    if let Some(ref event_type) = filters.event_type_filter {
        filter_parts.push(format!("Event type: {}", event_type));
    }
    if filters.tagged_event_ids.is_some() {
        filter_parts.push("Tagged events only".to_string());
    }
    // The truncation rides in the same line the report prints as its filter
    // description, so the disclosure is on the exhibit and not only in a header
    // an examiner never sees. Events come back newest-first, so what is missing
    // is the older end of the range.
    let filter_description = timeline_pdf_filter_description(
        filter_parts,
        pdf_truncated.then_some(TIMELINE_PDF_EXPORT_LIMIT),
    );

    // Generate temporary PDF file
    let temp_dir = std::env::temp_dir();
    let pdf_filename = format!("timeline_export_{}.pdf", case_id);
    let pdf_path = temp_dir.join(&pdf_filename);

    let pdf_path_str = pdf_path
        .to_str()
        .ok_or_else(|| ApiError::InternalServerError("Invalid PDF path encoding".to_string()))?;

    let generator = TimelineReportGenerator::new();
    generator
        .generate_timeline_report(
            &state.db,
            case_id,
            &case.name,
            events,
            matching_total,
            pdf_truncated,
            pdf_path_str,
            filter_description,
        )
        .await
        .map_err(|e| {
            error!("Failed to generate PDF report: {}", e);
            ApiError::InternalServerError(format!("Failed to generate PDF: {}", e))
        })?;

    // Read PDF file
    let pdf_data = tokio::fs::read(&pdf_path).await.map_err(|e| {
        error!("Failed to read generated PDF: {}", e);
        ApiError::InternalServerError(format!("Failed to read PDF: {}", e))
    })?;

    // Clean up temp file
    let _ = tokio::fs::remove_file(&pdf_path).await;

    // Optionally sign the PDF
    let pdf_data = if let Some(ref signing_config) = state.signing_config {
        sign_pdf(&pdf_data, signing_config).map_err(|e| {
            error!("Failed to sign PDF: {}", e);
            ApiError::InternalServerError(format!("Failed to sign PDF: {}", e))
        })?
    } else {
        pdf_data
    };

    // Return as downloadable file
    let response = axum::http::Response::builder()
        .status(StatusCode::OK)
        .header("Content-Type", "application/pdf")
        .header(
            "Content-Disposition",
            format!("attachment; filename=\"{}\"", pdf_filename),
        )
        .body(Body::from(pdf_data))
        .map_err(|e| {
            error!("Failed to build response: {}", e);
            ApiError::InternalServerError(format!("Failed to build response: {}", e))
        })?;

    Ok(response)
}

pub async fn export_case_pdf(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
    Extension(user): Extension<AuthenticatedUser>,
    axum::extract::Query(_params): axum::extract::Query<std::collections::HashMap<String, String>>,
) -> Result<axum::http::Response<Body>, ApiError> {
    info!(
        "Received request to export case summary as PDF for case {}",
        case_id
    );

    audit_required(
        &state,
        Some(case_id),
        &user.0,
        "case_report_exported",
        Some("case"),
        Some(case_id),
        Some("format: pdf"),
    )
    .await?;

    let pdf_filename = format!("case_summary_{}.pdf", case_id);

    let data = gather_report_data(&state, case_id).await?;
    let extras = gather_report_extras(&state, case_id).await?;
    let pdf_data = seance_reporting::render_pdf_with(&data, &extras).map_err(|e| {
        error!("Failed to generate PDF report: {}", e);
        ApiError::InternalServerError(format!("Failed to generate PDF: {}", e))
    })?;

    // Optionally sign the PDF
    let pdf_data = if let Some(ref signing_config) = state.signing_config {
        sign_pdf(&pdf_data, signing_config).map_err(|e| {
            error!("Failed to sign PDF: {}", e);
            ApiError::InternalServerError(format!("Failed to sign PDF: {}", e))
        })?
    } else {
        pdf_data
    };

    // Return as downloadable file
    let response = axum::http::Response::builder()
        .status(StatusCode::OK)
        .header("Content-Type", "application/pdf")
        .header(
            "Content-Disposition",
            format!("attachment; filename=\"{}\"", pdf_filename),
        )
        .body(Body::from(pdf_data))
        .map_err(|e| {
            error!("Failed to build response: {}", e);
            ApiError::InternalServerError(format!("Failed to build response: {}", e))
        })?;

    Ok(response)
}

/// Export the case report as a Rich Text Format document.
///
/// Same input, same section set, as [`export_case_html_report`] and
/// [`export_case_pdf`] -- [`seance_reporting::render_rtf`] is the RTF sibling
/// of `render_html`/`render_pdf` and covers the identical `ReportData`
/// contract (ROADMAP.md §2.10).
pub async fn export_case_rtf(
    Path(case_id): Path<Uuid>,
    State(state): State<AppState>,
    Extension(user): Extension<AuthenticatedUser>,
) -> Result<Response<Body>, ApiError> {
    info!("Generating RTF report for case {}", case_id);

    audit_required(
        &state,
        Some(case_id),
        &user.0,
        "case_report_exported",
        Some("case"),
        Some(case_id),
        Some("format: rtf"),
    )
    .await?;

    let data = gather_report_data(&state, case_id).await?;
    let extras = gather_report_extras(&state, case_id).await?;
    let rtf = seance_reporting::render_rtf_with(&data, &extras);

    let response = Response::builder()
        .status(StatusCode::OK)
        .header("Content-Type", "application/rtf")
        .header(
            "Content-Disposition",
            format!(
                "attachment; filename=\"report_{}.rtf\"",
                sanitize_filename_component(&data.case_name)
            ),
        )
        .body(Body::from(rtf))
        .map_err(|e| ApiError::InternalServerError(format!("Failed to build response: {}", e)))?;

    Ok(response)
}

