    /// BUG-234: only "known" / "notable" may be stored as a hash-set type, and
    /// case/whitespace variants normalize instead of slipping through as a new
    /// label that classification would treat as neither.
    #[test]
    fn hash_set_type_is_validated_and_normalized() {
        assert_eq!(normalize_hash_set_type("known").unwrap(), "known");
        assert_eq!(normalize_hash_set_type("notable").unwrap(), "notable");
        assert_eq!(normalize_hash_set_type("  Notable ").unwrap(), "notable");
        assert_eq!(normalize_hash_set_type("KNOWN").unwrap(), "known");

        for bad in ["", "bad", "known-bad", "notible", "nsrl"] {
            let err = normalize_hash_set_type(bad).expect_err("must reject");
            assert!(matches!(err, ApiError::InvalidRequest(_)), "{bad}");
        }
    }

    /// An HEVC .MOV keyframe decodes to an image via the HEIF-wrapping path.
    /// Gated on a real sample: set SEANCE_HEVC_MOV to a QuickTime/HEVC clip
    /// (the CI has none, so it no-ops there). Proves the synthesized HEIF is
    /// accepted by libheif/libde265 and yields non-empty pixels.
    #[cfg(all(feature = "video-thumbs", feature = "heic"))]
    #[test]
    fn hevc_mov_keyframe_decodes_via_heif() {
        let path = match std::env::var("SEANCE_HEVC_MOV") {
            Ok(p) => p,
            Err(_) => return,
        };
        let bytes = std::fs::read(&path).expect("read HEVC sample");
        let img = decode_hevc_frame(&bytes).expect("HEVC keyframe should decode");
        assert!(img.width() >= 16 && img.height() >= 16);
    }

    #[test]
    fn test_parse_byte_pattern() {
        assert_eq!(
            parse_byte_pattern("ff d8 ff").unwrap(),
            vec![0xFF, 0xD8, 0xFF]
        );
        assert_eq!(
            parse_byte_pattern("DE:AD,BE").unwrap(),
            vec![0xDE, 0xAD, 0xBE]
        );
        assert!(parse_byte_pattern("").is_err());
        assert!(parse_byte_pattern("abc").is_err()); // odd length
        assert!(parse_byte_pattern("zz").is_err()); // non-hex
    }

    #[test]
    fn parse_byte_pattern_is_size_capped() {
        // Hits are capped but the pattern was not: one request could allocate a
        // multi-MB pattern plus a near-pattern-sized carry window (BUG-281).
        let at_limit = "ab".repeat(MAX_BYTE_PATTERN_BYTES);
        assert_eq!(
            parse_byte_pattern(&at_limit).unwrap().len(),
            MAX_BYTE_PATTERN_BYTES
        );

        let over_limit = "ab".repeat(MAX_BYTE_PATTERN_BYTES + 1);
        assert!(parse_byte_pattern(&over_limit).is_err());

        // Separators must not let an oversize pattern in through the back door.
        let padded = "ab ".repeat(MAX_BYTE_PATTERN_BYTES + 1);
        assert!(parse_byte_pattern(&padded).is_err());
    }

    #[test]
    fn test_byte_search_scan_finds_offsets_incl_chunk_boundary() {
        use seance_core::data_source::{ByteSliceDataSource, DataSource};
        // Pattern "AB CD" at offsets 1, 7 (spanning a chunk edge with chunk=4), 12.
        let data = vec![
            0x00, 0xAB, 0xCD, 0x00, 0x00, 0x00, 0x00, 0xAB, 0xCD, 0x00, 0x00, 0x00, 0xAB, 0xCD,
        ];
        let src = ByteSliceDataSource::new(data.clone());
        let total = src.size();
        let pattern = vec![0xAB, 0xCD];
        // chunk=4 forces the offset-7 match to straddle a chunk boundary.
        let (offsets, truncated, scanned) =
            byte_search_scan(&src as &dyn DataSource, total, &pattern, 100, 4).unwrap();
        assert_eq!(offsets, vec![1, 7, 12]);
        assert!(!truncated);
        assert_eq!(scanned, total, "a complete scan reads every declared byte");

        // Cap honoured.
        let (capped, truncated, _) =
            byte_search_scan(&src as &dyn DataSource, total, &pattern, 2, 4).unwrap();
        assert_eq!(capped, vec![1, 7]);
        assert!(truncated);

        // No matches.
        let (none, _, _) =
            byte_search_scan(&src as &dyn DataSource, total, &[0xFF, 0xFF], 100, 4).unwrap();
        assert!(none.is_empty());
    }

    #[test]
    fn byte_search_reports_how_far_it_actually_got() {
        use seance_core::data_source::{ByteSliceDataSource, DataSource};
        // The artifact claims 64 bytes but only 8 are readable: a search that
        // finds nothing has NOT shown the pattern is absent from the file.
        let src = ByteSliceDataSource::new(vec![0x00; 8]);
        let declared = 64u64;
        let (offsets, truncated, scanned) =
            byte_search_scan(&src as &dyn DataSource, declared, &[0xAB, 0xCD], 100, 4).unwrap();
        assert!(offsets.is_empty());
        assert!(!truncated, "the hit cap was not reached");
        assert_eq!(scanned, 8, "only the readable prefix was searched");
        assert!(
            scanned < declared,
            "the caller must be able to see the shortfall and flag the scan incomplete"
        );
    }

    #[test]
    fn test_parse_relative_date_today() {
        let result = parse_relative_date("today");
        assert!(result.is_ok());

        let timestamp = result.unwrap();
        let today = Utc::now()
            .with_hour(0)
            .unwrap()
            .with_minute(0)
            .unwrap()
            .with_second(0)
            .unwrap()
            .with_nanosecond(0)
            .unwrap();

        assert_eq!(timestamp, today.timestamp());
    }

