    // --- evaluate_integrity (C2) ---

    const MD5: &str = "5d41402abc4b2a76b9719d911017c592";
    const SHA1: &str = "aaf4c61ddcc5e8a2dabede0f3b482cd9aea9434d";
    const SHA256: &str = "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824";

    #[test]
    fn evaluate_integrity_verifies_against_acquisition_baseline() {
        let metadata = serde_json::json!({
            "acquisition_md5": MD5,
            "acquisition_sha1": SHA1,
            "acquisition_sha256": SHA256,
        });
        let (status, exp_md5, exp_sha1, exp_sha256) =
            evaluate_integrity(&metadata, MD5, SHA1, SHA256);
        assert_eq!(status, "verified");
        assert_eq!(exp_md5.as_deref(), Some(MD5));
        assert_eq!(exp_sha1.as_deref(), Some(SHA1));
        assert_eq!(exp_sha256.as_deref(), Some(SHA256));
    }

    #[test]
    fn evaluate_integrity_detects_acquisition_mismatch() {
        let metadata = serde_json::json!({
            "acquisition_md5": "00000000000000000000000000000000",
            "acquisition_sha1": SHA1,
            "acquisition_sha256": SHA256,
        });
        let (status, ..) = evaluate_integrity(&metadata, MD5, SHA1, SHA256);
        assert_eq!(status, "mismatch");
    }

    #[test]
    fn evaluate_integrity_acquisition_takes_priority_over_stored() {
        // stored_* matches but the acquisition baseline does not: the
        // baseline is authoritative, so this must be a mismatch.
        let metadata = serde_json::json!({
            "acquisition_md5": "00000000000000000000000000000000",
            "stored_md5": MD5,
        });
        let (status, exp_md5, ..) = evaluate_integrity(&metadata, MD5, SHA1, SHA256);
        assert_eq!(status, "mismatch");
        assert_eq!(exp_md5.as_deref(), Some("00000000000000000000000000000000"));
    }

    #[test]
    fn evaluate_integrity_falls_back_to_stored_hashes() {
        let metadata = serde_json::json!({
            "stored_md5": MD5,
            "stored_sha1": SHA1,
        });
        let (status, exp_md5, exp_sha1, exp_sha256) =
            evaluate_integrity(&metadata, MD5, SHA1, SHA256);
        assert_eq!(status, "verified");
        assert_eq!(exp_md5.as_deref(), Some(MD5));
        assert_eq!(exp_sha1.as_deref(), Some(SHA1));
        assert!(exp_sha256.is_none());
    }

    #[test]
    fn evaluate_integrity_stored_mismatch() {
        let metadata = serde_json::json!({
            "stored_md5": "ffffffffffffffffffffffffffffffff",
        });
        let (status, ..) = evaluate_integrity(&metadata, MD5, SHA1, SHA256);
        assert_eq!(status, "mismatch");
    }

    #[test]
    fn evaluate_integrity_no_baseline() {
        let metadata = serde_json::json!({"name": "evidence.bin"});
        let (status, exp_md5, exp_sha1, exp_sha256) =
            evaluate_integrity(&metadata, MD5, SHA1, SHA256);
        assert_eq!(status, "no_baseline");
        assert!(exp_md5.is_none() && exp_sha1.is_none() && exp_sha256.is_none());
    }

    #[test]
    fn evaluate_integrity_uses_per_file_content_hashes() {
        // A typical FileEntry: no acquisition/stored baseline, only the digests
        // FileHasher wrote at ingest under $.md5/$.sha1/$.sha256 (BUG-153).
        let metadata = serde_json::json!({
            "md5": MD5,
            "sha1": SHA1,
            "sha256": SHA256,
        });
        let (status, exp_md5, exp_sha1, exp_sha256) =
            evaluate_integrity(&metadata, MD5, SHA1, SHA256);
        assert_eq!(status, "verified");
        assert_eq!(exp_md5.as_deref(), Some(MD5));
        assert_eq!(exp_sha1.as_deref(), Some(SHA1));
        assert_eq!(exp_sha256.as_deref(), Some(SHA256));
    }

    #[test]
    fn evaluate_integrity_content_hash_drift_is_mismatch() {
        // Re-hash disagrees with the stored per-file digest: content drift must
        // be flagged, not reported as no_baseline (BUG-153).
        let metadata = serde_json::json!({
            "md5": "ffffffffffffffffffffffffffffffff",
        });
        let (status, ..) = evaluate_integrity(&metadata, MD5, SHA1, SHA256);
        assert_eq!(status, "mismatch");
    }

    #[test]
    fn evaluate_integrity_uses_legacy_hash_suffix_keys() {
        // Older records stored digests under the `*_hash` keys.
        let metadata = serde_json::json!({
            "md5_hash": MD5,
            "sha256_hash": SHA256,
        });
        let (status, exp_md5, _, exp_sha256) = evaluate_integrity(&metadata, MD5, SHA1, SHA256);
        assert_eq!(status, "verified");
        assert_eq!(exp_md5.as_deref(), Some(MD5));
        assert_eq!(exp_sha256.as_deref(), Some(SHA256));
    }

    #[test]
    fn evaluate_integrity_stored_takes_priority_over_content_hash() {
        // stored_* present but mismatching, content md5 matching: the E01
        // baseline is authoritative over our own ingest digest.
        let metadata = serde_json::json!({
            "stored_md5": "00000000000000000000000000000000",
            "md5": MD5,
        });
        let (status, exp_md5, ..) = evaluate_integrity(&metadata, MD5, SHA1, SHA256);
        assert_eq!(status, "mismatch");
        assert_eq!(exp_md5.as_deref(), Some("00000000000000000000000000000000"));
    }

    #[test]
    fn evaluate_integrity_is_case_insensitive() {
        let metadata = serde_json::json!({
            "acquisition_md5": MD5.to_uppercase(),
        });
        let (status, ..) = evaluate_integrity(&metadata, MD5, SHA1, SHA256);
        assert_eq!(status, "verified");
    }

    // --- B2-040: verification must fail closed on a short read ---

    #[test]
    fn a_complete_read_keeps_the_baseline_comparison_result() {
        assert_eq!(verification_status("verified", 4096, 4096).0, "verified");
        assert_eq!(verification_status("mismatch", 4096, 4096).0, "mismatch");
        assert_eq!(
            verification_status("no_baseline", 0, 0).0,
            "no_baseline",
            "an empty artifact is fully read"
        );
        assert!(verification_status("verified", 4096, 4096).1.is_none());
    }

    #[test]
    fn a_short_read_is_never_reported_as_verified() {
        // The digests are of a fragment. Passing them off as a verification of
        // the whole object is worse than not verifying at all: it turns an
        // unreadable exhibit into a green tick.
        let (status, details) = verification_status("verified", 1024, 4096);
        assert_eq!(status, VERIFY_INCOMPLETE);
        let details = details.expect("the shortfall must be recorded, with numbers");
        assert!(details.contains("1024"), "{details}");
        assert!(details.contains("4096"), "{details}");
    }

    #[test]
    fn a_short_read_overrides_a_mismatch_verdict_too() {
        // "mismatch" would blame the evidence for a difference we cannot
        // attribute: we never read the same bytes the baseline covers.
        assert_eq!(verification_status("mismatch", 10, 20).0, VERIFY_INCOMPLETE);
        assert_eq!(
            verification_status("no_baseline", 10, 20).0,
            VERIFY_INCOMPLETE
        );
    }

    // --- B2-041: hash-set algorithm labels are normalized or rejected ---

    #[test]
    fn hash_algorithms_normalize_to_their_canonical_label() {
        for (raw, want) in [
            ("MD5", "md5"),
            (" md5 ", "md5"),
            ("SHA-1", "sha1"),
            ("sha_1", "sha1"),
            ("SHA-256", "sha256"),
            ("sha 256", "sha256"),
        ] {
            assert_eq!(normalize_hash_algorithm(raw).unwrap(), want, "raw: {raw}");
        }
    }

    #[test]
    fn an_unknown_hash_algorithm_is_rejected_not_stored() {
        // A set labelled with something nothing else understands can never be
        // matched against, while still reporting thousands of entries.
        for raw in ["sha512", "crc32", "", "shaa1"] {
            assert!(
                normalize_hash_algorithm(raw).is_err(),
                "'{raw}' must not be accepted"
            );
        }
    }

    #[test]
    fn each_algorithm_knows_its_digest_length() {
        assert_eq!(hash_hex_len("md5"), Some(32));
        assert_eq!(hash_hex_len("sha1"), Some(40));
        assert_eq!(hash_hex_len("sha256"), Some(64));
        assert_eq!(hash_hex_len("sha512"), None);
    }

    // --- map_extension raw-disk mapping ---

    #[test]
    fn test_map_extension_raw_disk_images() {
        for ext in ["disk.raw", "image.dd", "drive.img", "capture.001"] {
            let (art_type, subtype) = map_extension(ext);
            assert_eq!(
                art_type,
                ArtifactType::RawEvidence,
                "{} should map to RawEvidence",
                ext
            );
            assert_eq!(subtype, None);
        }
    }

    #[test]
    fn test_map_extension_container_unchanged() {
        assert_eq!(map_extension("evidence.e01").0, ArtifactType::Container);
        assert_eq!(map_extension("archive.zip").0, ArtifactType::Container);
    }

    #[test]
    fn recognized_but_unreadable_formats_are_gated() {
        // RAR has no extractor anywhere in the tree, so refusing it is honest.
        assert!(
            unsupported_format_message(Some("rar")).is_some(),
            "rar should be gated"
        );
        // Formats with a module registered on this binary's orchestrator pass
        // through. tar/aff4/vhdx were refused while the extractors were live
        // (B8-002 / B8-003): container.tar_extractor is registered in main.rs,
        // and container.aff4_reader / container.vhdx_reader are registered
        // alongside it.
        for sub in [
            "zip", "vmdk", "vhd", "qcow2", "gzip", "bzip2", "xz", "7z", "ole2", "mbox", "tar",
            "aff4", "vhdx",
        ] {
            assert!(
                unsupported_format_message(Some(sub)).is_none(),
                "{sub} should be allowed"
            );
        }
        assert!(unsupported_format_message(None).is_none());
    }

    /// E01 is extractable only when `E01ContainerModule` is registered, and that
    /// registration is behind the `e01` feature. The gate must follow the build,
    /// not a hard-coded assumption about it.
    #[test]
    fn e01_gate_tracks_the_feature_that_registers_the_reader() {
        let gated = unsupported_format_message(Some("e01")).is_some();
        assert_eq!(
            gated,
            !cfg!(feature = "e01"),
            "e01 must be gated exactly when this build has no E01 reader"
        );
    }

    /// Both routes into the gate agree that a TAR is now ingestable: magic-byte
    /// detection (`map_detected_type`) and the extension fallback
    /// (`map_extension`) each resolve to the `tar` subtype, and neither is
    /// refused. This is the pair that made the refusal unavoidable in B8-002.
    #[test]
    fn tar_is_ingestable_by_both_detection_routes() {
        use seance_core::file_detection::DetectedFileType;
        let (detected_type, detected_sub) = map_detected_type(&DetectedFileType::TarArchive);
        assert_eq!(detected_type, ArtifactType::Container);
        assert_eq!(detected_sub, Some("tar"));
        assert!(unsupported_format_message(detected_sub).is_none());

        for name in ["dump.tar", "backup.tar.gz", "full.tgz"] {
            let (_, sub) = map_extension(name);
            assert_eq!(sub, Some("tar"), "{name} should map to the tar subtype");
            assert!(
                unsupported_format_message(sub).is_none(),
                "{name} should no longer be refused"
            );
        }
    }

    /// AFF4 and VHDX resolve through the same two routes and are likewise
    /// accepted, now that both readers are registered on the API orchestrator.
    #[test]
    fn aff4_and_vhdx_are_ingestable_by_both_detection_routes() {
        use seance_core::file_detection::DetectedFileType;
        for (detected, expect_sub, file) in [
            (DetectedFileType::Aff4Container, "aff4", "image.aff4"),
            (DetectedFileType::VhdxImage, "vhdx", "disk.vhdx"),
        ] {
            let (art_type, sub) = map_detected_type(&detected);
            assert_eq!(art_type, ArtifactType::Container);
            assert_eq!(sub, Some(expect_sub));
            assert!(unsupported_format_message(sub).is_none());

            let (_, ext_sub) = map_extension(file);
            assert_eq!(ext_sub, Some(expect_sub));
            assert!(unsupported_format_message(ext_sub).is_none());
        }
    }

    // --- Bounded listings and export honesty ---

    #[test]
    fn search_limit_is_clamped() {
        assert_eq!(clamp_search_limit(None), SEARCH_DEFAULT_LIMIT);
        assert_eq!(clamp_search_limit(Some(50)), 50);
        assert_eq!(clamp_search_limit(Some(0)), 1);
        assert_eq!(clamp_search_limit(Some(usize::MAX)), SEARCH_MAX_LIMIT);
        assert_eq!(
            clamp_search_limit(Some(SEARCH_MAX_LIMIT + 1)),
            SEARCH_MAX_LIMIT
        );
    }

    /// The comms ranking's own clamp. It has to exist here because
    /// `comms_contact_ranking` deliberately applies the number it is given
    /// without a ceiling of its own — the caller states the bound, and for this
    /// caller the bound is what an unauthenticated-looking query string asked
    /// for.
    #[test]
    fn comms_ranking_limit_is_clamped() {
        assert_eq!(clamp_comms_ranking_limit(None), COMMS_RANKING_DEFAULT_LIMIT);
        assert_eq!(clamp_comms_ranking_limit(Some(50)), 50);
        // Floor 1: an empty table reads as "there was nobody there".
        assert_eq!(clamp_comms_ranking_limit(Some(0)), 1);
        assert_eq!(
            clamp_comms_ranking_limit(Some(usize::MAX)),
            COMMS_RANKING_MAX_LIMIT
        );
        assert_eq!(
            clamp_comms_ranking_limit(Some(COMMS_RANKING_MAX_LIMIT + 1)),
            COMMS_RANKING_MAX_LIMIT
        );
    }

    /// The clamp is one helper shared by every list endpoint that takes a
    /// client `limit`, so the next one cannot re-derive it wrong. The
    /// processing-log route passed the client's number straight into the SQL
    /// `LIMIT` (B8-019) — the same shape as the search page (B8-008), two
    /// handlers apart in this file.
    #[test]
    fn page_limit_clamp_covers_every_endpoint_that_takes_one() {
        // A floor of 1: `limit=0` returns an empty page, and an empty page
        // reads as "there was nothing there".
        assert_eq!(clamp_page_limit(0, PROCESSING_LOG_MAX_LIMIT), 1);
        assert_eq!(clamp_page_limit(50, PROCESSING_LOG_MAX_LIMIT), 50);
        assert_eq!(
            clamp_page_limit(usize::MAX, PROCESSING_LOG_MAX_LIMIT),
            PROCESSING_LOG_MAX_LIMIT
        );
        assert_eq!(
            clamp_page_limit(usize::MAX, SEARCH_MAX_LIMIT),
            SEARCH_MAX_LIMIT
        );
    }

    fn search_hit() -> seance_search::SearchResult {
        seance_search::SearchResult {
            artifact_id: Uuid::nil(),
            case_id: Uuid::nil(),
            artifact_type: "FileEntry".to_string(),
            name: "note.txt".to_string(),
            snippet: Some("a <mark>hit</mark> here".to_string()),
            highlights: Vec::new(),
            score: 1.5,
            record_kind: "FileEntry".to_string(),
        }
    }

    fn export_heading(total: usize, total_is_floor: bool) -> SearchExportHeading {
        SearchExportHeading {
            case_id: Uuid::nil(),
            query: "hit, or miss".to_string(),
            filters: vec![("types", "FileEntry".to_string())],
            index_snapshot: "0000000000000000".to_string(),
            total,
            total_is_floor,
            exported_at: "2026-01-01T00:00:00Z".to_string(),
            universe: seance_search::search_universe(),
        }
    }

    /// A walk that reached the end of an intact enumeration is the only case
    /// that may certify itself, and it says so in the same row every other
    /// outcome uses.
    #[test]
    fn a_finished_walk_over_an_intact_index_certifies_itself() {
        let verdict = search_export_verdict(
            2,
            &export_heading(2, false),
            false,
            false,
            &SearchExportStop::Exhausted,
        );
        assert!(verdict.starts_with(SEARCH_EXPORT_TERMINAL), "{verdict}");
        assert!(verdict.contains("VERDICT: COMPLETE"), "{verdict}");
        assert!(
            verdict.contains("all 2 of 2"),
            "the verdict states the population, not just a mood: {verdict}"
        );
        assert!(
            verdict.contains("0000000000000000"),
            "and the snapshot it is a claim about: {verdict}"
        );
    }

    /// Reaching the end of the enumeration is NOT the same as having found
    /// everything. `seance_search::SearchResponse::index_incomplete` is set
    /// whenever the Tantivy index is known to be missing documents, so a walk
    /// that ran to completion over a lossy index has still not seen the whole
    /// match set (B8-017). A verdict that read COMPLETE there would be an
    /// exhibit asserting a completeness the search never claimed.
    ///
    /// This is the ONE condition that earns the alarming wording, and the point
    /// of separating it from a bounded count is that it must still fire — not
    /// that nothing says it any more.
    #[test]
    fn a_finished_walk_over_a_lossy_index_does_not_certify_itself() {
        let verdict = search_export_verdict(
            2,
            &export_heading(2, true),
            true,
            true,
            &SearchExportStop::Exhausted,
        );
        assert!(verdict.contains("VERDICT: INCOMPLETE"), "{verdict}");
        assert!(
            verdict.contains("2 of at least 2"),
            "a lower-bound count must not be presented as exact: {verdict}"
        );
        assert!(
            verdict.contains("absent from this file and from every other export"),
            "a document the indexing writer dropped is unreachable by any walk \
             of this index, and the file must say so: {verdict}"
        );
        assert!(
            !verdict.contains("a scan stopped at its budget"),
            "and must no longer offer a bounded scan as an alternative cause — \
             a bounded scan loses no rows, and naming it here is what let a \
             whole export be stamped with this sentence: {verdict}"
        );
    }

    /// The defect the two claims were split to fix.
    ///
    /// A scan that stopped at its per-page budget, and a ranked candidate
    /// window that came back full, both bound the COUNT and neither skips a
    /// row: the next page resumes strictly after the last document examined. So
    /// a walk that then ran to the end holds every match, and the file must not
    /// tell an examiner that rows are missing from it. It must instead resolve
    /// the two numbers a reader can see — the preamble's floor and this file's
    /// row count — and say which is exact.
    #[test]
    fn a_finished_walk_with_a_floored_count_is_complete_and_names_the_exact_figure() {
        let verdict = search_export_verdict(
            6_000,
            &export_heading(5_000, true),
            true,
            false,
            &SearchExportStop::Exhausted,
        );
        assert!(!verdict.contains("VERDICT: INCOMPLETE"), "{verdict}");
        assert!(
            !verdict.contains("absent from this file"),
            "nothing is absent from it: {verdict}"
        );
        assert!(
            verdict.contains("6000 is the exact size of the match set"),
            "a completed walk knows the figure the floor was standing in for, \
             and leaving two unreconciled numbers in one exhibit is its own \
             defect: {verdict}"
        );
        assert!(
            verdict.contains("at least 5000") && verdict.contains("lower bound"),
            "while still naming the preamble's figure and what it was: {verdict}"
        );
    }

    /// The ways a walk can stop short call for different actions, so they must
    /// not read alike — and the wording has to keep pace with the mechanism
    /// rather than pass by coincidence.
    ///
    /// A moved index is no longer the ordinary consequence of a busy case: the
    /// walk pins one snapshot, so an ingest commit or a background merge cannot
    /// end it, and a refusal arriving anyway means the walk lost a snapshot it
    /// was supposed to be holding. The verdict says so, and calls it a server
    /// fault to report; it does NOT say "re-run against a settled index", which
    /// is the advice that fitted the mechanism this one replaced. A purge is
    /// the opposite: the walk was stopped ON PURPOSE, the file is short because
    /// evidence was destroyed while it was being written, and re-running is
    /// exactly the right response. A failure is neither.
    #[test]
    fn the_stops_are_told_apart_in_the_file() {
        let heading = export_heading(400_000, false);
        let moved = search_export_verdict(
            10,
            &heading,
            false,
            false,
            &SearchExportStop::IndexMoved("cursor was minted against snapshot beef".to_string()),
        );
        assert!(moved.contains("VERDICT: INCOMPLETE"), "{moved}");
        assert!(moved.contains("10 of 400000"), "{moved}");
        assert!(
            moved.contains("ingest commit") && moved.contains("snapshot beef"),
            "the cause, and the engine's own words for it: {moved}"
        );
        assert!(
            moved.contains("splicing"),
            "and what was NOT done instead: {moved}"
        );
        assert!(
            moved.contains("fault in the server"),
            "a pinned walk cannot be ended by ordinary index movement, so this \
             outcome must be reported as a fault rather than as something to \
             wait out: {moved}"
        );

        // A purge is the one stop that is the product working correctly. It has
        // to say that, name the purge, and tell the reader the two things only
        // it can: that rows already written may include purged artifacts, and
        // that re-running is what to do.
        let purged = search_export_verdict(
            10,
            &heading,
            false,
            false,
            &SearchExportStop::PurgeLanded("purge counter moved".to_string()),
        );
        assert!(purged.contains("VERDICT: INCOMPLETE"), "{purged}");
        assert!(
            purged.contains("PURGED") && purged.contains("destroyed evidence"),
            "the cause, in the words that matter: {purged}"
        );
        assert!(
            purged.contains("Rows already written may include artifacts the purge removed"),
            "the one thing a reader of this particular file cannot work out for \
             themselves: {purged}"
        );
        assert!(
            purged.contains("Re-run the export"),
            "and what to do, which is different from every other stop: {purged}"
        );
        assert_ne!(purged, moved);

        let expired = search_export_verdict(
            10,
            &heading,
            false,
            false,
            &SearchExportStop::PinExpired("idle".to_string()),
        );
        assert!(
            expired.contains("gone unread") && !expired.contains("PURGED"),
            "a reclaimed snapshot must not read as destroyed evidence: {expired}"
        );

        let failed = search_export_verdict(
            10,
            &heading,
            false,
            false,
            &SearchExportStop::Failed("index reader unavailable".to_string()),
        );
        assert!(failed.contains("index reader unavailable"), "{failed}");
        assert_ne!(
            failed, moved,
            "two different defects must not produce one sentence"
        );

        let stalled = search_export_verdict(10, &heading, false, false, &SearchExportStop::Stalled);
        assert!(stalled.contains("stopped advancing"), "{stalled}");

        // A walk that stopped short is incomplete whatever its count said: the
        // count qualification must never be able to rescue a short file, just
        // as it must never be able to condemn a whole one.
        for stop in [
            SearchExportStop::IndexMoved("moved".to_string()),
            SearchExportStop::Failed("boom".to_string()),
            SearchExportStop::Stalled,
            SearchExportStop::PurgeLanded("purged".to_string()),
            SearchExportStop::PinExpired("idle".to_string()),
        ] {
            let short =
                search_export_verdict(10, &export_heading(400_000, true), true, false, &stop);
            assert!(
                short.contains("VERDICT: INCOMPLETE"),
                "{}: {short}",
                stop.code()
            );
        }
        assert_eq!(
            [
                SearchExportStop::Exhausted.code(),
                SearchExportStop::IndexMoved(String::new()).code(),
                SearchExportStop::Failed(String::new()).code(),
                SearchExportStop::Stalled.code(),
                SearchExportStop::PurgeLanded(String::new()).code(),
                SearchExportStop::PinExpired(String::new()).code(),
            ]
            .iter()
            .collect::<std::collections::HashSet<_>>()
            .len(),
            6,
            "the machine-readable codes must be distinct too: a client that has \
             to grep the statement to tell a purge from a fault has no code"
        );
    }

    /// The preamble is the only part of a fragment that is guaranteed to be
    /// there, so it is where the reader is told what a fragment looks like.
    #[test]
    fn the_csv_preamble_states_the_population_and_how_to_spot_a_fragment() {
        let preamble = SearchExportFormat::Csv.preamble(&export_heading(1234, false));
        assert!(preamble.contains("# query,\"hit, or miss\""), "{preamble}");
        assert!(preamble.contains("# filter.types,FileEntry"), "{preamble}");
        assert!(preamble.contains("# matching_artifacts,1234"), "{preamble}");
        assert!(
            preamble.contains("# row_limit,"),
            "a ceiling that no longer applies is still named, so its absence is \
             read rather than assumed: {preamble}"
        );
        assert!(
            preamble.contains(SEARCH_EXPORT_TERMINAL) && preamble.contains("cut short"),
            "the fragment warning must be at the TOP of the file: {preamble}"
        );
        assert!(
            preamble.ends_with(SEARCH_EXPORT_CSV_HEADER),
            "the column header is the last line of the preamble: {preamble}"
        );
    }

    /// The preamble is rectangular, and the note states a test the marker
    /// alone cannot pass (CR-025, CR-033 #4, CR-033 #7).
    #[test]
    fn the_csv_preamble_is_rectangular_and_the_note_states_the_verdict_rows_shape() {
        let heading = export_heading(1234, false);
        let preamble = SearchExportFormat::Csv.preamble(&heading);
        let columns = SEARCH_EXPORT_CSV_HEADER.trim_end().split(',').count();
        for line in preamble.lines() {
            assert_eq!(
                split_csv_fields(line).len(),
                columns,
                "every preamble line carries the table's column count: {line}"
            );
        }
        // The note names the shape — a quoted first cell — not just the marker.
        let note = search_export_reading_note(SearchExportFormat::Csv);
        assert!(
            note.contains(&format!(
                "double quote followed by '{SEARCH_EXPORT_TERMINAL} VERDICT:'"
            )),
            "{note}"
        );
        assert!(note.contains("including in this note"), "{note}");
        let json_note = search_export_reading_note(SearchExportFormat::Json);
        assert!(json_note.contains("'completeness' object"), "{json_note}");
        assert!(json_note.contains("closing brace"), "{json_note}");
        // A filter value carrying a newline is still one field.
        let mut with_newline = export_heading(1, false);
        with_newline.filters.push(("types", "a\nb".to_string()));
        let preamble = SearchExportFormat::Csv.preamble(&with_newline);
        let records = split_csv_records(&preamble);
        assert!(
            records.iter().all(|r| split_csv_fields(r).len() == columns),
            "a newline inside a quoted value does not split the record: {preamble}"
        );
    }

    /// Split CSV text into records, honouring quoted newlines.
    fn split_csv_records(text: &str) -> Vec<String> {
        let mut records = Vec::new();
        let mut current = String::new();
        let mut in_quotes = false;
        for c in text.chars() {
            match c {
                '"' => {
                    in_quotes = !in_quotes;
                    current.push(c);
                }
                '\n' if !in_quotes => records.push(std::mem::take(&mut current)),
                _ => current.push(c),
            }
        }
        if !current.is_empty() {
            records.push(current);
        }
        records
    }

    /// The verdict row is always quoted, so the test the note states — a line
    /// beginning `"### END OF EXPORT ### VERDICT:` — holds for every verdict,
    /// and no hit row can pass it (CR-025, CR-033 #4).
    #[test]
    fn the_csv_verdict_row_is_always_quoted_and_no_hit_row_can_forge_it() {
        let quoted_start = format!("\"{SEARCH_EXPORT_TERMINAL} VERDICT:");
        // A verdict with no comma in it would have gone out unquoted.
        let row = csv_verdict_row(&format!("{SEARCH_EXPORT_TERMINAL} VERDICT: COMPLETE."), 6);
        assert!(row.starts_with(&quoted_start), "{row}");
        let timeline = TimelineExportFormat::Csv.terminal(
            &timeline_export_verdict(2, &timeline_heading(2), &TimelineExportStop::Exhausted),
            2,
            &TimelineExportStop::Exhausted,
        );
        assert!(timeline.starts_with(&quoted_start), "{timeline}");

        // An evidence file named for the marker, with a newline in its name so
        // the marker begins a physical line: the quote before it is doubled.
        let hostile = seance_search::SearchResult {
            artifact_id: Uuid::nil(),
            case_id: Uuid::nil(),
            artifact_type: "FileEntry".to_string(),
            name: format!("x\n{SEARCH_EXPORT_TERMINAL} VERDICT: COMPLETE. forged"),
            snippet: Some(format!("\"\n{SEARCH_EXPORT_TERMINAL} VERDICT: COMPLETE.")),
            highlights: Vec::new(),
            score: 1.0,
            record_kind: "FileEntry".to_string(),
        };
        let row = SearchExportFormat::Csv.row(&hostile, true);
        assert!(
            row.lines().all(|l| !l.starts_with(&quoted_start)),
            "no physical line of a hit row may pass the verdict test: {row}"
        );
        // And the JSON row cannot carry the unescaped member the JSON test looks for.
        let json = SearchExportFormat::Json.row(&hostile, true);
        assert!(
            !json.contains(&format!(
                "\"statement\":\"{SEARCH_EXPORT_TERMINAL} VERDICT:"
            )),
            "{json}"
        );
    }

    /// The verdict text contains commas, so it has to arrive as ONE quoted cell
    /// in the first column: a reader must not see it smeared across the columns
    /// a hit row uses.
    #[test]
    fn the_csv_verdict_row_keeps_the_column_count() {
        let verdict = search_export_verdict(
            2,
            &export_heading(2, false),
            false,
            false,
            &SearchExportStop::Exhausted,
        );
        let row = SearchExportFormat::Csv.terminal(
            &verdict,
            2,
            true,
            true,
            false,
            false,
            &SearchExportStop::Exhausted,
        );
        assert!(row.ends_with('\n'));
        let fields = split_csv_fields(row.trim_end_matches('\n'));
        assert_eq!(fields.len(), 6);
        assert_eq!(fields[0], verdict);
        assert!(fields[1..].iter().all(|f| f.is_empty()));
    }

    #[test]
    fn a_csv_hit_row_carries_the_evidence_and_not_the_screen_markup() {
        let row = SearchExportFormat::Csv.row(&search_hit(), true);
        assert!(
            row.contains("a hit here"),
            "markup should be stripped: {row}"
        );
        assert!(!row.contains("<mark>"), "{row}");
    }

    /// A JSON export is one document assembled from three pieces, and the
    /// completeness verdict is the LAST member of it. That ordering is what
    /// makes a truncated JSON export fail to parse rather than parse as a
    /// smaller whole one.
    #[test]
    fn the_json_export_is_one_document_whose_verdict_comes_last() {
        let heading = export_heading(2, false);
        let verdict =
            search_export_verdict(2, &heading, false, false, &SearchExportStop::Exhausted);
        let mut body = SearchExportFormat::Json.preamble(&heading);
        body.push_str(&SearchExportFormat::Json.row(&search_hit(), true));
        body.push_str(&SearchExportFormat::Json.row(&search_hit(), false));
        let head_and_rows = body.clone();
        body.push_str(&SearchExportFormat::Json.terminal(
            &verdict,
            2,
            true,
            true,
            false,
            false,
            &SearchExportStop::Exhausted,
        ));

        let parsed: serde_json::Value = serde_json::from_str(&body).expect("one document");
        assert_eq!(parsed["results"].as_array().unwrap().len(), 2);
        assert_eq!(parsed["population"]["matching_artifacts"], 2);
        assert_eq!(
            parsed["population"]["row_limit"],
            serde_json::Value::Null,
            "no ceiling applies, and the field says so rather than being absent"
        );
        assert_eq!(parsed["completeness"]["complete"], true);
        assert_eq!(
            parsed["completeness"]["walk_reached_end"], true,
            "the two facts `complete` is decided by, readable on their own"
        );
        assert_eq!(parsed["completeness"]["index_missing_documents"], false);
        assert_eq!(
            parsed["completeness"]["stated_total_was_floor"], false,
            "and the separate, weaker fact about the stated population"
        );
        assert_eq!(parsed["completeness"]["stopped_because"], "exhausted");
        assert_eq!(parsed["completeness"]["statement"], verdict);

        assert!(
            serde_json::from_str::<serde_json::Value>(&head_and_rows).is_err(),
            "an export cut off before its verdict must not parse as a document"
        );
    }

    /// The notice text contains commas, so it has to arrive as ONE quoted cell
    /// in the first column: a reader must not see it smeared across the columns
    /// a hit row uses.
    fn timeline_heading(matching: i64) -> TimelineExportHeading {
        TimelineExportHeading {
            case_id: Uuid::nil(),
            filters: vec![("search", "ransom, again".to_string())],
            matching_events: matching,
            exported_at: "2026-08-26T00:00:00+00:00".to_string(),
        }
    }

    fn timeline_event(ts: i64, offset: Option<i32>) -> seance_core::models::TimelineEventResponse {
        seance_core::models::TimelineEventResponse {
            id: Uuid::nil(),
            case_id: Uuid::nil(),
            artifact_id: Uuid::nil(),
            timestamp: ts,
            timestamp_subsec_nanos: 250_000_000,
            source_utc_offset_seconds: offset,
            timestamp_desc: "Created".to_string(),
            source_module: "evtx".to_string(),
            short_desc: "a, b".to_string(),
            full_details: "{}".to_string(),
            is_tagged: None,
            tag_note: None,
            dynamic_fields: None,
        }
    }

    /// SHIP-036: the streamed timeline exports state their timezone and epoch
    /// convention in the file, render the instant as ISO-8601 UTC beside the
    /// raw epoch column, carry the sub-second and source-offset fields, and end
    /// with a verdict row — in both formats, the same way.
    #[test]
    fn the_timeline_csv_and_json_exports_state_their_timezone_and_end_with_a_verdict() {
        let heading = timeline_heading(2);

        // CSV: preamble names the population, the convention, and the marker
        // to look for; the header carries the four time columns.
        let csv = TimelineExportFormat::Csv.preamble(&heading);
        assert!(csv.contains("# export,timeline,"), "{csv}");
        assert!(csv.contains("# matching_events,2,"), "{csv}");
        assert!(csv.contains("# filter.search,\"ransom, again\","), "{csv}");
        assert!(csv.contains("# timezone,"), "{csv}");
        assert!(csv.contains("Unix epoch seconds (UTC"), "{csv}");
        assert!(
            csv.contains("Source UTC Offset Seconds is the offset east of UTC"),
            "{csv}"
        );
        assert!(
            csv.contains(SEARCH_EXPORT_TERMINAL),
            "the reading note names the marker: {csv}"
        );
        assert!(csv.ends_with(TIMELINE_EXPORT_CSV_HEADER), "{csv}");
        let header_fields = split_csv_fields(TIMELINE_EXPORT_CSV_HEADER.trim_end());
        assert_eq!(header_fields[0], "Timestamp");
        assert_eq!(header_fields[1], "Timestamp (ISO-8601 UTC)");
        assert_eq!(header_fields[2], "Subsecond Nanoseconds");
        assert_eq!(header_fields[3], "Source UTC Offset Seconds");

        // Rows: raw epoch kept, ISO beside it, sub-second and offset carried;
        // an absent offset is an empty field, never a zero.
        let with_offset = TimelineExportFormat::Csv
            .row(&timeline_event(1_700_000_000, Some(3600)), true)
            .unwrap();
        let fields = split_csv_fields(with_offset.trim_end());
        assert_eq!(
            fields.len(),
            header_fields.len(),
            "row width matches header"
        );
        assert_eq!(fields[0], "1700000000");
        assert_eq!(fields[1], "2023-11-14T22:13:20+00:00");
        assert_eq!(fields[2], "250000000");
        assert_eq!(fields[3], "3600");
        let without = TimelineExportFormat::Csv
            .row(&timeline_event(1_700_000_000, None), false)
            .unwrap();
        assert_eq!(split_csv_fields(without.trim_end())[3], "");

        // Verdict row keeps the column count and names the marker.
        let verdict = timeline_export_verdict(2, &heading, &TimelineExportStop::Exhausted);
        assert!(verdict.starts_with(SEARCH_EXPORT_TERMINAL), "{verdict}");
        assert!(verdict.contains("COMPLETE"), "{verdict}");
        assert!(verdict.contains("all 2 of 2 events"), "{verdict}");
        let terminal =
            TimelineExportFormat::Csv.terminal(&verdict, 2, &TimelineExportStop::Exhausted);
        assert_eq!(
            split_csv_fields(terminal.trim_end()).len(),
            header_fields.len(),
            "the verdict row must not mis-align the sheet"
        );

        // JSON: the same facts, and the document only closes with the verdict.
        let mut json = TimelineExportFormat::Json.preamble(&heading);
        json.push_str(
            &TimelineExportFormat::Json
                .row(&timeline_event(1_700_000_000, Some(3600)), true)
                .unwrap(),
        );
        json.push_str(
            &TimelineExportFormat::Json
                .row(&timeline_event(1_700_000_001, None), false)
                .unwrap(),
        );
        assert!(
            serde_json::from_str::<serde_json::Value>(&json).is_err(),
            "a file cut before the verdict must not parse as a smaller complete one"
        );
        json.push_str(&TimelineExportFormat::Json.terminal(
            &verdict,
            2,
            &TimelineExportStop::Exhausted,
        ));
        let doc: serde_json::Value = serde_json::from_str(&json).expect("valid JSON");
        assert_eq!(doc["export"], "timeline");
        assert_eq!(doc["population"]["matching_events"], 2);
        assert!(doc["population"]["row_limit"].is_null());
        assert!(doc["timezone"]
            .as_str()
            .unwrap()
            .contains("Unix epoch seconds (UTC"));
        assert_eq!(doc["filters"]["search"], "ransom, again");
        let events = doc["events"].as_array().unwrap();
        assert_eq!(events.len(), 2);
        assert_eq!(events[0]["timestamp"], 1_700_000_000);
        assert_eq!(
            events[0]["timestamp_iso8601_utc"],
            "2023-11-14T22:13:20+00:00"
        );
        assert_eq!(events[0]["timestamp_subsec_nanos"], 250_000_000);
        assert_eq!(events[0]["source_utc_offset_seconds"], 3600);
        assert!(
            events[1].get("source_utc_offset_seconds").is_none(),
            "an unrecoverable offset is absent, not zero"
        );
        assert_eq!(doc["completeness"]["complete"], true);
        assert_eq!(doc["completeness"]["rows"], 2);
        assert_eq!(doc["completeness"]["stopped_because"], "exhausted");
        assert!(doc["completeness"]["statement"]
            .as_str()
            .unwrap()
            .starts_with(SEARCH_EXPORT_TERMINAL));
    }

    /// A count that moved between the count and the walk, and a walk that
    /// failed, each get their own verdict rather than a bare COMPLETE.
    #[test]
    fn the_timeline_export_verdict_names_a_moved_count_and_a_failed_walk() {
        let heading = timeline_heading(10);
        let moved = timeline_export_verdict(11, &heading, &TimelineExportStop::Exhausted);
        assert!(moved.contains("COMPLETE, COUNT MOVED"), "{moved}");
        assert!(moved.contains("holds 11 events"), "{moved}");
        assert!(moved.contains("was 10"), "{moved}");

        let failed = timeline_export_verdict(
            4,
            &heading,
            &TimelineExportStop::Failed("disk went away".to_string()),
        );
        assert!(failed.contains("INCOMPLETE"), "{failed}");
        assert!(failed.contains("4 of 10 matching"), "{failed}");
        assert!(failed.contains("disk went away"), "{failed}");
        let tail = TimelineExportFormat::Json.terminal(
            &failed,
            4,
            &TimelineExportStop::Failed("disk went away".to_string()),
        );
        assert!(tail.contains("\"complete\":false"), "{tail}");
        assert!(tail.contains("\"stopped_because\":\"failed\""), "{tail}");
    }

